RoleequipmentLocalData = {}
RoleequipmentLocalData.tab = {
[300000] = {300000, "百煉·千錘", "由露露啦所使用過的數千把戰錘熔煉而成。\n以一種無法用現有科學技術解析的方式增加著露露啦的力量，這其中的份量只有她自己知道吧。", "icon_lulula_zs1", "0", 4, 1, "3_{lv}*100", "露露啦", "1_110021_20", 10, "3_100", "300000,300001,300002", "0", "0", "0", "0", "0", "0", "0", "0"},
[300001] = {300001, "護臂·尖形鉤曲", "艾吉斯設計並製造的特製金屬護臂，相較於一味防守，這個護臂更傾向於消滅敵人以達成防禦的目的。\n把世界救濟，這就是這個護臂真正的含義。", "icon_lulula_zs2", "0", 4, 2, "3_{lv}*100", "露露啦", "1_110021_20", 10, "3_100", "300000,300001,300002", "0", "0", "0", "0", "0", "0", "0", "0"},
[300002] = {300002, "天隼", "艾吉斯為露露啦專門設計並製造的動力裝置，其內部整合了小型尼姆比斯反應堆，能夠為使用者提供大量動力。\n畢竟使用者揮舞一把沉重的武器，它的重量會隨著露露啦不斷地使用、損毀、再熔鑄而增加，而如何承載這份重量，是科學部最棘手的幾個問題之一。", "icon_lulula_zs3", "0", 4, 3, "3_{lv}*100", "露露啦", "1_110021_20", 10, "3_100", "300000,300001,300002", "0", "0", "0", "0", "0", "0", "0", "0"},
[300010] = {300010, "微瀾晨光", "應朱利烏斯的個人要求，在重劍上安裝了小型尼姆比斯反應堆。\n在解除限制的那一刻，其噴射的等離子體足以融化阻擋在它身前的任何事物。", "icon_zlws_zs1", "0", 4, 1, "3_{lv}*100", "朱利烏斯", "1_110021_20", 10, "3_100", "300010,300011,300012", "0", "0", "0", "0", "0", "0", "0", "0"},
[300011] = {300011, "純白護胄", "艾吉斯設計並製造的特製盾牌，其防禦力足以抵擋戰斧式導彈的正面轟擊。\n如果護臂上的盾牌不足以抗下敵人的攻擊，朱利烏斯一定會用身軀來阻擋攻擊的吧？所以我製造護臂的時候特意強化了這方面的功能，感覺壓力很大。——接觸過朱利烏斯的科研人員如此表示。", "icon_zlws_zs2", "0", 4, 2, "3_{lv}*100", "朱利烏斯", "1_110021_20", 10, "3_100", "300010,300011,300012", "0", "0", "0", "0", "0", "0", "0", "0"},
[300012] = {300012, "白鳶", "艾吉斯設計並製造的動力裝置，其內部整合了小型尼姆比斯反應堆，能夠為使用者提供大量動力。\n伴隨著朱利烏斯護胄的特殊功能，動力裝置的製作需求也被提上日程，簡直是給自己增加工作量。——一位科研部的同事如此評論道。", "icon_zlws_zs3", "0", 4, 3, "3_{lv}*100", "朱利烏斯", "1_110021_20", 10, "3_100", "300010,300011,300012", "0", "0", "0", "0", "0", "0", "0", "0"},
[300020] = {300020, "乞食者", "由高密度的合金和大量的尼姆比斯結晶打造而成，擁有調節其自身重力、改變自身形狀的功能。\n“雖然說，武器的名字叫乞食者，但其實我是靠著這件武器才有飯吃的嘛……我才是那個乞食的人才對。”", "icon_hanke_zs1", "0", 2, 1, "3_{lv}*100", "漢克", "1_110021_5", 10, "3_100", "300020,300021,300022", "0", "0", "0", "0", "0", "0", "0", "0"},
[300021] = {300021, "偏移力場", "裝有小型推進裝置和腿刃，是一款輸出與防禦齊備的裝甲。\n只需要稍微偏移對方的彈道即可，這微妙的偏移角度足以奪去對面的生命。", "icon_hanke_zs2", "0", 2, 2, "1_{lv}*100", "漢克", "1_110021_5", 10, "1_100", "300020,300021,300022", "0", "0", "0", "0", "0", "0", "0", "0"},
[300022] = {300022, "均衡天平", "以超強的平衡性能和機動能力著稱的飛行裝備。\n漢克對飛行裝備的穩定、機動有著非常扭曲的訴求……姑且認為這是久經沙場之人對裝備的敏銳嗅覺。", "icon_hanke_zs3", "0", 2, 3, "1_{lv}*100", "漢克", "1_110021_5", 10, "1_100", "300020,300021,300022", "0", "0", "0", "0", "0", "0", "0", "0"},
[300030] = {300030, "鬼之牙", "由九州總部製作的近戰兵器，該武器擁有長槍和三叉倆種形態。\n【牙】對使用者的要求極高，它是某位科研人員腦袋一熱完全不考慮使用者而製作的，如果不是鬼之介，也許它會一直躺在裝備庫裡吧。", "icon_sencunguizhijie_zs1", "0", 2, 1, "3_{lv}*100", "森村鬼之介", "1_110021_5", 10, "3_100", "300030,300031,300032", "0", "0", "0", "0", "0", "0", "0", "0"},
[300031] = {300031, "鬼之角", "由九州總部製作的精神力控制裝置，該裝置上融入了高密度的尼姆比斯結晶體，在戰鬥中會大幅度的提高AVG的共鳴數據，但副作用極大。\n“能承受住這個的，是真正的鬼神吧？！”某位科研人員的早期作品。", "icon_sencunguizhijie_zs2", "0", 2, 2, "1_{lv}*100", "森村鬼之介", "1_110021_5", 10, "1_100", "300030,300031,300032", "0", "0", "0", "0", "0", "0", "0", "0"},
[300032] = {300032, "鬼之血鎧", "由九州總部製作的風林火山小隊專用裝甲，該裝甲擁有極高的防護且但重量極輕。\n為持【牙】配【角】者而定制的裝甲，“既然她承載了我們糟糕的設計想法，那就把這件裝備作為詛咒的贈禮吧，如果說【牙】和【角】代表著懵懂、開端，那這件裝備就是我們夢想的積澱。”", "icon_sencunguizhijie_zs3", "0", 2, 3, "3_{lv}*100", "森村鬼之介", "1_110021_5", 10, "3_100", "300030,300031,300032", "0", "0", "0", "0", "0", "0", "0", "0"},
[300040] = {300040, "定裁", "此為瑪雅支部製造的量產型B2機器人配備的通用近戰裝備。武器內部裝有動力引擎，通過旋轉來提高穿刺能力。\nD型會為了創造它們的神靈，將來敵盡數討伐。", "icon_b2_zs1", "0", 4, 1, "3_{lv}*100", "D型b2", "1_110021_20", 10, "3_100", "300040,300041,300042", "0", "0", "0", "0", "0", "0", "0", "0"},
[300041] = {300041, "黑天使", "此為瑪雅支部製造的量產型B2機器人配備的通用近戰裝備，擁有設立能量罩的能力，但對幻化核心的能量消耗極大。\n我們是【幽靈】，是守護人們安危的幽靈。", "icon_b2_zs2", "0", 4, 2, "3_{lv}*100", "D型b2", "1_110021_20", 10, "3_100", "300040,300041,300042", "0", "0", "0", "0", "0", "0", "0", "0"},
[300042] = {300042, "審判日", "此為瑪雅支部製造的量產型B2機器人配備的通用近戰裝備，通過消耗幻化核心的能量來提高機體的行動速度，擁有極高的爆發力，據說全力狀態下可達到超音速。\n在最後的審判日，我們將會迎來怎樣的結局？", "icon_b2_zs3", "0", 4, 3, "3_{lv}*100", "D型b2", "1_110021_20", 10, "3_100", "300040,300041,300042", "0", "0", "0", "0", "0", "0", "0", "0"},
[300050] = {300050, "太昊精金象鼻蟲", "由九州總部特研製的一種防護型機器人，雖然該裝置上沒有裝載特別厲害的火力裝備，但是擁有超運算的自動防衛系統。\n“這就是象鼻蟲……？小生還以為是真的什麼蟲子呢……”", "icon_hualian_zs1", "0", 3, 1, "3_{lv}*100", "華戀", "1_110021_10", 10, "3_100", "300050,300051,300052", "0", "0", "0", "0", "0", "0", "0", "0"},
[300051] = {300051, "顯聖歸一順風耳", "由九州總部特研製的一種通信裝置，造型看似簡單，卻擁有超強的信號穿透能力。\n“話說，咱們天華閣的裝備名字怎麼都這麼文縐縐的……”", "icon_hualian_zs2", "0", 3, 2, "3_{lv}*100", "華戀", "1_110021_10", 10, "3_100", "300050,300051,300052", "0", "0", "0", "0", "0", "0", "0", "0"},
[300052] = {300052, "混元萬裡遁行靴", "由九州總部特研製的一種動力裝備，外表酷似一雙布鞋，但是擁有重力和動力雙重系統。\n“小生就需要這種跑得快的裝備！能輕鬆追上敵人！”", "icon_hualian_zs3", "0", 3, 3, "1_{lv}*100", "華戀", "1_110021_10", 10, "1_100", "300050,300051,300052", "0", "0", "0", "0", "0", "0", "0", "0"},
[300060] = {300060, "光追", "該裝備是以上位原罪身體作為素材加工而成，在幻化核心的催化下生成的等離子光刃。可以輕易地切開任何堅硬的物質，且對能量消耗極低。\n如同它的名字一樣，揮舞它的時候，殘留的光會在劃過的地方留下光帶，仿佛光能在追逐著斧刃一般。", "icon_xiliwaerte_zs1", "0", 3, 1, "1_{lv}*100", "棲琳", "1_110021_10", 10, "1_100", "300060,300061,300062", "0", "0", "0", "0", "0", "0", "0", "0"},
[300061] = {300061, "山貓", "棲琳女士刪除了這段描述。\n外觀可愛且設計高端時尚，雖然在戰場上不一定能派上用場，但是棲林覺得穿著得體非常重要，心情好！才能更好的戰鬥。", "icon_xiliwaerte_zs2", "0", 3, 2, "3_{lv}*100", "棲琳", "1_110021_10", 10, "3_100", "300060,300061,300062", "0", "0", "0", "0", "0", "0", "0", "0"},
[300062] = {300062, "自律臂盾Ⅰ", "該裝甲上裝載自律AI，在受到攻擊時，會自動擋住要害的部位。\n因為棲琳在戰場上的活躍性，普通的臂盾已經失去了它的作用，這是添加了AI防護功能的新產品，話說……它真的能被稱之為臂盾嗎。", "icon_xiliwaerte_zs3", "0", 3, 3, "3_{lv}*100", "棲琳", "1_110021_10", 10, "3_100", "300060,300061,300062", "0", "0", "0", "0", "0", "0", "0", "0"},
[300070] = {300070, "遠航者", "由九州海軍兵器研究部製作的水上武器，裝有電能轉化系統，注入液體就能產生雷電，並能擁有發射功能，是一種遠近兼備的武器。\n據說科研人員拿到裝備製作需求的時候焦頭爛額了好久，因為海姬本人對裝備的需求只說了“像我在老家時用的魚叉那樣的就可以了”。", "icon_haiji_zs1", "0", 2, 1, "1_{lv}*100", "海姬", "1_110021_5", 10, "1_100", "300070,300071,300072", "0", "0", "0", "0", "0", "0", "0", "0"},
[300071] = {300071, "淑女型通信器二代", "由九州海軍兵器研究部製作的通信器，除了具備基本的通信功能外面，還裝備了探測雷達，可以檢索範圍2海里內的所有生物坐標。\n這件裝備的初代版本，不防水……不防水……", "icon_haiji_zs2", "0", 2, 2, "3_{lv}*100", "海姬", "1_110021_5", 10, "3_100", "300070,300071,300072", "0", "0", "0", "0", "0", "0", "0", "0"},
[300072] = {300072, "魚鱗", "由九州海軍兵器研究部製作的通用型防具，裝有自律防衛系統，可以自動抵擋來自正面的攻擊。\n海姬本人對這件裝備不太在意，因為在水中的她猶如回到了自己家，像遊魚一般的她，很難受到從正面發動的攻擊。", "icon_haiji_zs3", "0", 2, 3, "3_{lv}*100", "海姬", "1_110021_5", 10, "3_100", "300070,300071,300072", "0", "0", "0", "0", "0", "0", "0", "0"},
[300080] = {300080, "騎士微光", "由多瑙支部為多洛莉絲研發的裝備，由三個单位的足鈦打造的輕型防衛盾牌組合而成，在戰鬥中可以自由拆解，以達到戰術目的。\n這是小小騎士傳記的開始，年輕的騎士多洛莉絲踏上了征途。", "icon_duoluolisi_zs1", "0", 2, 1, "3_{lv}*100", "多洛莉絲", "1_110021_5", 10, "3_100", "300080,300081,300082", "0", "0", "0", "0", "0", "0", "0", "0"},
[300081] = {300081, "聆聽禱言", "由多瑙支部為多洛莉絲研發的裝備，該武裝除了配備了基本的防衛系統和通信系統，還加入了重力轉化系統，可以小幅度調節使用者的重力。\n放鬆你的精神聆聽禱言，這會使小小騎士的軀體更輕鬆，更靈活。", "icon_duoluolisi_zs2", "0", 2, 2, "3_{lv}*100", "多洛莉絲", "1_110021_5", 10, "3_100", "300080,300081,300082", "0", "0", "0", "0", "0", "0", "0", "0"},
[300082] = {300082, "約束本我", "由多瑙支部為多洛莉絲研發的裝備，該武裝擁有極高防護能力且不受溫度的影響，但重量出奇的高，是其他同款裝備的三倍。\n腳踏實地，即使走得很慢，但小小騎士的每一步都無邊扎實。", "icon_duoluolisi_zs3", "0", 2, 3, "3_{lv}*100", "多洛莉絲", "1_110021_5", 10, "3_100", "300080,300081,300082", "0", "0", "0", "0", "0", "0", "0", "0"},
[300090] = {300090, "裁决之镰", "该装备是一名沉迷魔法少女幻想的科学官研发出的第一代攻击型装备，装备采用神秘的“S”金属，据说该物质并不存于这个宇宙，因此现世的所有攻击方式都无法摧毁这件装备（出自该科学官之口，真实性有待考证）。\n另外该装备拥有将空气燃烧的能力，在挥舞的过程中，会带起5000度以上的蓝色光焰。", "icon_mogenlefei_zs1", "0", 4, 1, "1_{lv}*100", "摩根勒菲", "1_110021_20", 10, "1_100", "300090,300091,300092", "0", "0", "0", "0", "0", "0", "0", "0"},
[300091] = {300091, "肆维之线", "该装备是一名沉迷魔法少女幻想的科学官研发出的第一代辅助型装备，据说该装备拥有撕裂空间维度并与第四空间建立联系的能力（出自该科学官之口，真实性有待考证）。\n对使用者的要求是有童真的想象力才能发挥出它真正的力量。", "icon_mogenlefei_zs2", "0", 4, 2, "3_{lv}*100", "摩根勒菲", "1_110021_20", 10, "3_100", "300090,300091,300092", "0", "0", "0", "0", "0", "0", "0", "0"},
[300092] = {300092, "驱逐之翼", "该装备是一名沉迷魔法少女幻想的科学官研发出的第一代辅助型装备，装备是用足量的钛合金制作而成。\n并且加入了全新的光之遗赠系统（由该科学官命名），通过消耗幻化核心的能量来制造出虚拟光翼，除了对能量的消耗略高外，在速度和稳定性的数据上十分优异。\n这个系统到底是什么，犹未可知。", "icon_mogenlefei_zs3", "0", 4, 3, "1_{lv}*100", "摩根勒菲", "1_110021_20", 10, "1_100", "300090,300091,300092", "0", "0", "0", "0", "0", "0", "0", "0"},
[300100] = {300100, "騎士利刃", "由多瑙支部研發的裝備，該武裝由輕金屬製成，在確保一定殺傷力的同時重量上進行了有效的削減，能夠滿足高速戰鬥的需求。\n一度折斷過的利劍，如今重返屬於它的戰場。", "icon_alaita_zs1", "0", 3, 1, "3_{lv}*100", "阿萊塔", "1_110021_10", 10, "3_100", "300100,300101,300102", "0", "0", "0", "0", "0", "0", "0", "0"},
[300101] = {300101, "砥礪前行", "由多瑙支部為阿萊塔研發的裝備，採用高強度合金製造，該武裝擁有極高防護能力且不受溫度的影響，但重量出奇的高，是其他同款裝備的三倍。\n走錯路的代價是其他人的三倍，在你前行之前，先思考。", "icon_alaita_zs2", "0", 3, 2, "1_{lv}*100", "阿萊塔", "1_110021_10", 10, "1_100", "300100,300101,300102", "0", "0", "0", "0", "0", "0", "0", "0"},
[300102] = {300102, "信念感知", "由多瑙支部為阿萊塔研發的裝備，除了配備了基本的防衛系統和通信系統，還可以與第三研究室的系統直連，在戰鬥中即時接收系統的分析數據。\n記得與你的隊友常聯繫。", "icon_alaita_zs3", "0", 3, 3, "3_{lv}*100", "阿萊塔", "1_110021_10", 10, "3_100", "300100,300101,300102", "0", "0", "0", "0", "0", "0", "0", "0"},
[300110] = {300110, "隱鐮", "由艾吉斯總部設計並製造的雙鐮，專為執行隱秘行動的部隊所設計。設計初衷便是在支持隱秘行動的基礎上保證殺傷力和射程，採用鏈條將雙鐮底端連接以便駕駛員回收。\n只有弱水能辨別回收啟動中的隱鐮，其他使用者都被不同程度的劃傷，這孩子或許是與生俱來的暗殺者……", "icon_ruoshui_zs1", "0", 3, 1, "1_{lv}*100", "弱水", "1_110021_10", 10, "1_100", "300110,300111,300112", "0", "0", "0", "0", "0", "0", "0", "0"},
[300111] = {300111, "她從黑暗中來", "由艾吉斯總部設計並製造的潛行服，專為執行隱秘行動的部隊所設計。採用能夠生成負折射率力場的材質，啟動時能讓駕駛員獲得到光學迷彩的效果以便執行隱蔽行動。\n設計這件衣服的研究員被表彰為年度最佳員工，他真的好懂。", "icon_ruoshui_zs2", "0", 3, 2, "3_{lv}*100", "弱水", "1_110021_10", 10, "3_100", "300110,300111,300112", "0", "0", "0", "0", "0", "0", "0", "0"},
[300112] = {300112, "目明", "由艾吉斯總部設計並製造的目罩，專為執行隱秘行動的部隊所設計。遮擋住駕駛員面容的同時，能夠採集周邊情報並將生成的環境數據傳輸至駕駛員大腦。\n眼睛是傳遞人類情緒的重要窗口，一旦遮住，就顯得▉▉了起來。", "icon_ruoshui_zs3", "0", 3, 3, "1_{lv}*100", "弱水", "1_110021_10", 10, "1_100", "300110,300111,300112", "0", "0", "0", "0", "0", "0", "0", "0"},
[300120] = {300120, "騎士榮耀", "由多瑙支部為格洛麗亞研發的裝備，該武裝由重金屬製成，能夠在瞬時爆發出巨大的破壞力，超高溫的斧刃無論何種護甲都能破壞殆盡。\n掙脫了家庭的格洛麗亞，拿到武器的那一刻，恐怖了起來……", "icon_geluoliya_zs1", "0", 3, 1, "1_{lv}*100", "格洛麗亞", "1_110021_10", 10, "1_100", "300120,300121,300122", "0", "0", "0", "0", "0", "0", "0", "0"},
[300121] = {300121, "箴言難辨", "由多瑙支部為格洛麗亞研發的裝備，該護臂由重金屬製成，與巨斧同時配備。在提供不俗的防禦力的同時，內藏的動力機構能夠讓減輕駕駛員使用重型武器的負擔。\n如果箴言難以被辨別，那就自己總結吧，用拳頭……", "icon_geluoliya_zs2", "0", 3, 2, "3_{lv}*100", "格洛麗亞", "1_110021_10", 10, "3_100", "300120,300121,300122", "0", "0", "0", "0", "0", "0", "0", "0"},
[300122] = {300122, "公正道標", "由多瑙支部為格洛麗亞研發的裝備，由輕金屬製成，主要配備給持重武裝的駕駛員，用於輔助平衡。由於其持有攻擊性能，在近距離下也能作為一個火力點，對敵人進行打擊。\n孩子，會有人帶領你的，她會讓你不偏不倚地行走在這詭譎莫測的人世之間，她是……", "icon_geluoliya_zs3", "0", 3, 3, "1_{lv}*100", "格洛麗亞", "1_110021_10", 10, "1_100", "300120,300121,300122", "0", "0", "0", "0", "0", "0", "0", "0"},
[300130] = {300130, "驅光之傘", "該裝備是一名沉迷魔法少女幻想的科學官研發出的第二代攻擊型裝備，裝備採用神秘的“S”金屬，據說該物質並不存於這個宇宙，因此現世的所有攻擊方式都無法摧毀這件裝備。（出自該科學官之口，真實性有待考證）\n在傘架展開狀態下會啟動光翼增加武器出力，賦予武器強大的推進力。", "icon_lilisi_zs1", "0", 2, 1, "1_{lv}*100", "莉莉絲", "1_110021_5", 10, "1_100", "300130,300131,300132", "0", "0", "0", "0", "0", "0", "0", "0"},
[300131] = {300131, "展羽之翼", "該裝備是一名沉迷魔法少女幻想的科學官研發出的第二代輔助型裝備，裝備是用足量的鈦合金製作而成，採用了羽翼狀設計，在提供強大的推進力的同時也擔任了盾牌的職責，能夠從任何外部攻擊中保護裝備者。\n像鳥兒一樣飛翔吧。", "icon_lilisi_zs2", "0", 2, 2, "3_{lv}*100", "莉莉絲", "1_110021_5", 10, "3_100", "300130,300131,300132", "0", "0", "0", "0", "0", "0", "0", "0"},
[300132] = {300132, "聖潔之蓮", "該裝備是一名沉迷魔法少女幻想的科學官研發出的第二代輔助型裝備，具備索敵通信機能的同時，能夠對裝備者的精神感應力起到一定的抑制作用，防止裝備者因感應力太強在戰鬥時接收到過多的負面感情導致精神崩壞。\n製作者的靈感來源於九州古詩。", "icon_lilisi_zs3", "0", 2, 3, "3_{lv}*100", "莉莉絲", "1_110021_5", 10, "3_100", "300130,300131,300132", "0", "0", "0", "0", "0", "0", "0", "0"},
[300140] = {300140, "樵夫", "塞倫公司為科羅溫特別定制的斧型武器，以卡佳支部的名義裝配給科羅溫，使用新型合金材料製作而成。該武器能夠輕鬆劈開原罪的外殼，但是在外觀上並沒有什麼特殊的地方。\n“如果把這個斧子扔進湖裡，能換個金的嗎？”", "icon_keluowen_zs1", "0", 3, 1, "1_{lv}*100", "科羅溫", "1_110021_10", 10, "1_100", "300140,300141,300142", "0", "0", "0", "0", "0", "0", "0", "0"},
[300141] = {300141, "海格力斯之握", "塞倫公司為科羅溫特別定制的臂鎧，以卡佳支部的名義裝配給科羅溫，使用新型合金材料製作而成。臂鎧內部通過複雜的機械結構極大地提升了使用者的握力，讓其手中的武器不易被打飛或者在攻擊敵人時可以輕鬆破壞要害部位。但是整體的外觀上非常普通。\n在肘部裝甲的右下角有一行小字“請勿在裝備此臂鎧的情況下與其他駕駛員握手。”", "icon_keluowen_zs2", "0", 3, 2, "3_{lv}*100", "科羅溫", "1_110021_10", 10, "3_100", "300140,300141,300142", "0", "0", "0", "0", "0", "0", "0", "0"},
[300142] = {300142, "“普通”護目鏡", "塞倫公司為科羅溫特別定制的護目鏡，以卡佳支部的名義裝配給科羅溫，使用新型合金材料製作而成。護目鏡上暗藏全視角鏡頭可以洞悉周圍的一切情況，並顯示在鏡片上。在進行遠距離攻擊時會進行輔助瞄準，是一件攻守兼備的利器。\n“好…好多的數據，眼睛都看花了，算了還是戴在頭上好了。”", "icon_keluowen_zs3", "0", 3, 3, "1_{lv}*100", "科羅溫", "1_110021_10", 10, "1_100", "300140,300141,300142", "0", "0", "0", "0", "0", "0", "0", "0"},
[300150] = {300150, "“關愛”", "由卡佳地區最強的軍火製造商—“塞倫”製作的第三代近戰裝備，該武裝使用鑽頭作為攻擊部，當其旋轉起來時擁有遠超其他類型武器的穿透性能。索菲亞將其取名為“關愛”，除了原罪誰都消受不起的關愛。", "icon_suofeiya_zs1", "0", 3, 1, "3_{lv}*100", "索菲亞", "1_110021_10", 10, "3_100", "300150,300151,300152", "0", "0", "0", "0", "0", "0", "0", "0"},
[300151] = {300151, "絕對力場", "由卡佳地區最強的軍火製造商—“塞倫”製作的測試型防禦裝備，通過改變尼姆比斯能的輸出形式來獲得可以抵禦攻擊的防禦力場。目前是處在測試階段的裝備，可能會出現例如將內部的攻擊也防禦住的尷尬情況。但是對於索菲亞來說什麼都阻止不了她攻擊眼前的敵人，恐怕連傳聞中號稱絕對防禦的防禦力場也阻擋不住。", "icon_suofeiya_zs2", "0", 3, 2, "1_{lv}*100", "索菲亞", "1_110021_10", 10, "1_100", "300150,300151,300152", "0", "0", "0", "0", "0", "0", "0", "0"},
[300152] = {300152, "腳鐐", "由卡佳地區最強的軍火製造商—“塞倫”製作的制式機動裝備的原型機，與量產型不同的是該原型機犧牲了部分機動能力來換取更高的穩定性和承重能力。這件裝備最大的意義在於限制了索菲亞在戰場上的活動範圍，不會因為沉迷於戰鬥而陷入敵人的包圍。索菲亞本人對此是十分不滿，她覺得這就是支部給她上的腳鐐。", "icon_suofeiya_zs3", "0", 3, 3, "1_{lv}*100", "索菲亞", "1_110021_10", 10, "1_100", "300150,300151,300152", "0", "0", "0", "0", "0", "0", "0", "0"},
[300160] = {300160, "最後的努力", "薩哈拉支部所屬學院的制式輕火力武器。是學院保衛科的標準裝備之一，由於體積小巧非常適合駕駛員隨身攜帶作為備用。當然千萬不要小看該槍支的火力，對付一般的低等原罪綽綽有餘。\n“這是我最後的努力了，如果這都不行的話……”", "icon_anan_zs1", "0", 3, 1, "3_{lv}*100", "安安", "1_110021_10", 10, "3_100", "300160,300161,300162", "0", "0", "0", "0", "0", "0", "0", "0"},
[300161] = {300161, "他們的守護者", "薩哈拉支部所屬學院的制式盾牌。是學院保衛科的標準裝備之一，可以提供強大的正面防護能力，但是由於沒有經費加裝重力輔助裝置，其重量需要駕駛員進行一定的體能訓練後方可靈活使用。\n“我是駕駛員，我是個戰士，我是他們的守護者。”", "icon_anan_zs2", "0", 3, 2, "3_{lv}*100", "安安", "1_110021_10", 10, "3_100", "300160,300161,300162", "0", "0", "0", "0", "0", "0", "0", "0"},
[300162] = {300162, "笨鳥先飛", "薩哈拉支部特別支援的機動設備，以尼姆比斯能作為驅動力代替駕駛員的雙腿進行機動，可以很大程度上幫助駕駛員節省體力。雖然速度很快，但是由於會影響戰鬥時的發揮而被大部分駕駛員所嫌棄，卻很適合體型矮小的安安在戰場上行軍。\n“好快，比隊長她們跑得還快…糟糕，一不小心跑太遠了。”", "icon_anan_zs3", "0", 3, 3, "3_{lv}*100", "安安", "1_110021_10", 10, "3_100", "300160,300161,300162", "0", "0", "0", "0", "0", "0", "0", "0"},
[300170] = {300170, "高波震盪雙刃", "在瑪雅地區頂尖科技研究計畫中所衍生的裝備，擁有強大攻擊性能的雙刃型武裝。通過刀體的高速震動可以快速切割原罪肉體，被攻擊的目標就算不死也會喪失戰鬥能力。\n“敵人是原罪而不是人類真是太好了。”——愛好和平的武器設計師", "icon_luoshalinde_zs1", "0", 3, 1, "1_{lv}*100", "羅莎琳德", "1_110021_10", 10, "1_100", "300170,300171,300172", "0", "0", "0", "0", "0", "0", "0", "0"},
[300171] = {300171, "納米輔助鐵臂", "在瑪雅地區頂尖科技研究計畫中所衍生的裝備，極具功能性的輔助裝備。固定在身體兩側的機械臂可以充當額外的手臂使用。兼具力量和靈活的同時，鐵臂還可以啟動內置的模組對使用者進行戰鬥增幅。必要時可以直接進行攻擊，打敵人一個措手不及。\n“有四個手臂的話就不怕和人近身格鬥了，不過遇到飛行的敵人可就苦惱了。”——充滿想像力的武器設計師", "icon_luoshalinde_zs2", "0", 3, 2, "3_{lv}*100", "羅莎琳德", "1_110021_10", 10, "3_100", "300170,300171,300172", "0", "0", "0", "0", "0", "0", "0", "0"},
[300172] = {300172, "亞音速加速引擎", "在瑪雅地區頂尖科技研究計畫中所衍生的裝備，提供高機動性的推進器。可以在幾秒內加速到超音速，最快速度可達到18馬赫但是會對駕駛員巨大化的身體造成極大的負擔。\n“塗成紅色會不會更快一點？”——  急性子的裝備設計師", "icon_luoshalinde_zs3", "0", 3, 3, "1_{lv}*100", "羅莎琳德", "1_110021_10", 10, "1_100", "300170,300171,300172", "0", "0", "0", "0", "0", "0", "0", "0"},
[300180] = {300180, "勝利賜予之盾", "艾吉斯卡佳支部第一研究室特製的盾牌型裝備，本意是為了提高防禦型駕駛員的防禦能力，但是在莉法手上反而成為了“殺敵”的利器。\n最強的防禦就是進攻！", "icon_lifa_zs1", "0", 3, 1, "3_{lv}*100", "莉法", "1_110021_10", 10, "3_100", "300180,300181,300182", "0", "0", "0", "0", "0", "0", "0", "0"},
[300181] = {300181, "通訊帽·女僕型", "由多瑙支部研發部專為多瑙第一親衛班配置的通信裝置，為了滿足莉法的“女僕夢”，瓦爾基里的隊長動用自己的許可權從多瑙支部採購而來。\n這就叫專業。", "icon_lifa_zs2", "0", 3, 2, "3_{lv}*100", "莉法", "1_110021_10", 10, "3_100", "300180,300181,300182", "0", "0", "0", "0", "0", "0", "0", "0"},
[300182] = {300182, "尼伯龍根之環", "艾吉斯卡佳支部第一研究室特製的輔助裝備，由瓦爾基里隊長親自參與研製，可在戰鬥中增幅駕駛員的力量，但實際能力遠遠不止如此。\n小心霧中人。", "icon_lifa_zs3", "0", 3, 3, "1_{lv}*100", "莉法", "1_110021_10", 10, "1_100", "300180,300181,300182", "0", "0", "0", "0", "0", "0", "0", "0"},
[300190] = {300190, "“27Club”", "沒想到我竟然在27歲之前就因為意外去世了……不過我還沒有留下足以讓大家記住我的傳世名作欸？！不行不行，趁著現在還有靈感，我一定要寫出點什麼！\n結束希小姐今天依舊什麼歌都沒寫出來。", "icon_jieshuxiyongzhuang_zs1", "0", 4, 1, "1_{lv}*100", "結束希·泳装", "1_110021_20", 10, "1_100", "300190,300191,300192", "0", "0", "0", "0", "0", "0", "0", "0"},
[300191] = {300191, "“重新來過”", "還不夠……試著在副歌前加入一小段吉他solo……總覺得有哪裡怪怪的，聲音可以更放開一點……為了配合聲音修改一下歌詞吧……有沒有另外的詞呢……\n名為“創作”的地獄今天依舊有人在掙扎。", "icon_jieshuxiyongzhuang_zs2", "0", 4, 2, "1_{lv}*100", "結束希·泳装", "1_110021_20", 10, "1_100", "300190,300191,300192", "0", "0", "0", "0", "0", "0", "0", "0"},
[300192] = {300192, "“偶像與音樂人”", "編舞……嗚，我不擅長這個，要是能和人合作就好了，成員的話就找九個人吧，我們一定會給“世界”帶來絕無僅有的體驗……\n結束希在等待著，就像她以前一樣。", "icon_jieshuxiyongzhuang_zs3", "0", 4, 3, "3_{lv}*100", "結束希·泳装", "1_110021_20", 10, "3_100", "300190,300191,300192", "0", "0", "0", "0", "0", "0", "0", "0"},
[300200] = {300200, "海濱樂園加護", "未來作為海濱樂園的管理員被賦予的武器，在成為駕駛員之後她依舊選了相同的款式。據她說在揮動斧子的時候會有屬於女主角宇宙的力量附著在其上，真實情況未知。\n海濱樂園為了保護這個世界的未來不受傷，而傳遞了力量過來。會有這樣夢幻的事情嗎？", "icon_weilai_zs1", "0", 4, 1, "1_{lv}*100", "未来·泳装", "1_110021_20", 10, "1_100", "300200,300201,300202", "0", "0", "0", "0", "0", "0", "0", "0"},
[300201] = {300201, "大人的泳衣", "不管從何種意義上都是未來的戰鬥服，戰場、游泳場、戀愛場，此泳衣乃是諸多場合的不敗王牌，因為這是大人的泳衣。\n女孩子就是要穿上漂漂亮亮的衣服然後戰鬥在各種各樣的地方的生物。未來裝模作樣地說著聽不懂的話。", "icon_weilai_zs2", "0", 4, 2, "3_{lv}*100", "未来·泳装", "1_110021_20", 10, "3_100", "300200,300201,300202", "0", "0", "0", "0", "0", "0", "0", "0"},
[300202] = {300202, "童話故事", "守護少女的童話故事，在經歷被伊莎貝拉襲擊的事件之後（夢中），未來要求裝備部為自己製作的防身道具和警報道具，能傳出求救信號和定位自己的位置。\n我的故事就此開始。", "icon_weilai_zs3", "0", 4, 3, "1_{lv}*100", "未来·泳装", "1_110021_20", 10, "1_100", "300200,300201,300202", "0", "0", "0", "0", "0", "0", "0", "0"},
[300210] = {300210, "黑心白影", "由多瑙支部研究室專為辛西婭研製的戰鬥裝備。本是分開獨立的鐮刀和盾牌在辛西婭和辛米亞的配合下形成攻防一體的戰鬥模式。在在戰場中就像一輛無懈可擊的戰車，輕鬆碾碎原罪的戰線。唯一的缺陷是二人實際只有單人的能量儲備，導致戰鬥時間大大縮短。\n黑色的內心映出純白的影子，看上去是兩個人，其實我們二位一體。", "icon_xinxiya_zs1", "0", 4, 1, "1_{lv}*100", "辛西婭", "1_110021_20", 10, "1_100", "300210,300211,300212", "0", "0", "0", "0", "0", "0", "0", "0"},
[300211] = {300211, "W型防禦裝甲", "由多瑙支部研究室專為辛西婭研製的防護裝備。與辛西婭和辛米亞一樣，看似是獨立的兩件裝甲其實是一個整體。不但擁有不俗的防護能力，還裝配有獨特的傷害分流裝置，可以將其中一個收到的攻擊分攤到另一人身上。具體的原理屬於絕密等級，除了那位博士之外無人知曉。\n打在你甲，痛在我身。", "icon_xinxiya_zs2", "0", 4, 2, "1_{lv}*100", "辛西婭", "1_110021_20", 10, "1_100", "300210,300211,300212", "0", "0", "0", "0", "0", "0", "0", "0"},
[300212] = {300212, "外置記憶體", "由多瑙支部研究室專為辛西婭研製的通信裝置。除了擁有基礎的通信功能之外，最主要的作用是可以讓二人可以通過思維直接交流，避免在戰鬥中因為溝通問題導致失誤。\n“他們說讓我們用這個溝通。”“他們怕我們會產生分歧。”“他們錯了，我們本就是一體，何來分歧。”", "icon_xinxiya_zs3", "0", 4, 3, "1_{lv}*100", "辛西婭", "1_110021_20", 10, "1_100", "300210,300211,300212", "0", "0", "0", "0", "0", "0", "0", "0"},
[300220] = {300220, "法芙娜之無饜", "由艾吉斯多瑙支部研究室專為龍騎士配置的雙刃巨斧，集厚重與鋒利於一身，十分貼合法芙娜本人狂暴的作戰風格。\n邪龍的貪慾，也將成其爪刃。", "icon_fafuna_zs1", "0", 4, 1, "1_{lv}*100", "法芙娜", "1_110021_20", 10, "1_100", "300220,300221,300222", "0", "0", "0", "0", "0", "0", "0", "0"},
[300221] = {300221, "賈巴沃克之虛妄", "由艾吉斯多瑙支部研究室專為龍騎士配置的通信裝置。由於龍騎士存在著暴走的風險，在附帶正常通信機能的同時，也起到穩定駕駛員腦波的作用。\n邪龍的無謂，也將成其冠冕。", "icon_fafuna_zs2", "0", 4, 2, "3_{lv}*100", "法芙娜", "1_110021_20", 10, "3_100", "300220,300221,300222", "0", "0", "0", "0", "0", "0", "0", "0"},
[300222] = {300222, "提亚马特之博愛", "由艾吉斯多瑙支部研究室專為龍騎士配置的尾部武裝。不僅起到平衡與支撐的作用，在腹背受敵之境也可作為第二把武器而化險為夷。\n邪龍的執念，也將成其覆鱗。", "icon_fafuna_zs3", "0", 4, 3, "1_{lv}*100", "法芙娜", "1_110021_20", 10, "1_100", "300220,300221,300222", "0", "0", "0", "0", "0", "0", "0", "0"},
[300230] = {300230, "牧羊人之杖", "由摩親自設計並委託瑪雅支部製作的長杖型武器，使用了極為堅硬的合金作為原材料，但直到成品製作完成，人們還是沒搞懂摩準備怎麼使用這把武器。\n一根法杖，有著優秀的物理攻擊加成。", "icon_mo_zs1", "0", 4, 1, "3_{lv}*100", "摩", "1_110021_20", 10, "3_100", "300230,300231,300232", "0", "0", "0", "0", "0", "0", "0", "0"},
[300231] = {300231, "老舊的白色外套", "由摩親自設計並委託瑪雅支部製作的裝備，僅僅只是把平時穿的衣服資料上傳，只有穿著這件衣服摩才會感覺安心。\n別看樣子不起眼，卻是一件橙色裝備。", "icon_mo_zs2", "0", 4, 2, "4_{lv}*100", "摩", "1_110021_20", 10, "4_100", "300230,300231,300232", "0", "0", "0", "0", "0", "0", "0", "0"},
[300232] = {300232, "有用之靴", "由摩親自設計並委託瑪雅支部製作的腿部護甲，可以提供雙腿額外的支撐，降低劇烈蹦跑時對膝蓋造成的傷害。\n不只是為了套裝效果。", "icon_mo_zs3", "0", 4, 3, "3_{lv}*100", "摩", "1_110021_20", 10, "3_100", "300230,300231,300232", "0", "0", "0", "0", "0", "0", "0", "0"},
[300250] = {300250, "重刀", "由艾吉斯多瑙支部研究室專為龍騎士配置的巨刀型武裝。為了適應龍騎士的戰鬥風格而極大地增加了堅固度，卻導致其達到了一個恐怖的重量。普通駕駛員揮舞一把已是極限，梅爾卻能同時裝備兩把，不可思議。\n重量不是負擔，而是突破阻礙的力量。", "icon_meier_zs1", "0", 4, 1, "1_{lv}*100", "梅爾", "1_110021_20", 10, "1_100", "300250,300251,300252", "0", "0", "0", "0", "0", "0", "0", "0"},
[300251] = {300251, "望穿", "由艾吉斯多瑙支部研究室專為龍騎士配置的通信裝置。由於龍騎士存在著暴走的風險，在附帶正常通信機能的同時，也起到穩定駕駛員腦波的作用。\n好想回到過去，和他們說一聲……對不起。", "icon_meier_zs2", "0", 4, 2, "1_{lv}*100", "梅爾", "1_110021_20", 10, "1_100", "300250,300251,300252", "0", "0", "0", "0", "0", "0", "0", "0"},
[300252] = {300252, "天行", "由艾吉斯多瑙支部研究室專為龍騎士配置的支撐裝置。採用了非常極端的力學結構，可以支撐起龍騎士誇張的裝備重量。\n自由的步伐永不停歇。", "icon_meier_zs3", "0", 4, 3, "1_{lv}*100", "梅爾", "1_110021_20", 10, "1_100", "300250,300251,300252", "0", "0", "0", "0", "0", "0", "0", "0"},
[300260] = {300260, "“女王”君臨塞倫", "娜斯佳的裝甲是塞倫全部科技實力的結晶，其存在就是為了詮釋著“暴君”這個詞的意義，但是為了成為塞倫的女王，為了擁有話語權，娜斯佳必須承受這份痛苦，不計代價。\n我不會去祈禱神明來拯救我，我不能奢望有人能拯救我，所以我必須靠自己！", "icon_nasijia_zs1", "0", 4, 1, "3_{lv}*100", "娜斯佳", "1_110021_20", 10, "3_100", "300260,300261,300262", "0", "0", "0", "0", "0", "0", "0", "0"},
[300261] = {300261, "“惡戲”無處不在", "塞倫裝備部為了增加裝甲的驅動性，專門打造的推進器，據說娜斯佳讓裝備部在推進器的設計中加入了某種自毀裝置。\n娜斯佳的最後一擊。", "icon_nasijia_zs2", "0", 4, 2, "3_{lv}*100", "娜斯佳", "1_110021_20", 10, "3_100", "300260,300261,300262", "0", "0", "0", "0", "0", "0", "0", "0"},
[300262] = {300262, "“質子”用來交換", "塞倫裝備部為了增加裝甲的續航，專門打造的能源轉換器，能讓娜斯佳更輕鬆地調用尼姆比斯能，值得一提的是，娜斯佳的能源基本都集中在巨大的機械手臂上，即使娜斯佳因為某種原因忽然死亡，機械手臂“女王”依舊會執行她最後的命令。\n娜斯佳不知道在背負著什麼前行。", "icon_nasijia_zs3", "0", 4, 3, "3_{lv}*100", "娜斯佳", "1_110021_20", 10, "3_100", "300260,300261,300262", "0", "0", "0", "0", "0", "0", "0", "0"},
[300270] = {300270, "在此告別“過去”", "亞爾薇特為自己製作的接收器，隨著亞爾薇特研究的進展不斷地追加新的功能，效果繁多，尋常駕駛員記憶並理解搭載在其中的功能都要月餘，全部運用到實戰中更是要數年的磨合，所以她放棄了普及的想法。\n並不是越複雜的裝備，效果就越好——但這句話對能靈活使用它的亞爾薇特並不奏效。", "icon_yaerweite_zs1", "0", 4, 1, "1_{lv}*100", "亞爾薇特", "1_110021_20", 10, "1_100", "300270,300271,300272", "0", "0", "0", "0", "0", "0", "0", "0"},
[300271] = {300271, "時此獨斷“現在”", "亞爾薇特為自己製作的浮游炮，在戰鬥的同時兼顧著傳輸器的作用，當亞爾薇特對對手感到無趣的時候，會以自動模式運行著全身的武器進行攻擊。\n沒有價值的對手，讓她提不起一點興趣。", "icon_yaerweite_zs2", "0", 4, 2, "3_{lv}*100", "亞爾薇特", "1_110021_20", 10, "3_100", "300270,300271,300272", "0", "0", "0", "0", "0", "0", "0", "0"},
[300272] = {300272, "以此開闢“未來”", "亞爾薇特為自己製作的武器，在需要的時候可以單獨從武器匣中分離出來作為劍使用，每一柄劍都需要獨立的意識去操控，發射出去之後會以能量的形式消失，在武器匣中再生成。\n如果亞爾薇特開始全權接手對武器的控制，就表示她要開始認真了。", "icon_yaerweite_zs3", "0", 4, 3, "1_{lv}*100", "亞爾薇特", "1_110021_20", 10, "1_100", "300270,300271,300272", "0", "0", "0", "0", "0", "0", "0", "0"},
[300280] = {300280, "積玉聯芳", "搭載有尖端感應系統的的自律防禦裝置，可分散成複數防禦模塊以應對多重打擊，合一時則更是嚴絲合縫、堅不可摧。\n積玉成山，諸子聯芳。", "icon_mojun_zs1", "0", 3, 1, "3_{lv}*100", "墨君", "1_110021_10", 10, "3_100", "300280,300281,300282", "0", "0", "0", "0", "0", "0", "0", "0"},
[300281] = {300281, "百兵之仁", "墨家千百年相傳的機關锏，為每代“鉅子”所持，如今已隨技術進步獲得新的面貌。可在“四棱锏”與“軟鞭”之間變換形態。\n锏乃善器，唯仁者舉重若輕，揮動自如。", "icon_mojun_zs2", "0", 3, 2, "3_{lv}*100", "墨君", "1_110021_10", 10, "3_100", "300280,300281,300282", "0", "0", "0", "0", "0", "0", "0", "0"},
[300282] = {300282, "匠羽扶搖", "將艾吉斯的技術與機關術相結合，製造而成的動力裝置，能夠高效消耗尼姆比斯能產生位移推進，以便戰術使用。\n原本可以更為小巧且低功耗，不過墨君偏愛這一造型方案。", "icon_mojun_zs3", "0", 3, 3, "1_{lv}*100", "墨君", "1_110021_10", 10, "1_100", "300280,300281,300282", "0", "0", "0", "0", "0", "0", "0", "0"},
[300290] = {300290, "叮叮貓鈴", "史蒂芬妮博士基於莉莉原本身體進行改造的裝備，可以幫助莉莉更好地控制自己的分身。史蒂芬妮讀取了莉莉原罪化過程中的腦部電波變化，將其應用到貓鈴的鈴聲中，分身一旦聽到貓鈴的聲音便會平靜下來。\n一切仿佛回到了貓蛋之內。", "icon_maodan_zs1", "0", 4, 1, "1_{lv}*100", "莉莉", "1_110021_20", 10, "1_100", "300290,300291,300292", "0", "0", "0", "0", "0", "0", "0", "0"},
[300291] = {300291, "好奇心抑制器", "史蒂芬妮博士基於莉莉原本身體進行改造的精神抑制裝置，可以緩解莉莉在原罪化後承受的精神壓力，讓她保持自我的人性不被原罪侵蝕。\n貓的一生一共可以提問八次，為什麼是八次？好了你還剩下七次機會。", "icon_maodan_zs2", "0", 4, 2, "3_{lv}*100", "莉莉", "1_110021_20", 10, "3_100", "300290,300291,300292", "0", "0", "0", "0", "0", "0", "0", "0"},
[300292] = {300292, "非人構造", "史蒂芬妮博士基於莉莉原本身體進行改造的臂鎧，給莉莉原罪化後異化的身體結構提供額外的支撐，同時也可以在莉莉失去自我人格的時候限制她的行動。\n貓的身體構造，是神秘學。", "icon_maodan_zs3", "0", 4, 3, "1_{lv}*100", "莉莉", "1_110021_20", 10, "1_100", "300290,300291,300292", "0", "0", "0", "0", "0", "0", "0", "0"},
[300300] = {300300, "芳香播種者", "根據法爾奈斯在學校及日常生活中慣用的手槍製造而出的AVG武裝，連其中彈藥也盡可能通過尼姆比斯還原了特性，猶如一顆擁有破土之力的頑強種子。\n她向每一座花園播種芬芳，也向每一名敵人播種子彈。", "icon_faernaisi_zs1", "0", 4, 1, "3_{lv}*100", "法爾奈斯", "1_110021_20", 10, "3_100", "300300,300301,300302", "0", "0", "0", "0", "0", "0", "0", "0"},
[300301] = {300301, "塔斯卡尼的陰雲", "根據蘭特家族高級幹部所著外套製造而出的AVG武裝，其樣式象征著籠罩塔斯卡尼上空的陰雲。每一縷穿雲而過照在草地上的陽光，都須經過這片厚重層雲的准許。\n是這片陰雲造就了塔斯卡尼漫長的雨季，還是古老的雨季醞釀出這片陰雲？", "icon_faernaisi_zs2", "0", 4, 2, "3_{lv}*100", "法爾奈斯", "1_110021_20", 10, "3_100", "300300,300301,300302", "0", "0", "0", "0", "0", "0", "0", "0"},
[300302] = {300302, "花園魅影", "根據法爾奈斯耗費重金私人訂製的特殊長靴製造而出的AVG武裝，使用尖端吸音材料顯著降低了腳步聲，即使行走於城市綠地間，那些被踐踏折斷的樹木花草也無法發出半點哀號。\n在蘭特家族的園林中，只有最為百折不撓的花草才得以存續。", "icon_faernaisi_zs3", "0", 4, 3, "3_{lv}*100", "法爾奈斯", "1_110021_20", 10, "3_100", "300300,300301,300302", "0", "0", "0", "0", "0", "0", "0", "0"},
[300310] = {300310, "水之車", "艾吉斯多瑙支部研製的輪型武器，外形仿造了奧菲莉亞故鄉“水車村”中最知名的一座水車，在此基礎上的裝飾更具現代性，而材質與功能更具戰鬥實用性。\n“我想讓它永不停轉，就像幸福的日常生活那樣不斷持續下去。”", "icon_aofeiliya_zs1", "0", 4, 1, "1_{lv}*100", "奧菲莉亞", "1_110021_20", 10, "1_100", "300310,300311,300312", "0", "0", "0", "0", "0", "0", "0", "0"},
[300311] = {300311, "奶奶的心意", "艾吉斯多瑙支部研製的一套防具，外形復原了奧菲莉亞的奶奶為她手工縫製的衣物，原物兼顧保暖與透氣，而這件防具則是兼顧了防御性與輕量化。\n“由於我每長一歲就穿不下之前的衣服了，奶奶她每年都要幫忙縫改，卻從來不說辛苦……”", "icon_aofeiliya_zs2", "0", 4, 2, "3_{lv}*100", "奧菲莉亞", "1_110021_20", 10, "3_100", "300310,300311,300312", "0", "0", "0", "0", "0", "0", "0", "0"},
[300312] = {300312, "小動物長靴", "艾吉斯多瑙支部研製的腿部護具，採用特殊材料與結構提供了強大的減震效果，不僅能讓駕駛員更具靈活機動性，同時還能避免她們的腳步產生的強震破壞場地。\n“希望能自由穿越城市而不破壞道路，就像山間的小動物自由穿越灌木叢而不破壞環境。”", "icon_aofeiliya_zs3", "0", 4, 3, "3_{lv}*100", "奧菲莉亞", "1_110021_20", 10, "3_100", "300310,300311,300312", "0", "0", "0", "0", "0", "0", "0", "0"},
[300320] = {300320, "“門”", "“門”形狀的奇怪武器，被鎖鏈重重封鎖，“門”的作用不祥，只知道在對抗原罪攻擊的時候有出色的防禦表現，目前這扇門由克莉絲蒂娜博士持有。\n我對這東西一無所知，對“門”的研究陷入了瓶頸。", "icon_kelisidina_zs1", "0", 3, 1, "3_{lv}*100", "克里斯蒂娜", "1_110021_10", 10, "3_100", "300320,300321,300322", "0", "0", "0", "0", "0", "0", "0", "0"},
[300321] = {300321, "“門”之鑰", "“門”的啟動裝置，如果以正常的手段打開，那麼這就是一扇正常的門，而如果受到尼姆比斯能的刺激，例如受到蘊含尼姆比斯能的攻擊，門就就會產生抵抗立場。\n總之可以當武器使用。", "icon_kelisidina_zs2", "0", 3, 2, "3_{lv}*100", "克里斯蒂娜", "1_110021_10", 10, "3_100", "300320,300321,300322", "0", "0", "0", "0", "0", "0", "0", "0"},
[300322] = {300322, "看“門”人", "“門”，曾是克莉絲蒂娜博士的主要研究項目之一，但是直到現在，克莉絲蒂娜都沒有交出過讓人滿意的答卷，她對此非常困擾……不，可以說是異常憤怒，現在對“門”研究的優先順序被她挪到了最後。\n我已經在這上面浪費了很多研究經費了，該死！", "icon_kelisidina_zs3", "0", 3, 3, "1_{lv}*100", "克里斯蒂娜", "1_110021_10", 10, "1_100", "300320,300321,300322", "0", "0", "0", "0", "0", "0", "0", "0"},
[300330] = {300330, "應崇奉之物", "鑲嵌在背部的水滴狀晶體，在S52與幻化核心共鳴期間，可一定程度提高適格率。增幅時高時低，極不穩定。經研究發現，該結晶由原初尼姆比斯打造而成，但明顯手法欠妥，夾雜了大量不純成分，因此並非常規的虹色。而日常活動中，其與脊椎骨摩擦所帶來的疼痛，則被當事人視為“契約的憑證”，意義不明，來源不明。", "icon_kelang_zs1", "0", 4, 1, "1_{lv}*100", "柯朗", "1_110021_20", 10, "1_100", "300330,300331,300332", "0", "0", "0", "0", "0", "0", "0", "0"},
[300331] = {300331, "應摘除之物", "S52專用護頸帶，內置定位系統，可即時監管駕駛員所在位置。由於S52經常散播不利於組織團結的言論，絲毫不分場合地點，甚至曾在戰鬥途中鼓動其他駕駛員反抗艾吉斯，為了有效制止這一行為，督促她專注作戰，額外又裝添了可遠程控制的收緊功能和監聽系統。成效顯著。", "icon_kelang_zs2", "0", 4, 2, "3_{lv}*100", "柯朗", "1_110021_20", 10, "3_100", "300330,300331,300332", "0", "0", "0", "0", "0", "0", "0", "0"},
[300332] = {300332, "應歸還之物", "為S52量身定制的盾牌。駕駛員個人裝備研發資金的近九成都花在了這面盾上，因此用料極其奢侈，在整個印加都是數一數二的堅固。當事人對其可謂愛不釋手。但自從“S52會將不再信從她的信眾捆綁固定在盾牌上施以懲戒”一事暴露後，研究所便對此做出嚴格限制。再然後，S52就把武器名稱改成了現在這個——呵。誰管她啊。", "icon_kelang_zs3", "0", 4, 3, "1_{lv}*100", "柯朗", "1_110021_20", 10, "1_100", "300330,300331,300332", "0", "0", "0", "0", "0", "0", "0", "0"},
[300340] = {300340, "白日夢", "九州總部為受刑人洛基專門研發的拘束器其一。為了更好地使用受刑人，艾吉斯慷慨地滿足她們的各種要求。只要她們還是好用的工具，這份特權就能一直持續下去。\n你失去的只是自由，卻擁有了生命。", "icon_luoji_zs1", "0", 4, 1, "1_{lv}*100", "洛基", "1_110021_20", 10, "1_100", "300340,300341,300342", "0", "0", "0", "0", "0", "0", "0", "0"},
[300341] = {300341, "拘束", "九州總部為受刑人洛基專門研發的拘束器其二，洛基特別要求製作的裝備。殺的人越多，手上的血腥味就越難以洗掉，這件裝備能洗掉那些令人作嘔的氣味。\n手上的血能被潔淨，心中的疤無法愈合。", "icon_luoji_zs2", "0", 4, 2, "1_{lv}*100", "洛基", "1_110021_20", 10, "1_100", "300340,300341,300342", "0", "0", "0", "0", "0", "0", "0", "0"},
[300342] = {300342, "夥伴", "九州總部為受刑人洛基專門研發的拘束器其三，刀槍皆為夥伴。洛基並不拘泥於武器的選擇，她認為武器終究只是殺人的手段罷了。但這並不妨礙她把武器視為夥伴。\n刀刀的名字是月，槍槍的名字是七七。", "icon_luoji_zs3", "0", 4, 3, "1_{lv}*100", "洛基", "1_110021_20", 10, "1_100", "300340,300341,300342", "0", "0", "0", "0", "0", "0", "0", "0"},
[300350] = {300350, "您有一筆新的訂單", "為赫莉定制的裝備。在赫莉的強烈要求下，AVG裝甲的大部分性能都集中在了這件裝備上，她的理由是外賣員必須時刻掌握最新情報，敵人和訂單要一網打盡。\n活下去是赫莉的第一序列。", "icon_heli_zs1", "0", 3, 1, "3_{lv}*100", "赫莉", "1_110021_10", 10, "3_100", "300350,300351,300352", "0", "0", "0", "0", "0", "0", "0", "0"},
[300351] = {300351, "外賣員已取餐", "為赫莉定制的裝備。派送箱中攜帶了很多從科研部那裡申請的秘密道具和實驗型道具，有針對原罪堅硬外殼的腐蝕劑，有針對環境的除霧粉塵，當然也有尼姆比斯補充液……\n“補給品——準備充足。”", "icon_heli_zs2", "0", 3, 2, "3_{lv}*100", "赫莉", "1_110021_10", 10, "3_100", "300350,300351,300352", "0", "0", "0", "0", "0", "0", "0", "0"},
[300352] = {300352, "五星好評", "為赫莉定制的裝備。累計獲得100次五星好評就能拿到50盾幣的補貼——by年度五星好評冠軍，赫莉。\n“不給我五星好評的人，這個仇我就記下了。”", "icon_heli_zs3", "0", 3, 3, "1_{lv}*100", "赫莉", "1_110021_10", 10, "1_100", "300350,300351,300352", "0", "0", "0", "0", "0", "0", "0", "0"},
[300360] = {300360, "起誓之花", "你和查麗莎一起買的情趣內衣，被她當作幻化的藍圖提交給紅博士。只有和你單獨出任務的時候才會用這套AVG裝甲，她對此的解釋是“本小姐想穿什麼就穿什麼！”\n……查麗莎絕對是故意的。", "icon_qingrenjiechalisha_zs3", "0", 4, 1, "1_{lv}*100", "查麗莎·情人节", "1_110021_20", 10, "1_100", "300360,300361,300362", "0", "0", "0", "0", "0", "0", "0", "0"},
[300361] = {300361, "解放之緞", "你和查麗莎一起買的情趣內衣，被她當作幻化的藍圖提交給紅博士。當查麗莎注意到你的視線停留在段帶上時，她這麼說道“看什麼看！這個緞帶可不會像之前那樣被你拉一下就讓整個衣服散架！”\n真的不會散架嗎？你對此持疑。", "icon_qingrenjiechalisha_zs2", "0", 4, 2, "1_{lv}*100", "查麗莎·情人节", "1_110021_20", 10, "1_100", "300360,300361,300362", "0", "0", "0", "0", "0", "0", "0", "0"},
[300362] = {300362, "純白之約", "你和查麗莎一起買的情趣內衣，被她當作幻化的藍圖提交給紅博士。對於查麗莎而言，服裝是決勝的手段，而髮飾上的花束則是她的心意，這是命中註定的花束，只向喜歡的人綻放。\n“我們之前買的時候有這個髮飾？”“……笨蛋。”", "icon_qingrenjiechalisha_zs1", "0", 4, 3, "1_{lv}*100", "查麗莎·情人节", "1_110021_20", 10, "1_100", "300360,300361,300362", "0", "0", "0", "0", "0", "0", "0", "0"},
[300370] = {300370, "光榮機關·偽", "由印加支部獨自研製的警備用武器為原型改良的AVG用武器，原設計並未考慮與原罪戰鬥，對原罪的殺傷力有限。\n用來自殺非常順手的一把武器。", "icon_zhensusi_zs1", "0", 4, 1, "1_{lv}*100", "軫宿四", "1_110021_20", 10, "1_100", "300370,300371,300372", "0", "0", "0", "0", "0", "0", "0", "0"},
[300371] = {300371, "外在之壁", "由印加支部獨自研製的警備用盾牌為原型改良的AVG用盾牌，盾牌的防禦性能參數是拉滿的，但是同樣的其重量也被拉滿了，在AVG藍圖設計階段主要的改良方向就是減重。\n心靈之壁保護心智，外在之壁保護軀體。", "icon_zhensusi_zs2", "0", 4, 2, "3_{lv}*100", "軫宿四", "1_110021_20", 10, "3_100", "300370,300371,300372", "0", "0", "0", "0", "0", "0", "0", "0"},
[300372] = {300372, "“警備員”", "由印加支部警備員通用制服為原型改良的AVG用頭部裝甲，具備一定的防護作用，設計師還喪心病狂地將諸如通訊模組，雷達模組，夜視模組等功能集成其中，導致其佩戴感受可以說是災難級別。\n戴上了你就是警備員了。", "icon_zhensusi_zs3", "0", 4, 3, "3_{lv}*100", "軫宿四", "1_110021_20", 10, "3_100", "300370,300371,300372", "0", "0", "0", "0", "0", "0", "0", "0"},
[300380] = {300380, "概率性工具", "由赫洛卡自己設計的AVG武器，靈感來源於她的愛好。由於守夜人平時並不參與作戰任務，所以並沒有該武器的實際戰鬥數據，光從赫洛卡自己提交的參數來看，是把好武器。\n上鉤和脫鉤的概率，一個是50%，另一個也是50%。", "icon_heluoka_zs3", "0", 4, 1, "1_{lv}*100", "赫洛卡", "1_110021_20", 10, "1_100", "300380,300381,300382", "0", "0", "0", "0", "0", "0", "0", "0"},
[300381] = {300381, "“ 貓”不在這裏", "由赫洛卡自己設計的AVG工具，靈感來源於她的愛好。箱子裏不僅放著很多實用（危險）的實驗性道具，必要時還可以用來攻擊敵人，以掄的方式。\n別想了，這裏面沒有貓。", "icon_heluoka_zs2", "0", 4, 2, "4_{lv}*100", "赫洛卡", "1_110021_20", 10, "4_100", "300380,300381,300382", "0", "0", "0", "0", "0", "0", "0", "0"},
[300382] = {300382, "超視覺", "由赫洛卡自己設計的AVG偵查工具，除了有夜視和熱成像之類的基礎功能之外還有探測尼姆比斯能蹤跡的功能，以及對水下魚群的掃描追蹤能力。\n貓在這裏。", "icon_heluoka_zs1", "0", 4, 3, "3_{lv}*100", "赫洛卡", "1_110021_20", 10, "3_100", "300380,300381,300382", "0", "0", "0", "0", "0", "0", "0", "0"},
[300390] = {300390, "“你好”", "由奧德賽重工為哈莉特研發的AVG武器，手部裝甲間湧動的電流，實際上是在提醒哈莉特用力過猛。\n這一拳向你問好。", "icon_halite_zs1", "0", 4, 1, "1_{lv}*100", "哈莉特", "1_110021_20", 10, "1_100", "300390,300391,300392", "0", "0", "0", "0", "0", "0", "0", "0"},
[300391] = {300391, "“教養”", "由奧德賽重工為哈莉特研發的戰衣，能夠提供扎實的防護，如果能夠被好好地穿在身上的話。\n家裏人常說女孩子要有“教養”，於是我弄了一件披在身上。", "icon_halite_zs2", "0", 4, 2, "3_{lv}*100", "哈莉特", "1_110021_20", 10, "3_100", "300390,300391,300392", "0", "0", "0", "0", "0", "0", "0", "0"},
[300392] = {300392, "“歡呼”", "由奧德賽重工為哈莉特研發的研發的通訊裝置，除了通訊外沒有其他臃腫功能，只為了保證隨時能叫停沉迷在勝利中的拳擊手。\n聽見了嗎？不絕的歡呼聲。", "icon_halite_zs3", "0", 4, 3, "3_{lv}*100", "哈莉特", "1_110021_20", 10, "3_100", "300390,300391,300392", "0", "0", "0", "0", "0", "0", "0", "0"},
[300400] = {300400, "天線觸鬚", "感應大家的感情，然後吸收，名為“天線觸鬚”的邪惡作案工具\n更多……我還需要更多……", "icon_xiaozhuli_zs1", "0", 4, 1, "3_{lv}*100", "小朱利初號機", "1_110021_20", 10, "3_100", "300400,300401,300402", "0", "0", "0", "0", "0", "0", "0", "0"},
[300401] = {300401, "空氣炮", "套在手上喊“砰”就會發射出無形尼姆比斯能攻擊敵人\n據紅博士所說，靈感來自於她小時候看到的動畫片，當然她現在還在看。", "icon_xiaozhuli_zs2", "0", 4, 2, "1_{lv}*100", "小朱利初號機", "1_110021_20", 10, "1_100", "300400,300401,300402", "0", "0", "0", "0", "0", "0", "0", "0"},
[300402] = {300402, "大圓盤", "滿足了人類對外星人的想象，完美的傑作，但是red不那麼認為。\n“老土的紅博士可悲地活在自己年輕時候接觸的東西的記憶裡，並且永遠拒絕擁抱時代。”“這叫經典，你懂不懂？”", "icon_xiaozhuli_zs3", "0", 4, 3, "3_{lv}*100", "小朱利初號機", "1_110021_20", 10, "3_100", "300400,300401,300402", "0", "0", "0", "0", "0", "0", "0", "0"},
[300410] = {300410, "副官的稀疏平常", "從偶像到駕駛員到城市管理者，職業生涯未免也太豐富了。\n第三研究室防衛班即使只剩下最後一人，也不會忘了自己的使命。", "icon_daalaita_zs2", "0", 3, 1, "3_{lv}*100", "阿莱塔", "1_110021_20", 10, "3_100", "300410,300411,300412", "0", "0", "0", "0", "0", "0", "0", "0"},
[300411] = {300411, "合劍入盾", "阿萊塔認為這是一件非常不適合她本人氣質的武器，但有什麼辦法呢，為了應對末世做的妥協已經足夠多了，再多一件也無礙。\n合劍入盾,而成一斧,有開山裂石之能！", "icon_daalaita_zs1", "0", 3, 2, "1_{lv}*100", "阿莱塔", "1_110021_20", 10, "1_100", "300410,300411,300412", "0", "0", "0", "0", "0", "0", "0", "0"},
[300412] = {300412, "背道而馳的人生", "阿萊塔小姐始終沒有回到心心念念的舞臺上。\n但是……我們就會在一個全新的未來重逢的。", "icon_daalaita_zs3", "0", 3, 3, "3_{lv}*100", "阿莱塔", "1_110021_20", 10, "3_100", "300410,300411,300412", "0", "0", "0", "0", "0", "0", "0", "0"},
[300420] = {300420, "朱朱特製發飾", "由艾吉斯科學部為駿河朱朱打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n不知道為什麼，她似乎很執著於保留這個發飾的樣子。", "icon_junhezhuzhu_zs1", "0", 4, 1, "3_{lv}*100", "駿河朱朱", "1_110021_20", 10, "3_100", "300420,300421,300422", "0", "0", "0", "0", "0", "0", "0", "0"},
[300421] = {300421, "朱朱特製護手", "由艾吉斯科學部為駿河朱朱打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n朱朱並未選擇我們為她提供的其他武器（武器能隨身體大小而變化），而是選擇了特化拳擊的裝甲。", "icon_junhezhuzhu_zs2", "0", 4, 2, "3_{lv}*100", "駿河朱朱", "1_110021_20", 10, "3_100", "300420,300421,300422", "0", "0", "0", "0", "0", "0", "0", "0"},
[300422] = {300422, "朱朱特製腿甲", "由艾吉斯科學部為駿河朱朱打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n因為朱朱的能力可以讓她隨意改變身體的大小，所以她的幻化裝甲也經過了特殊處理，能隨身體大小而變化。", "icon_junhezhuzhu_zs3", "0", 4, 3, "3_{lv}*100", "駿河朱朱", "1_110021_20", 10, "3_100", "300420,300421,300422", "0", "0", "0", "0", "0", "0", "0", "0"},
[300430] = {300430, "忠誠度檢測裝置", "據説在最初，被這把槍射擊到的人將會被光所操控，但是隨著光的實力越來越強大，當她只憑精神力就能操控別人，這把槍也就成了擺飾。\n一槍一个！", "icon_guang_zs1", "0", 4, 1, "1_{lv}*100", "光·泳裝", "1_110021_20", 10, "1_100", "300430,300431,300432", "0", "0", "0", "0", "0", "0", "0", "0"},
[300431] = {300431, "爸爸的禮物", "爸爸送給她的第一个禮物。被光要求加到了AVG裝備的藍圖裏，不管是什麽時候都不離身。\n也許該給它洗个澡了。", "icon_guang_zs2", "0", 4, 2, "3_{lv}*100", "光·泳裝", "1_110021_20", 10, "3_100", "300430,300431,300432", "0", "0", "0", "0", "0", "0", "0", "0"},
[300432] = {300432, "光之限制器", "就像名字説的那樣，這是在光作為兵器的那段時間裏限制光行動的裝備，雖然在女主角宇宙裏只是純粹的裝飾品，她本人也習慣了。\n説是習慣了不如説已經喜歡上了。", "icon_guang_zs3", "0", 4, 3, "1_{lv}*100", "光·泳裝", "1_110021_20", 10, "1_100", "300430,300431,300432", "0", "0", "0", "0", "0", "0", "0", "0"},
[300440] = {300440, "第二次裁決", "D型b2-H機體配備的近戰武器，參照了D型b2本體的武器設計。【Hecatonchires】模式下會額外幻化出一只手臂和長槍，提升不只是兩倍的攻擊頻率。\n多就是好，多就是強。", "icon_DB2H_zs1", "0", 4, 1, "3_{lv}*100", "D型b2-H", "1_110021_20", 10, "3_100", "300440,300441,300442", "0", "0", "0", "0", "0", "0", "0", "0"},
[300441] = {300441, "新準則", "D型b2-H機體配備的防禦用盾牌，參照了D型b2本體的裝備設計。為了彌補機體本身孱弱的防禦性能而加厚了裝甲層，卻導致重量超額，必須在【Hecatonchires】模式下使用兩只手臂進行支撐才能在戰鬥中保持平衡。\n守護，是【幽靈】不變的準則。", "icon_DB2H_zs2", "0", 4, 2, "3_{lv}*100", "D型b2-H", "1_110021_20", 10, "3_100", "300440,300441,300442", "0", "0", "0", "0", "0", "0", "0", "0"},
[300442] = {300442, "幽靈的體表溫度", "D型b2-H機體配備的防護裝甲，裝甲覆蓋率極低，或許是為了更好的散熱。\n幽靈的體表溫度，預測是273.15K。", "icon_DB2H_zs3", "0", 4, 3, "4_{lv}*100", "D型b2-H", "1_110021_20", 10, "4_100", "300440,300441,300442", "0", "0", "0", "0", "0", "0", "0", "0"},
[300450] = {300450, "碎顱錘", "由艾吉斯工程師為特薇爾達打造的裝備，造型和實際上的重量都相當誇張，但她就是可以只靠一隻手使用它。\n原本的名字大概是複雜的一大串，但她嫌太麻煩了，所以一直這麼叫。", "icon_teweierda_zs1", "0", 4, 1, "1_{lv}*100", "特薇爾達", "1_110021_20", 10, "1_100", "300450,300451,300452", "0", "0", "0", "0", "0", "0", "0", "0"},
[300451] = {300451, "“工作制服”", "特薇爾達最常穿的一套工作裝，卡佳的工作人員甚至懷疑她一年到頭只穿這一身。\n據說是她以前在下決心給自己確定形象時挑的裝束，她的衣櫃裡有好幾套。", "icon_teweierda_zs2", "0", 4, 2, "3_{lv}*100", "特薇爾達", "1_110021_20", 10, "3_100", "300450,300451,300452", "0", "0", "0", "0", "0", "0", "0", "0"},
[300452] = {300452, "敬逝者", "幾塊被抹去了文字的識別牌，和幾把日常生活中絕對不會希望用上的剃刀。\n特薇爾達從不跟人解釋這些東西曾經屬於誰，只是偶爾能看到她對著這些東西發呆。", "icon_teweierda_zs3", "0", 4, 3, "1_{lv}*100", "特薇爾達", "1_110021_20", 10, "1_100", "300450,300451,300452", "0", "0", "0", "0", "0", "0", "0", "0"},
[300460] = {300460, "貫日神槍", "東風舞希使用其能力“貫日神槍”時出現的武器，具有隨心意自由伸縮長度的能力。\n水泥、鋼鐵、甚至於原罪的身軀，都會被它輕易貫穿，是如其名字一樣，連太陽也能貫穿的武器。", "icon_dongfengwuxi_zs1", "0", 4, 1, "1_{lv}*100", "東風舞希", "1_110021_20", 10, "1_100", "300460,300461,300462", "0", "0", "0", "0", "0", "0", "0", "0"},
[300461] = {300461, "東風舞希量身定制隊服", "魔防隊九番組組長東風舞希的隊服，根據她个人喜好進行了適當的修改。\n明明是款式相近的服裝，但穿在東風舞希身上時給人的氣質完全不同。", "icon_dongfengwuxi_zs2", "0", 4, 2, "3_{lv}*100", "東風舞希", "1_110021_20", 10, "3_100", "300460,300461,300462", "0", "0", "0", "0", "0", "0", "0", "0"},
[300462] = {300462, "東風舞希量身定制長鞾", "魔防隊九番組組長東風舞希日常行動時穿戴的長鞾。\n實際上只是普通的鞾子而已，並沒有特別之處。", "icon_dongfengwuxi_zs3", "0", 4, 3, "3_{lv}*100", "東風舞希", "1_110021_20", 10, "3_100", "300460,300461,300462", "0", "0", "0", "0", "0", "0", "0", "0"},
[310000] = {310000, "流星幕", "艾吉斯設計並製造的組合式長槍，在刺出的那一刻，如流星貫穿夜幕般璀璨。\n我以此為驕傲，我以此為榮耀，我以此劃破這漆黑的幕布，我將如流星般閃耀。", "icon_chalisha_zs1", "0", 3, 1, "1_{lv}*100", "查麗莎", "1_110021_10", 10, "1_100", "310000,310001,310002", "0", "0", "0", "0", "0", "0", "0", "0"},
[310001] = {310001, "不滅志", "艾吉斯設計並製造的護臂，其防禦力足以抵擋戰斧式導彈的正面轟擊。\n我心中有一把火焰，那火焰飄飄晃晃，似要熄滅，但有群人伸出手替我擋住了襲來的風。", "icon_chalisha_zs2", "0", 3, 2, "1_{lv}*100", "查麗莎", "1_110021_10", 10, "1_100", "310000,310001,310002", "0", "0", "0", "0", "0", "0", "0", "0"},
[310002] = {310002, "逐日心", "由艾吉斯設計並製造的腿部動力源，其速度，足以追逐下落的太陽。\n於是我不再滿足作為一顆流星，我將要成為……太陽。", "icon_chalisha_zs3", "0", 3, 3, "1_{lv}*100", "查麗莎", "1_110021_10", 10, "1_100", "310000,310001,310002", "0", "0", "0", "0", "0", "0", "0", "0"},
[310010] = {310010, "煌星", "艾吉斯在一次偶然的實驗中製造出的原型武器，利用小型尼姆比斯聚合能的龐大能量，使用者能夠在一瞬間發動數次攻擊。\n即使是這種兵器也能駕馭的愛麗絲大小姐，真是完美。", "icon_ailisi_zs1", "0", 4, 1, "1_{lv}*100", "愛麗絲", "1_110021_20", 10, "1_100", "310010,310011,310012", "0", "0", "0", "0", "0", "0", "0", "0"},
[310011] = {310011, "完美追尋", "克雷蒂亞家設計並製造的護臂，為了能符合愛麗絲的完美，這件護臂光設計時間就長達兩個月。\n這種程度，還沒有達到我所追求的“完美”，我還可以更……", "icon_ailisi_zs2", "0", 4, 2, "1_{lv}*100", "愛麗絲", "1_110021_20", 10, "1_100", "310010,310011,310012", "0", "0", "0", "0", "0", "0", "0", "0"},
[310012] = {310012, "仍未改變", "克雷蒂亞家設計並製造的動力裝置，其內部整合了小型尼姆比斯反應堆，能夠為使用者提供大量動力。\n我在等待什麼，我的內心在渴望什麼，有誰來告訴我……", "icon_ailisi_zs3", "0", 4, 3, "1_{lv}*100", "愛麗絲", "1_110021_20", 10, "1_100", "310010,310011,310012", "0", "0", "0", "0", "0", "0", "0", "0"},
[310020] = {310020, "羽斬", "曾經供奉在心經神社的靈刀，在斬殺原罪並吸收了原罪核心後，擁有了強大的力量，能夠瞬間切斷所碰到的一切事物，靈刀會隨著使用者的改變而改變。\n也許這位少女，真的能通過這柄武器觸摸到神的居所。", "icon_xinzhi_zs1", "0", 4, 1, "1_{lv}*100", "心紙", "1_110021_20", 10, "1_100", "310020,310021,310022", "0", "0", "0", "0", "0", "0", "0", "0"},
[310021] = {310021, "空白消融", "艾吉斯設計並製造的腿部裝甲，尤其在膝蓋部位加強了防禦。\n“膝蓋中箭了，是很可怕的。”", "icon_xinzhi_zs2", "0", 4, 2, "1_{lv}*100", "心紙", "1_110021_20", 10, "1_100", "310020,310021,310022", "0", "0", "0", "0", "0", "0", "0", "0"},
[310022] = {310022, "存在證明", "艾吉斯設計並製造的動力裝置，其內部整合了小型尼姆比斯反應堆，能夠為使用者提供大量動力。\n老身的一切都已經隨著誓言的履行而消失，有人能注意到“我”的過去嗎……", "icon_xinzhi_zs3", "0", 4, 3, "1_{lv}*100", "心紙", "1_110021_20", 10, "1_100", "310020,310021,310022", "0", "0", "0", "0", "0", "0", "0", "0"},
[310030] = {310030, "紅炎", "一把妖刀，傳說是用神秘礦石打造而成，在原罪入侵後，浸泡在高濃度尼姆比斯中獲得了特殊能力，外形會隨著使用者的改變而改變。\n就連妖刀都被她的意志所鎮壓，對她俯首。", "icon_lingmuqingfeng_zs1", "0", 4, 1, "3_{lv}*100", "鈴木清風", "1_110021_20", 10, "3_100", "310030,310031,310032", "0", "0", "0", "0", "0", "0", "0", "0"},
[310031] = {310031, "鬼媽媽", "由九州總部製作的精神力控制裝置，在戰鬥中會大幅度的提高駕駛員與AVG的共鳴數據，但副作用極大。\n假如你惹怒了“鬼媽媽”，我只能祈禱你能順利地死去。", "icon_lingmuqingfeng_zs2", "0", 4, 2, "3_{lv}*100", "鈴木清風", "1_110021_20", 10, "3_100", "310030,310031,310032", "0", "0", "0", "0", "0", "0", "0", "0"},
[310032] = {310032, "田舍歸所", "由九州總部製作的風林火山小隊專用裝甲，該裝甲擁有極高的防護且但重量極輕。\n“唔，希望在這場戰爭的最後，咱能有一個好結局吧……開玩笑的。”", "icon_lingmuqingfeng_zs3", "0", 4, 3, "3_{lv}*100", "鈴木清風", "1_110021_20", 10, "3_100", "310030,310031,310032", "0", "0", "0", "0", "0", "0", "0", "0"},
[310040] = {310040, "束", "該裝備造型上看似古老，卻是九州總部新型的AVG電擊步槍，通過將幻化核心的能量轉化為電能，並在槍管中加速後擊發出去，在衝擊力上高於傳統的電磁步槍。\n每一發子彈，都是錢啊！！！", "icon_lishanqingluan_zs1", "0", 2, 1, "1_{lv}*100", "栗山青鸞", "1_110021_5", 10, "1_100", "310040,310041,310042", "0", "0", "0", "0", "0", "0", "0", "0"},
[310041] = {310041, "邪眼", "該裝備是九州總部某研究員的即興之作，造型雖然古怪，卻蘊含了最頂尖科研技術，該裝備可以捕捉到音速級別的影像動畫，並且視野射程高達30km。\n因為是即興之作，所以量產的可能性微乎其微。之所以把邪眼配布給栗山青鸞的原因是，她使用的武器子彈太昂貴了，務必要確保每一發子彈的準確率和作用性。", "icon_lishanqingluan_zs2", "0", 2, 2, "3_{lv}*100", "栗山青鸞", "1_110021_5", 10, "3_100", "310040,310041,310042", "0", "0", "0", "0", "0", "0", "0", "0"},
[310042] = {310042, "魄", "外觀非常可愛的無人機，具備不俗的炮火支援能力，由於體型關係，無法裝載大量的尼姆比斯能，導致無法在戰場上活躍太久。\n也許關鍵時候，能通過“魄”變身也說不定……", "icon_lishanqingluan_zs3", "0", 2, 3, "3_{lv}*100", "栗山青鸞", "1_110021_5", 10, "3_100", "310040,310041,310042", "0", "0", "0", "0", "0", "0", "0", "0"},
[310060] = {310060, "雙膛狙擊炮", "該裝備由多瑙支部為應對密集型裝甲原罪專門研製的可攜式狙擊炮，由於造價昂貴且戰鬥消耗極高，在整個支部配備該裝備的AVG只有一部。\n在追尋一線新聞的過程中總伴隨著危險，這時候就需要這把武器的幫助。", "icon_yanniluosi_zs1", "0", 3, 1, "1_{lv}*100", "燕妮羅斯", "1_110021_10", 10, "1_100", "310060,310061,310062", "0", "0", "0", "0", "0", "0", "0", "0"},
[310061] = {310061, "定位裝置·好活", "裝置上裝載有多瑙支部新研製的輔助AI，可以通過捕捉戰場上的資訊，並分析成可用情報通過耳機和可視化液晶屏傳達給使用者。\n有攝像功能，年輕的攝影師從不錯過任何一場有趣的新聞。", "icon_yanniluosi_zs2", "0", 3, 2, "3_{lv}*100", "燕妮羅斯", "1_110021_10", 10, "3_100", "310060,310061,310062", "0", "0", "0", "0", "0", "0", "0", "0"},
[310062] = {310062, "填裝彈", "全身由高密度的合金打造而成，品質極高，底部裝有助推火藥，在通過炮管加速後，可以輕鬆擊穿範圍100KM的任何裝甲。\n昂貴的彈藥，雖然沒有用幻化核心作為火力，但依舊很昂貴、很昂貴！", "icon_yanniluosi_zs3", "0", 3, 3, "1_{lv}*100", "燕妮羅斯", "1_110021_10", 10, "1_100", "310060,310061,310062", "0", "0", "0", "0", "0", "0", "0", "0"},
[310070] = {310070, "雪地狙擊槍Ⅰ 型", "由卡佳地區軍方自己研製的初代鐳射狙擊槍，該槍械完全不受溫度的影響，在極寒地區仍能正常使用，並且裝有高倍狙擊鏡和熱成像儀，該武器雖然範圍殺傷力不足，但是穿透力極強。\n專業的情報官，可以在把目標情報傳回指揮室之前，一槍解決目標。", "icon_lidiya_zs1", "0", 3, 1, "1_{lv}*100", "莉迪婭", "1_110021_10", 10, "1_100", "310070,310071,310072", "0", "0", "0", "0", "0", "0", "0", "0"},
[310071] = {310071, "羽音", "由卡佳地區軍方自己研製的初代通信裝備，造價便宜，但內嵌超強的通信系統，另外該裝備極度耐寒，在極地下使用信號也不會受到影響。\n跟隨著這如羽毛般展開的外顯裝置，雪地的人認為，它是勝利法則的人格化所佩戴之物。", "icon_lidiya_zs2", "0", 3, 2, "1_{lv}*100", "莉迪婭", "1_110021_10", 10, "1_100", "310070,310071,310072", "0", "0", "0", "0", "0", "0", "0", "0"},
[310072] = {310072, "生存必需", "由卡佳地區軍需處統一製作的防寒外衣，主要針對常年在極地作戰的駕駛員研製的，採用特別的保暖材料製作而成。\n使用過的駕駛員都說很棒。", "icon_lidiya_zs3", "0", 3, 3, "1_{lv}*100", "莉迪婭", "1_110021_10", 10, "1_100", "310070,310071,310072", "0", "0", "0", "0", "0", "0", "0", "0"},
[310080] = {310080, "地獄香克斯", "由艾吉斯九州總部研發部為絞皇大隊開發的第一把武器，外觀酷似一把貝斯，擁有控制空氣壓強的能力。\n歡迎來到【愛露達死亡深淵】的演唱會現場。", "icon_aixilika_zs1", "0", 4, 1, "3_{lv}*100", "艾希麗卡", "1_110021_20", 10, "3_100", "310080,310081,310082", "0", "0", "0", "0", "0", "0", "0", "0"},
[310081] = {310081, "樂園旋臂", "由艾吉斯九州總部研發部為絞皇大隊開發的外骨骼裝備，可以極大的降低使用者在彈奏中所花費的力氣。\n也許艾希麗卡是位魔女，她有操縱大家情緒的力量。", "icon_aixilika_zs2", "0", 4, 2, "3_{lv}*100", "艾希麗卡", "1_110021_20", 10, "3_100", "310080,310081,310082", "0", "0", "0", "0", "0", "0", "0", "0"},
[310082] = {310082, "追訪迴響", "由艾吉斯九州總部研發部為絞皇大隊開發的裝備，擁有大幅度增強使用者殺傷力的能力。\n腦中在轟鳴，脫離了現場後，音樂依舊在不斷地訪問著我的大腦，這究竟是……", "icon_aixilika_zs3", "0", 4, 3, "3_{lv}*100", "艾希麗卡", "1_110021_20", 10, "3_100", "310080,310081,310082", "0", "0", "0", "0", "0", "0", "0", "0"},
[310090] = {310090, "灰色天使", "該裝備為艾吉斯禁止開發和使用的一種AI兵器，在使用時會對使用者的大腦造成負擔，擁有傳統同型號裝備三倍以上的穿透力。此類裝備只有在卡佳少數的黑市流通。\n灰色的天使能有什麼壞心思呢？", "icon_bolinna_zs1", "0", 2, 1, "3_{lv}*100", "波林娜", "1_110021_5", 10, "3_100", "310090,310091,310092", "0", "0", "0", "0", "0", "0", "0", "0"},
[310091] = {310091, "白色惡魔", "該裝備為艾吉斯禁止開發和使用的一種AI兵器，擁有穩定使用者精神及提升腦力運算速度的作用，但是卻會對使用者的身體造成嚴重負荷，而讓使用者望而卻步。目前該裝備只有在卡佳少數的黑市流通。\n白色的惡魔什麼都不知道、不知道……", "icon_bolinna_zs2", "0", 2, 2, "1_{lv}*100", "波林娜", "1_110021_5", 10, "1_100", "310090,310091,310092", "0", "0", "0", "0", "0", "0", "0", "0"},
[310092] = {310092, "最幸福的孩子", "該裝備為艾吉斯禁止開發和使用的一種AI兵器，雖然能提供非常強大的防禦網，但據說對使用者的精神損傷極大，因此此類裝備只有在卡佳少數的黑市流通。\n我一定、一定是最幸福的孩子了吧。", "icon_bolinna_zs3", "0", 2, 3, "1_{lv}*100", "波林娜", "1_110021_5", 10, "1_100", "310090,310091,310092", "0", "0", "0", "0", "0", "0", "0", "0"},
[310100] = {310100, "黃金小兔兔", "由瓏親自參與設計並委託給瑪雅支部研究院製作的試作型近戰兵器，擁有二種形態，只有瓏才能駕馭它。\n她的敵人一定想不到，也不會想知道，這把武器叫什麼名字", "icon_long_zs1", "0", 2, 1, "1_{lv}*100", "瓏", "1_110021_5", 10, "1_100", "310100,310101,310102", "0", "0", "0", "0", "0", "0", "0", "0"},
[310101] = {310101, "兔兔騎士盔", "由瓏親自參與設計並委託給瑪雅支部研究院製作的裝備，據說帶上這個，會給瓏帶來勇氣。\n你被兔兔騎士打死了。", "icon_long_zs2", "0", 2, 2, "1_{lv}*100", "瓏", "1_110021_5", 10, "1_100", "310100,310101,310102", "0", "0", "0", "0", "0", "0", "0", "0"},
[310102] = {310102, "兔兔機械腿", "由瓏親自參與設計並委託給瑪雅支部研究院製作的試作型機械義肢，據說可以提升瓏3倍以上的彈跳能力。\n兔兔騎士，即將起飛。", "icon_long_zs3", "0", 2, 3, "1_{lv}*100", "瓏", "1_110021_5", 10, "1_100", "310100,310101,310102", "0", "0", "0", "0", "0", "0", "0", "0"},
[310110] = {310110, "雷切", "由艾吉斯總部設計並製造的脅差，採用高強度金屬製作，專為執行隱秘行動的部隊所設計。設計初衷便是在支持隱秘行動的基礎上保證範圍性殺傷力，除利用其本身物理性質進行攻擊外也可以通過放電進行範圍打擊。\n聽憑雷引，且等雷聲大作。", "icon_honglei_zs1", "0", 3, 1, "1_{lv}*100", "轟雷", "1_110021_10", 10, "1_100", "310110,310111,310112", "0", "0", "0", "0", "0", "0", "0", "0"},
[310111] = {310111, "精神殘存", "由艾吉斯總部設計並製造的護臂，相較於防禦性能，更著重於改造潛力，為滿足駕駛員個性定制的需求在裝甲上配置了介面用以配置外部裝備。\n也許我會毀滅，但我的意志，我的作用，我的目標，將會苟延殘喘。", "icon_honglei_zs2", "0", 3, 2, "1_{lv}*100", "轟雷", "1_110021_10", 10, "1_100", "310110,310111,310112", "0", "0", "0", "0", "0", "0", "0", "0"},
[310112] = {310112, "黯光", "由艾吉斯總部設計並製造的金屬面罩，專為執行隱秘行動的部隊所設計。遮擋住駕駛員面容的同時，使得駕駛員能夠在不發出聲響的前提下進行通信交流。\n誰都不知道，我曾來過。", "icon_honglei_zs3", "0", 3, 3, "1_{lv}*100", "轟雷", "1_110021_10", 10, "1_100", "310110,310111,310112", "0", "0", "0", "0", "0", "0", "0", "0"},
[310120] = {310120, "毀滅啟動者", "此為瑪雅支部參與設計，多瑙支部負責制造的機器兵器阿爾法配備的超巨型電磁炮，武器採用稀有金屬進行研製，並在內部附有增幅裝置以提高輸出功率。\n擁有著次人格的我能夢到電子羊嗎。", "icon_aerfa_zs1", "0", 4, 1, "1_{lv}*100", "阿爾法", "1_110021_20", 10, "1_100", "310120,310121,310122", "0", "0", "0", "0", "0", "0", "0", "0"},
[310121] = {310121, "核心堡壘", "此為瑪雅支部參與設計，多瑙支部製造的機器兵器阿爾法配備的腿部裝甲，裝甲採用稀有金屬進行研製，為確保絕對的防禦力在設計上採用了厚裝甲設計，對衝擊抗性拔群。\n我的存在是為了人類的延續，我需要贖罪……", "icon_aerfa_zs2", "0", 4, 2, "3_{lv}*100", "阿爾法", "1_110021_20", 10, "3_100", "310120,310121,310122", "0", "0", "0", "0", "0", "0", "0", "0"},
[310122] = {310122, "無可救藥的惡", "此為瑪雅支部參與設計，多瑙支部製造的機器兵器阿爾法配備的通信裝置，採用稀有金屬進行研製。主要作用在部隊成員間的通信及周遭環境資訊的採集。\n是人為的入侵導致我陷入暴走嗎？我究竟有沒有過錯……我不知道。", "icon_aerfa_zs3", "0", 4, 3, "1_{lv}*100", "阿爾法", "1_110021_20", 10, "1_100", "310120,310121,310122", "0", "0", "0", "0", "0", "0", "0", "0"},
[310140] = {310140, "逐暗之刃", "該裝備是一名沉迷魔法少女幻想的科學家研發出的第三代攻擊型裝備，裝備採用神秘的“S”金屬，據說該物質並不存於這個宇宙，因此現世的所有攻擊方式都無法摧毀這件裝備。（出自該科學官之口，真實性有待考證）刀身可以通過自然光吸收能量，並在命中目標後將能量瞬間放出，產生巨大的破壞力。\n追逐於黑暗中的影之國女王，何日能從暗中走出，你的子民已經能脫離黑暗生存，她們在陽光中等待著你。", "icon_sikadi_zs1", "0", 2, 1, "1_{lv}*100", "斯卡蒂", "1_110021_5", 10, "1_100", "310140,310141,310142", "0", "0", "0", "0", "0", "0", "0", "0"},
[310141] = {310141, "拂曉之後", "該裝備是一名沉迷魔法少女幻想的科學家研發出的第三代輔助型裝備，裝備是用足量的鈦合金製作而成，採用了光之翼系統衍生出的設計以獲得無可比擬的爆發推進力，雖然幻化核心的能量消耗較高，但機動性達到了頂尖的水準。\n拂曉之後，就是影之國的女王力量全盛的時間（大概）", "icon_sikadi_zs2", "0", 2, 2, "3_{lv}*100", "斯卡蒂", "1_110021_5", 10, "3_100", "310140,310141,310142", "0", "0", "0", "0", "0", "0", "0", "0"},
[310142] = {310142, "女王之影", "該裝備是一名沉迷魔法少女幻想的科學家研發出的第三代輔助型裝備，雖不是合金製品但能夠抵禦一定程度的攻擊。具備通信機能的同時，搭載了最新銳的防干擾裝置，使得裝備者能免疫電波干擾。\n我的子民，我將永遠在黑暗中坐擁，我已經強大到，成為了拯救世界的一份子了！", "icon_sikadi_zs3", "0", 2, 3, "1_{lv}*100", "斯卡蒂", "1_110021_5", 10, "1_100", "310140,310141,310142", "0", "0", "0", "0", "0", "0", "0", "0"},
[310150] = {310150, "清虛道德爪痕拳套", "由九州總部科學部與研發部為攻擊型駕駛員設計、研發的外骨骼，該裝甲能夠提供手部的全覆蓋保護。將從幻化核心得到的能量傳遞到五指的尖端，在攻擊目標的同時留下爪痕印記。\n我可是天才！", "icon_ling_zs1", "0", 3, 1, "1_{lv}*100", "鈴", "1_110021_10", 10, "1_100", "310150,310151,310152", "0", "0", "0", "0", "0", "0", "0", "0"},
[310151] = {310151, "淩靈領鈴泠泠狐丸", "由九州總部特研科研制的狐狸型能量傳輸裝置，該裝置能將幻化核心的能量增幅傳遞至身體各部位的機甲。並且內含能量存儲機能，在幻化核心能量耗盡時充當備用能量避免駕駛員因突然解除巨大化造成傷亡。\n為了防止鈴在駕駛的時候因為自己的疏忽造成死亡，以鈴為設計對象的特供裝備製作完成，順帶一提，名字是鈴自己取得，簡稱鈴鈴狐丸。", "icon_ling_zs2", "0", 3, 2, "3_{lv}*100", "鈴", "1_110021_10", 10, "3_100", "310150,310151,310152", "0", "0", "0", "0", "0", "0", "0", "0"},
[310152] = {310152, "慈航普度神州天線", "由九州總部研製的一種通信裝置，在二代的基礎上增加了定位原罪座標的能力。\n同樣，神州天線也是鈴特供的版本，在其中安置了天（笨）才（蛋）教程。", "icon_ling_zs3", "0", 3, 3, "1_{lv}*100", "鈴", "1_110021_10", 10, "1_100", "310150,310151,310152", "0", "0", "0", "0", "0", "0", "0", "0"},
[310160] = {310160, "夜翼", "由艾吉斯總部設計並製造的手弩，採用高強度金屬製作，中距離下能實現精確打擊，威力絲毫不遜於其他火力型駕駛員的武器。\n悄無聲息，精妙絕倫，但這位保護者似乎不太適合出現在狩獵場。", "icon_heiyu_zs1", "0", 3, 1, "3_{lv}*100", "黑羽", "1_110021_10", 10, "3_100", "310160,310161,310162", "0", "0", "0", "0", "0", "0", "0", "0"},
[310161] = {310161, "【黑羽】", "由艾吉斯總部設計並製造的特製金屬腿甲，相較於防禦性能，更著重於改造潛力，為滿足駕駛員個性定制的需求在裝甲上配置了介面用以配置外部裝備。\n竟然說什麼賭上【黑羽】的名字，難道【黑羽】這個名字有什麼特殊的含義嗎……我去問問……", "icon_heiyu_zs2", "0", 3, 2, "3_{lv}*100", "黑羽", "1_110021_10", 10, "3_100", "310160,310161,310162", "0", "0", "0", "0", "0", "0", "0", "0"},
[310162] = {310162, "忠誠的條件", "由艾吉斯總部設計並製造的特製通信器，專為執行隱秘行動的部隊所設計，在確保隊內通信的基礎上搭載了雷達幹擾的功能。\n宣誓效忠，從此以後你我有君臣之別，但還是別這樣了，你也那麼認為對吧？", "icon_heiyu_zs3", "0", 3, 3, "1_{lv}*100", "黑羽", "1_110021_10", 10, "1_100", "310160,310161,310162", "0", "0", "0", "0", "0", "0", "0", "0"},
[310170] = {310170, "破裂者", "由多瑙支部研發部專為多瑙第一親衛班配置的破壞性武裝。使用鈦合金製造，體積雖然龐大但重量上得以控制。破壞力拔群，能夠輕易粉碎原罪的護甲，活躍在護衛多瑙方舟的第一線。\n芙蘿拉、芙蘿拉你想成為什麼樣的芙蘿拉，你拿起武器是【親衛】，你放下武器是【啞巴】，你想成為什麼樣的【芙蘿拉】。", "icon_fuluola_zs1", "0", 3, 1, "3_{lv}*100", "芙蘿拉", "1_110021_10", 10, "3_100", "310170,310171,310172", "0", "0", "0", "0", "0", "0", "0", "0"},
[310171] = {310171, "甲胄力場", "由多瑙支部研發部專為多瑙第一親衛班配置的防護裝甲。使用鈦合金製造，配置在女僕裝的週邊。抗擊打能力，溫度適性極高。能夠輕鬆抵禦大部分的攻擊。\n芙蘿拉小姐，是一位適應性很強的人，即使是不願意做的事情……她也會很快地調整自己的心態。", "icon_fuluola_zs2", "0", 3, 2, "3_{lv}*100", "芙蘿拉", "1_110021_10", 10, "3_100", "310170,310171,310172", "0", "0", "0", "0", "0", "0", "0", "0"},
[310172] = {310172, "發信器·女僕型", "由多瑙支部研發部專為多瑙第一親衛班配置的通信裝置。具有通信機能和情報處理機能的同時，能夠以裝備者為中心進行廣範圍的通信控制，以便裝備者進行戰鬥部署。\n雖然是親衛沒錯，但是為什麼為我設計的外裝風格是女僕樣式的，是哪位性格惡俗的科學官做的嗎？", "icon_fuluola_zs3", "0", 3, 3, "3_{lv}*100", "芙蘿拉", "1_110021_10", 10, "3_100", "310170,310171,310172", "0", "0", "0", "0", "0", "0", "0", "0"},
[310180] = {310180, "音速高頻刀", "由銀自己設計並委託艾吉斯製作的武器，為了滿足自己的作戰需求，採用較輕材質。武器僅依靠鋒銳作為唯一的殺傷手段，只有像銀這樣的戰鬥經驗豐富的人才能最大限度發揮它的優勢。\n我的族人已經擺脫了危險……太好了，我生存的意義現在終於只剩下戰鬥了，【士兵】銀，報到。", "icon_yin_zs1", "0", 3, 1, "1_{lv}*100", "銀", "1_110021_10", 10, "1_100", "310180,310181,310182", "0", "0", "0", "0", "0", "0", "0", "0"},
[310181] = {310181, "銀狼", "由銀自己設計並委託艾吉斯製作的護甲，採用輕金屬材質製造，注重機動性。在提供最低限度的防禦力的同時，能幫助她輕鬆適應各種地面環境進行高速戰鬥。\n這就是巨大化，好奇妙，即使受傷也不會受到真實的傷害，但是行動上有點不方便……巨大化的軀體也有這種壞處呢。", "icon_yin_zs2", "0", 3, 2, "3_{lv}*100", "銀", "1_110021_10", 10, "3_100", "310180,310181,310182", "0", "0", "0", "0", "0", "0", "0", "0"},
[310182] = {310182, "光子披風", "由銀自己設計並委託艾吉斯製作的披風，考慮到自己靈活的作戰風格，並未採用實體材質。原理與諸多光翼類武裝相近，在起到一定的裝飾作用的同時，提高裝備者的機動力。\n銀原來也會在戰鬥的同時考慮到服飾的美觀度嗎？也許從你來到艾吉斯後，就漸漸不再是【士兵】了。", "icon_yin_zs3", "0", 3, 3, "3_{lv}*100", "銀", "1_110021_10", 10, "3_100", "310180,310181,310182", "0", "0", "0", "0", "0", "0", "0", "0"},
[310190] = {310190, "肉質處理", "薩哈拉支部所屬學院自研武器。外形是一對擁有一定的重量和硬度的雙錘。是學院對現有的制式裝備進行的改良，足以在戰場上對抗低等原罪的入侵。錘上的貓爪圖案是天天要求的特別塗裝。\n“看我用這兩個錘子把它們做成漢堡肉餅。”", "icon_tiantian_zs1", "0", 2, 1, "1_{lv}*100", "天天", "1_110021_5", 10, "1_100", "310190,310191,310192", "0", "0", "0", "0", "0", "0", "0", "0"},
[310191] = {310191, "讓所有人都幸福", "薩哈拉支部所學院自研的通信設備。通過學院現有的制式裝備進行改良，內置了數據分析模組，可以自動為探查出戰場周圍的情報，並告知異常。非常適合新人駕駛員用來熟悉戰場，快速進入戰鬥狀態。\n“我會通過料理讓所有人都感到幸福。”", "icon_tiantian_zs2", "0", 2, 2, "3_{lv}*100", "天天", "1_110021_5", 10, "3_100", "310190,310191,310192", "0", "0", "0", "0", "0", "0", "0", "0"},
[310192] = {310192, "廚師的榮光", "薩哈拉支部所屬學院自研的推進裝置。具備優秀的續航能力和穩定性，即使是再惡劣的環境如沙暴之中也能正常使用。但是在推進速度方面不比學院中的制式推進器。\n“環境再差的廚房，優秀的廚師也可以烹調出美食。”", "icon_tiantian_zs3", "0", 2, 3, "1_{lv}*100", "天天", "1_110021_5", 10, "1_100", "310190,310191,310192", "0", "0", "0", "0", "0", "0", "0", "0"},
[310200] = {310200, "輝光不及常者", "由艾吉斯支部—多瑙支部研究室專為鐵鴉成員卡洛琳打造的便攜式光刃，造型上為了滿足使用者的需求，選擇了更加迎合大眾審美而非實用的造型。儘管如此，它依然具備著輕易切割原罪軀體的鋒利度。\n“你聽我解釋，這份設計圖被人動了手腳……”", "icon_kaluolin_zs1", "0", 3, 1, "1_{lv}*100", "卡羅琳", "1_110021_10", 10, "1_100", "310200,310201,310202", "0", "0", "0", "0", "0", "0", "0", "0"},
[310201] = {310201, "不能", "由艾吉斯支部—多瑙支部研究室專為鐵鴉成員卡洛琳打造的貼身防護服，造型上為了滿足使用者的需求，選擇了更加花哨的方案，儘管如此，它依然能夠適應絕大多數作戰環境，讓駕駛員發揮出最大的戰力。\n“我能不能換回我原本的裝備……”", "icon_kaluolin_zs2", "0", 3, 2, "3_{lv}*100", "卡羅琳", "1_110021_10", 10, "3_100", "310200,310201,310202", "0", "0", "0", "0", "0", "0", "0", "0"},
[310202] = {310202, "我，雙馬尾", "由艾吉斯支部—多瑙支部研究室專為鐵鴉成員卡洛琳打造的輕式足甲，造型上為了滿足使用者的需求，選擇了更加花哨的方案。\n“至少它沒那麼古怪……但能不能換個名字？”", "icon_kaluolin_zs3", "0", 3, 3, "1_{lv}*100", "卡羅琳", "1_110021_10", 10, "1_100", "310200,310201,310202", "0", "0", "0", "0", "0", "0", "0", "0"},
[310210] = {310210, "以洋流為吾劍", "第三次迎來老年垂暮的斯卡蒂前往了蘊含著死亡與生命真理的森林，她準備把自己埋在森林中。隨後成功返老還童的她帶著這把能操縱水的劍走出了森林。\n這把劍的故事就這樣寫好了，嗯嗯！", "icon_sikadiyongzhuang_zs1", "0", 3, 1, "1_{lv}*100", "斯卡蒂·泳装", "1_110021_10", 10, "1_100", "310210,310211,310212", "0", "0", "0", "0", "0", "0", "0", "0"},
[310211] = {310211, "以此跨越萬水", "影之國的女王憑藉著她的智慧鑄就了一艘浮舟，讓信仰她的子民從生存環境惡劣的小島上搬遷到了適宜居住的陸地上。\n哇啊啊，水好冰啊……嗯……嗯，吾可不會被這點困難打倒！", "icon_sikadiyongzhuang_zs2", "0", 3, 2, "3_{lv}*100", "斯卡蒂·泳装", "1_110021_10", 10, "3_100", "310210,310211,310212", "0", "0", "0", "0", "0", "0", "0", "0"},
[310212] = {310212, "星之靴", "有古老的龍種憑藉一則數千年前就已經作廢的約定尋到影之國的女王，聲稱條約的廢止沒有經過它的同意，它蠻橫地要求女王賠償。最終它變成了一雙舒適的鞋子，被收藏了起來。\n星之靴，名字就叫這個好了。", "icon_sikadiyongzhuang_zs3", "0", 3, 3, "1_{lv}*100", "斯卡蒂·泳装", "1_110021_10", 10, "1_100", "310210,310211,310212", "0", "0", "0", "0", "0", "0", "0", "0"},
[310220] = {310220, "王下之劍", "王女身份的象徵，距離真正“王”只有一步之遙的距離，因為王女尚未純粹而止步於此，也就是說這一把武器還沒鑄成，劍鞘的名字是“理想鄉”。\n我的劍一旦從理想鄉中拔出，將會吸引世間所有的汙穢前來玷污。", "icon_wangnv_zs1", "0", 3, 1, "1_{lv}*100", "王女", "1_110021_10", 10, "1_100", "310220,310221,310222", "0", "0", "0", "0", "0", "0", "0", "0"},
[310221] = {310221, "第五次孤獨", "能發動【常識改造·催眠光束】的護目鏡，能改變人的作息習慣，早睡早起一日三餐。她究竟在想什麼。\n敬把這個世界攪得天翻地覆的【最自由的怪人，斯卡蒂】。", "icon_wangnv_zs2", "0", 3, 2, "3_{lv}*100", "王女", "1_110021_10", 10, "3_100", "310220,310221,310222", "0", "0", "0", "0", "0", "0", "0", "0"},
[310222] = {310222, "jk束縛環", "從腿上摘下來之後可以當做捆住壞人的束縛圈使用。在世間行俠仗義的時候會用的小道具，王女擁有其專利，目前正在網上試著推銷。\n能被從jk腿上拔下來的腿環束縛，真是便宜你們這些壞人了。", "icon_wangnv_zs3", "0", 3, 3, "1_{lv}*100", "王女", "1_110021_10", 10, "1_100", "310220,310221,310222", "0", "0", "0", "0", "0", "0", "0", "0"},
[310230] = {310230, "無極太極", "使用九州傳統技藝打造的護手，內襯堅韌的人造毛皮，堅固耐用，可以有效消減拳擊時對手臂產生的反作用力。\n太極者，無極而生。", "icon_xiaomeng_zs1", "0", 4, 1, "1_{lv}*100", "曉夢", "1_110021_20", 10, "1_100", "310230,310231,310232", "0", "0", "0", "0", "0", "0", "0", "0"},
[310231] = {310231, "動靜分合", "使用九州傳統技藝打造的護腿，相比於速度更加注重穩定性，有助於武者穩固下盤，將更多力量集中在攻擊上。\n動之則分，靜之則合。", "icon_xiaomeng_zs2", "0", 4, 2, "1_{lv}*100", "曉夢", "1_110021_20", 10, "1_100", "310230,310231,310232", "0", "0", "0", "0", "0", "0", "0", "0"},
[310232] = {310232, "萬化歸一", "使用九州傳統技藝打造的發飾，內置了通訊模組和雷達系統，除開外形比較可愛之外是標準的通訊裝置。\n雖變化萬端，而理唯一貫。", "icon_xiaomeng_zs3", "0", 4, 3, "1_{lv}*100", "曉夢", "1_110021_20", 10, "1_100", "310230,310231,310232", "0", "0", "0", "0", "0", "0", "0", "0"},
[310240] = {310240, "“海豚俠”", "由九州海軍兵器研究部製作的自律魚雷，既能通過聲吶索敵以追蹤目標，也可作為水下載具供駕駛員快速移動、實施遊擊戰術。\n原型其實為鯊魚，妍妍蘿卻稱其為海豚。", "icon_yanyanluo_zs1", "0", 3, 1, "1_{lv}*100", "妍妍蘿", "1_110021_10", 10, "1_100", "310240,310241,310242", "0", "0", "0", "0", "0", "0", "0", "0"},
[310241] = {310241, "真實之窗", "原料之一據稱為妍妍蘿在海底神殿搜尋到的某種結晶，擁有對光線極為敏感的性質。經兵器研究部加工後製成潛水鏡，佩戴者透過鏡片即可在晦暗無明的深海潛行自如。\n而妍妍蘿時常表示，她能透過鏡片看見不存在的事物。", "icon_yanyanluo_zs2", "0", 3, 2, "3_{lv}*100", "妍妍蘿", "1_110021_10", 10, "3_100", "310240,310241,310242", "0", "0", "0", "0", "0", "0", "0", "0"},
[310242] = {310242, "斷壓之刃", "由九州海軍兵器研究所製作的鰭狀外骨骼裝甲，運轉時會控制表面分子振動產生斥力，通過不斷切割水體顯著降低深海壓強，鋒銳的尾鰭也能用於近距離攻擊。\n“我的尾刃，連水壓也能切斷哦”妍妍蘿耍帥地說。", "icon_yanyanluo_zs3", "0", 3, 3, "1_{lv}*100", "妍妍蘿", "1_110021_10", 10, "1_100", "310240,310241,310242", "0", "0", "0", "0", "0", "0", "0", "0"},
[310270] = {310270, "普通的撬棍", "由九州總部參與設計，多名科學官主導研發的——雖然想這麼說，但其實這就是一根各方面參數跟普通的撬棍沒什麼區別的武器，只是比尋常的撬棍要大上十幾倍而已。\n因為很順手，所以幻化的時候就決定選它當武器了。", "icon_qishi_zs1", "0", 4, 1, "1_{lv}*100", "今七實", "1_110021_20", 10, "1_100", "310270,310271,310272", "0", "0", "0", "0", "0", "0", "0", "0"},
[310271] = {310271, "昂貴的貂皮", "無論從什麼角度來看，這就是一個披在身上的貂皮，當然，既然是穿在受刑人身上的衣物，自然一定有它的特別之處——對的，它很貴。\n千萬不要在今七實面前說這套裝扮老土，她會大發雷霆的。", "icon_qishi_zs2", "0", 4, 2, "1_{lv}*100", "今七實", "1_110021_20", 10, "1_100", "310270,310271,310272", "0", "0", "0", "0", "0", "0", "0", "0"},
[310272] = {310272, "時尚的高跟長靴", "只有對自己的長腿擁有絕對自信的人才能適配的長靴，若是不自量力的人穿上只會讓自己顯得可笑。不過，這雙靴子也不是絕對沒有破綻的，它的透氣性就是最大的弱點。\n“說了，人家不是專門的戰鬥人員，就不要難為我穿什麼難看的裝備了啦~”", "icon_qishi_zs3", "0", 4, 3, "1_{lv}*100", "今七實", "1_110021_20", 10, "1_100", "310270,310271,310272", "0", "0", "0", "0", "0", "0", "0", "0"},
[310280] = {310280, "光之復生", "艾吉斯卡佳支部第一研究室特製的潔蘿專用武器，由瓦爾基裡隊長親自參與研製。基於潔蘿特殊的體質量身打造，能更好地引導潔蘿對自身能量的使用。\n當少女舉起長槍時，她將戰無不勝。", "icon_jieluo_zs1", "0", 3, 1, "1_{lv}*100", "潔蘿", "1_110021_10", 10, "1_100", "310280,310281,310282", "0", "0", "0", "0", "0", "0", "0", "0"},
[310281] = {310281, "籠中之焰", "艾吉斯卡佳支部第一研究室特製的輔助裝備，由瓦爾基裡隊長親自參與研製，用以平衡潔蘿身體裡溢出的能量。\n如無必要，請勿解除限制。", "icon_jieluo_zs2", "0", 3, 2, "3_{lv}*100", "潔蘿", "1_110021_10", 10, "3_100", "310280,310281,310282", "0", "0", "0", "0", "0", "0", "0", "0"},
[310282] = {310282, "光從火焰中來", "艾吉斯卡佳支部第一研究室特製的浮游砲，由瓦爾基裡隊長親自參與研製，用以補足潔蘿在火力上的不足之處。\n“實際上，她大多數時候用不上。”", "icon_jieluo_zs3", "0", 3, 3, "3_{lv}*100", "潔蘿", "1_110021_10", 10, "3_100", "310280,310281,310282", "0", "0", "0", "0", "0", "0", "0", "0"},
[310290] = {310290, "興功懼暴", "薩哈拉支部所屬學院的制式武裝之一，整體是長槍的造型，使用輕金屬打造，輕巧耐用。槍頭的藍色金屬是新研製的合金，削鐵如泥，對抗輕型原罪單位非常好用。\n興功懼暴，定分止爭。", "icon_qianmo_zs1", "0", 3, 1, "1_{lv}*100", "千陌", "1_110021_10", 10, "1_100", "310290,310291,310292", "0", "0", "0", "0", "0", "0", "0", "0"},
[310291] = {310291, "雛鷹之威", "薩哈拉支部所屬學院的制式無人機，主要用途是偵察。無人機外形類似鳥類，但是飛行原理是通過磁力場產生反重力飛行。\n雖然是偵察機械，但憑藉重力可以輕鬆砸死原罪。", "icon_qianmo_zs2", "0", 3, 2, "3_{lv}*100", "千陌", "1_110021_10", 10, "3_100", "310290,310291,310292", "0", "0", "0", "0", "0", "0", "0", "0"},
[310292] = {310292, "定法非一", "薩哈拉支部所屬學院的制式裝甲，除了提供部分防護之外還集成了通訊裝置等戰場必備的功能系統，是簡單便攜的多功能戰鬥平臺。\n誰人定義，裝甲只能用來防禦？", "icon_qianmo_zs3", "0", 3, 3, "1_{lv}*100", "千陌", "1_110021_10", 10, "1_100", "310290,310291,310292", "0", "0", "0", "0", "0", "0", "0", "0"},
[310300] = {310300, "量天杖", "艾吉斯九州總部研發的三眼杖銃，擊中目標時會引發火藥爆炸。此外還內置了精準測距系統，可自動修正駕駛員的每一次攻擊，將其導向正途。\n丈量歷史之法，唯有反復敲錘。", "icon_chenglian_zs1", "0", 3, 1, "1_{lv}*100", "澄練", "1_110021_10", 10, "1_100", "310300,310301,310302", "0", "0", "0", "0", "0", "0", "0", "0"},
[310301] = {310301, "破土足", "艾吉斯九州總部研發的動力護腿，可讓駕駛員在各種環境下都靈活行動。其外形設計參考了傳說之中，通曉古今諸史的神獸“白澤”。\n歷史的足跡曾踏過每一寸土地。", "icon_chenglian_zs2", "0", 3, 2, "3_{lv}*100", "澄練", "1_110021_10", 10, "3_100", "310300,310301,310302", "0", "0", "0", "0", "0", "0", "0", "0"},
[310302] = {310302, "止風笠", "艾吉斯九州總部研發的光學防具，除了防風、防塵、減輕光束傷害，更關鍵的功能是忽視敵方光學迷彩，使駕駛員心無迷障。\n歷史有浪、無風。", "icon_chenglian_zs3", "0", 3, 3, "1_{lv}*100", "澄練", "1_110021_10", 10, "1_100", "310300,310301,310302", "0", "0", "0", "0", "0", "0", "0", "0"},
[310310] = {310310, "刀背", "史蒂芬妮博士基於萊拉普斯原本身體進行改造的伴生武器，其組成物質與萊拉普斯身體組成物質相同，看著像刀刃狀的其實是一片細毛，但是在攻擊時會瞬間聚集成為真正的刀刃。\n這是生物學的勝利。", "icon_wangwang_zs1", "0", 3, 1, "1_{lv}*100", "萊拉普斯", "1_110021_10", 10, "1_100", "310310,310311,310312", "0", "0", "0", "0", "0", "0", "0", "0"},
[310311] = {310311, "最終守則", "史蒂芬妮博士基於萊拉普斯原本身體進行改造的腿甲，可以提供一定的防護，但是最主要的作用是可以釋放高壓電流，在萊拉普斯發狂時癱瘓她的身體。\n這是最後的守則，一旦失效將沒有辦法再控制萊拉普斯。", "icon_wangwang_zs2", "0", 3, 2, "3_{lv}*100", "萊拉普斯", "1_110021_10", 10, "3_100", "310310,310311,310312", "0", "0", "0", "0", "0", "0", "0", "0"},
[310312] = {310312, "憤怒抑制器", "史蒂芬妮博士基於萊拉普斯原本身體進行改造的精神抑制裝置，能夠幫助萊拉普斯抑制原罪化帶來的無端憤怒情緒。但是一旦受傷，萊拉普斯的憤怒情緒很可能會超過抑制器控制的閾值。\n你們竟敢傷害我？你們……竟敢傷害……黎貝卡！", "icon_wangwang_zs3", "0", 3, 3, "1_{lv}*100", "萊拉普斯", "1_110021_10", 10, "1_100", "310310,310311,310312", "0", "0", "0", "0", "0", "0", "0", "0"},
[310320] = {310320, "殺人意向", "艾吉斯的研發部在保留原武器外觀的基礎上重新設計架構的裝備。顯然，這是一把剪刀，或者說是一把剪刀拆成了兩半。為什麼要用剪刀作為武器，或許這是千秋的個人喜好。\n無論什麼樣的理由，既然她選擇了犯罪，那她便是罪人。", "icon_qianqiu_zs1", "0", 4, 1, "1_{lv}*100", "千秋", "1_110021_20", 10, "1_100", "310320,310321,310322", "0", "0", "0", "0", "0", "0", "0", "0"},
[310321] = {310321, "殺人鬼", "作為犯罪者小隊，受刑人必須要穿著限制駕駛員人身的裝備。為千秋配備的臂甲最大的目的不是為了保護千秋，而是限制她雙手的“自由”。\n輕易越過殺人之門的人，被稱之為殺人鬼。", "icon_qianqiu_zs2", "0", 4, 2, "1_{lv}*100", "千秋", "1_110021_20", 10, "1_100", "310320,310321,310322", "0", "0", "0", "0", "0", "0", "0", "0"},
[310322] = {310322, "罪孽的重量", "作為犯罪者小隊，受刑人必須要穿著限制駕駛員人身的裝備。為千秋配備的動力靴，儘管一定程度上提高了她的機動力，但只要領航願意，她會一瞬間失去行動能力。\n殺人犯的自由已被剝奪，她必須要背負自己犯下的罪。", "icon_qianqiu_zs3", "0", 4, 3, "1_{lv}*100", "千秋", "1_110021_20", 10, "1_100", "310320,310321,310322", "0", "0", "0", "0", "0", "0", "0", "0"},
[310330] = {310330, "月脊", "艾吉斯卡佳支部第一研究室特製的星爍專用武器，由瓦爾基裏隊長親自參與研製，擁有最高品質的鋒銳度，即便是以堅硬外殼著稱的防禦型原罪也無法抵禦它的攻擊。\n她只需要武器，一把能夠斬斷任何物質的武器。", "icon_xingshuo_zs1", "0", 3, 1, "1_{lv}*100", "星爍", "1_110021_10", 10, "1_100", "310330,310331,310332", "0", "0", "0", "0", "0", "0", "0", "0"},
[310331] = {310331, "爍衣", "艾吉斯卡佳支部第一研究室特製的輔助裝備……不，實際上這並不算一件嚴格意義上的裝備，只是應星爍的要求，量身定制的服飾。據說，名字是她的一個朋友取的。\n“裝甲？那種東西太重了，穿在身上一點也不舒服。如果有攻擊能打中我，那就說明我的好運到頭了，到也不壞。”", "icon_xingshuo_zs2", "0", 3, 2, "3_{lv}*100", "星爍", "1_110021_10", 10, "3_100", "310330,310331,310332", "0", "0", "0", "0", "0", "0", "0", "0"},
[310332] = {310332, "世界的另一端", "艾吉斯卡佳支部第一研究室特製的通訊器，由瓦爾基裏隊長親自參與研製，在對抗蒼霧的“通訊妨礙”上有做特殊處理，不易與其他人失去聯繫。\n何時何地，她都希望能聯繫上那個人。", "icon_xingshuo_zs3", "0", 3, 3, "1_{lv}*100", "星爍", "1_110021_10", 10, "1_100", "310330,310331,310332", "0", "0", "0", "0", "0", "0", "0", "0"},
[310340] = {310340, "領袖想要這麼做", "自稱為“天生領袖”的羅德尼亞，雖然在生活中冒冒失失，但是卻憑藉果斷與大膽在戰場上大放光彩，讓所有人都認可了她。羅德尼亞掌握著高超的槍鬥術，研發部回應了她的想法，為其定制了這把武器。\n不甘淪為凡人，所以舉起“領袖之槍”。", "icon_luodeniya_zs1", "0", 4, 1, "1_{lv}*100", "羅德尼亞", "1_110021_20", 10, "1_100", "310340,310341,310342", "0", "0", "0", "0", "0", "0", "0", "0"},
[310341] = {310341, "溫柔的渴求者", "在某次戰鬥中羅德尼亞首次展現了自己的劍鬥術，令人費解的是，她在劍鬥術上的造詣也遠超常人。研發部為了配合她，與其在武器的拓展選擇上進行了詳細探討，最終為她配備了劍與槍。\n羅德尼亞接受了溫柔的劍，她決定成為一位溫柔的領袖。", "icon_luodeniya_zs2", "0", 4, 2, "3_{lv}*100", "羅德尼亞", "1_110021_20", 10, "3_100", "310340,310341,310342", "0", "0", "0", "0", "0", "0", "0", "0"},
[310342] = {310342, "想要成為那樣的人", "“我要成為像姐姐那樣溫柔的，強大的人！有著能夠治癒傷者心靈的溫柔，能保護所有人不受傷害的強大！我要成為那樣超厲害的人！”\n姐姐的死亡為羅德尼亞留下的回憶，都是想到就會讓胸口發暖的溫柔，這股溫柔淹沒了仇恨，讓羅德尼亞沒有因此走錯路。", "icon_luodeniya_zs3", "0", 4, 3, "1_{lv}*100", "羅德尼亞", "1_110021_20", 10, "1_100", "310340,310341,310342", "0", "0", "0", "0", "0", "0", "0", "0"},
[310350] = {310350, "複生的代價", "根據桀派在多年前使用的裝備改造而成的機動外裝。經過長時間冷凍的身體，即使是現在最高水準的治療，依舊會殘留些許惱人的後遺症——肌肉萎縮，代謝緩慢等。這些後遺症甚至會影響到幻化後的身體，即使巨大化塑造的是一具嶄新而健康身體。\n人們只看到我從地獄中複生，卻從不關心我為此支付了何等的代價。", "icon_jiepai_zs1", "0", 4, 1, "3_{lv}*100", "桀派", "1_110021_20", 10, "3_100", "310350,310351,310352", "0", "0", "0", "0", "0", "0", "0", "0"},
[310351] = {310351, "魔神之冠", "根據桀派在多年前使用的裝備改造而成的精神輔助裝置。那場戰鬥對桀派大腦造成的傷害超過了所有人和儀器的預估。她能存活到現在已經是個奇跡，而史蒂芬妮博士在這個奇跡之上又創造了新的奇跡——她治癒了桀派，用一種全新的療法補齊了她受損的腦細胞。\n這是我的榮譽，也是我的桎梏。", "icon_jiepai_zs2", "0", 4, 2, "3_{lv}*100", "桀派", "1_110021_20", 10, "3_100", "310350,310351,310352", "0", "0", "0", "0", "0", "0", "0", "0"},
[310352] = {310352, "地獄的僕從", "根據桀派在多年前的戰鬥方式設計而成的攻擊型無人機。桀派服役的那段時間是人類對抗原罪最艱難的階段也是桀派最艱辛的時候。連續保持巨大化幾個月，奔波於各個戰場，用廝殺代替休息，最後在原罪的屍體上入眠。\n好好休息吧，剩下的戰鬥就交給她們了。", "icon_jiepai_zs3", "0", 4, 3, "3_{lv}*100", "桀派", "1_110021_20", 10, "3_100", "310350,310351,310352", "0", "0", "0", "0", "0", "0", "0", "0"},
[310360] = {310360, "“蜜囊”", "薩哈拉蒼穹學院計算機科學院受普瑞席歐所托研製的接收天線，用於接收“蜂群”所採集的數據，並根據某種演算法將那些雜亂無章的未加工數據自動處理成有效資訊。\n“小的們，快麻利地為我幹活哦，再辛勤點就能吃到尼姆比斯了~”", "icon_puruixiou_zs1", "0", 4, 1, "1_{lv}*100", "普瑞席歐", "1_110021_20", 10, "1_100", "310360,310361,310362", "0", "0", "0", "0", "0", "0", "0", "0"},
[310361] = {310361, "“女王蜂”", "普瑞席歐自行研發的微型裝置，能將儲存其內的尼姆比斯能轉化為一種蜂型原罪間交流用的信號，其擁有類似資訊素的特性。通過這種信號模擬，普瑞席歐便可號令“蜂群”，因此她將裝置命名為“女王蜂”。\n“雖然是虛假的王冠，戴起來倒也挺合適的嘛。”", "icon_puruixiou_zs2", "0", 4, 2, "1_{lv}*100", "普瑞席歐", "1_110021_20", 10, "1_100", "310360,310361,310362", "0", "0", "0", "0", "0", "0", "0", "0"},
[310362] = {310362, "“蜂群”", "複數蜂型原罪組成的“蜂群”，由普瑞席歐捕獲並記錄，現已被高度馴化。“蜂群”最初每只個體都在30米上下，在普瑞席歐逐步調控它們體內尼姆比斯能存量之後，才勉強實現了相對容易控制的小型化。\n“希望有一天我能飼養耶夢加得，為此還得再多努力研究呢。”", "icon_puruixiou_zs3", "0", 4, 3, "1_{lv}*100", "普瑞席歐", "1_110021_20", 10, "1_100", "310360,310361,310362", "0", "0", "0", "0", "0", "0", "0", "0"},
[310370] = {310370, "祝聖絹布", "據說原型為聖濯教會聖物，擁有特殊過濾性能的頭巾。即使雨水僅從布料間經過一瞬也能得到賜福，被淨化為無比潔淨的純水，面對某些類型的原罪能有效應對。\n駱駝穿過針眼，比毒物穿過此布還要容易。", "icon_saileixiya_zs1", "0", 3, 1, "1_{lv}*100", "塞蕾希婭", "1_110021_10", 10, "1_100", "310370,310371,310372", "0", "0", "0", "0", "0", "0", "0", "0"},
[310371] = {310371, "淨鹽鋒刃", "據說原型為聖濯教會聖物，此刃所用質料的特性之於尼姆比斯，就如同鹽晶之於傷口——被其劃破裝甲的原罪，會像脫水一樣迅速流失體內的尼姆比斯能。\n水應流向它該去之地，而不應在此停駐。", "icon_saileixiya_zs2", "0", 3, 2, "3_{lv}*100", "塞蕾希婭", "1_110021_10", 10, "3_100", "310370,310371,310372", "0", "0", "0", "0", "0", "0", "0", "0"},
[310372] = {310372, "黑鴉＆白鴿", "為塞蕾希婭量身設計的一雙手套，被她命名為“黑鴉＆白鴿”。黑鴉無接觸即可遠程操控武器，白鴿則擁有出色的防菌能力，救助傷患時能避免造成二次感染。\n黑鴉象徵著教會的力量，白鴿象徵著教會的慈心。", "icon_saileixiya_zs3", "0", 3, 3, "1_{lv}*100", "塞蕾希婭", "1_110021_10", 10, "1_100", "310370,310371,310372", "0", "0", "0", "0", "0", "0", "0", "0"},
[310380] = {310380, "帶來毀滅的一把武器", "卡芙卡平時就會使用的趁手武器，在巨大化後也順理成章地幻化了出來，原本只是威懾小混混用的塑膠釘刺被特殊合金取代，變得鋒利無比。\n對於阻擋她道路的墻壁，她首先會進行塗鴉，而後再進行破壞。", "icon_kafuka_zs1", "0", 3, 1, "1_{lv}*100", "卡芙卡", "1_110021_10", 10, "1_100", "310380,310381,310382", "0", "0", "0", "0", "0", "0", "0", "0"},
[310381] = {310381, "重重鎖鏈縛我不得", "卡芙卡平時就會穿戴的綁帶飾品，在巨大化後也順理成章地幻化了出來，擁有不俗的防禦性能，必要時也能用於拘束敵人。\n讓象徵著束縛的綁帶與鎖鏈纏繞自己，實則意在反叛束縛。", "icon_kafuka_zs2", "0", 3, 2, "3_{lv}*100", "卡芙卡", "1_110021_10", 10, "3_100", "310380,310381,310382", "0", "0", "0", "0", "0", "0", "0", "0"},
[310382] = {310382, "鋼鐵指環", "卡芙卡平時就會穿戴的金屬飾品，在巨大化後也順理成章地幻化了出來，讓靈活的雙拳隨時都能予以敵人致命一擊。\n指環不僅只是裝飾，也應成為武器。", "icon_kafuka_zs3", "0", 3, 3, "3_{lv}*100", "卡芙卡", "1_110021_10", 10, "3_100", "310380,310381,310382", "0", "0", "0", "0", "0", "0", "0", "0"},
[310390] = {310390, "巧克力魂寶石", "斯卡蒂自己設計的服裝，拜託紅博士為她製作了AVG藍圖。據斯卡蒂所說，這塊寶石的設定是能收納巧克力的靈魂，殺害的巧克力越多，能量越強大。\n“這塊寶石是甜的哦，領航要不要嘗嘗看？不過不能摘下來給你……唔，稍微蹲下來一點就能夠到了吧？”", "icon_qingrenjiesikadi_zs1", "0", 4, 1, "1_{lv}*100", "斯卡蒂·情人节", "1_110021_20", 10, "1_100", "310390,310391,310392", "0", "0", "0", "0", "0", "0", "0", "0"},
[310391] = {310391, "戀愛暴走限制器", "斯卡蒂自己設計的服裝，拜託紅博士為她製作了AVG藍圖。據斯卡蒂所說，眼罩的設定是在她的戀愛能量要溢滿的時候，暫時抑制她的暴走。但是實際上在她戴上眼罩之後反而更加中二了。\n值得慶幸的是莉莉絲依舊能壓制斯卡蒂的眼罩中二狀態。", "icon_qingrenjiesikadi_zs2", "0", 4, 2, "3_{lv}*100", "斯卡蒂·情人节", "1_110021_20", 10, "3_100", "310390,310391,310392", "0", "0", "0", "0", "0", "0", "0", "0"},
[310392] = {310392, "幹壞事的尾巴", "斯卡蒂自己設計的服裝，拜託紅博士為她製作了AVG藍圖。據斯卡蒂所說，尾巴屬於魅魔器官的一種，在非幻化狀態下，尾巴也能隨著她的意志而動。紅博士為了在截止日期前滿足斯卡蒂的設定通宵了三天。\n當你和斯卡蒂站在一起的時候，你意識到斯卡蒂的尾巴在蹭你的大腿。", "icon_qingrenjiesikadi_zs3", "0", 4, 3, "1_{lv}*100", "斯卡蒂·情人节", "1_110021_20", 10, "1_100", "310390,310391,310392", "0", "0", "0", "0", "0", "0", "0", "0"},
[310400] = {310400, "情感的傳達", "感情檢測裝置，擁有著極強的性能，但是會隨著使用者感情而產生不同幅度的動作，失落的時候會折耳朵，高興的時候會大幅度搖動，緊張的時候會硬直不動，憤怒的時候會飛機耳。一旦戴上這件裝備就不能隱藏自己的心情。\n害羞的時候也會大幅度搖動。", "icon_duoluolisiqingdian_zs1", "0", 4, 1, "1_{lv}*100", "多洛莉絲·偶像", "1_110021_20", 10, "1_100", "310400,310401,310402", "0", "0", "0", "0", "0", "0", "0", "0"},
[310401] = {310401, "超級星光閃耀號", "“我決定叫它，超級多洛莉絲號，象徵著重生的第三防衛班和你，怎麼樣？”“紅博士，還是換個名字吧！”“是嗎？我還覺得這名字挺不錯的……那就叫超級星光閃耀號吧。”“嗚……”\n繼承著擊碎星辰的意志，應運而生的最閃耀武器。", "icon_duoluolisiqingdian_zs2", "0", 4, 2, "1_{lv}*100", "多洛莉絲·偶像", "1_110021_20", 10, "1_100", "310400,310401,310402", "0", "0", "0", "0", "0", "0", "0", "0"},
[310402] = {310402, "帶著魔法的水晶鞋", "通常情況下為高跟鞋狀態，“外殖流體裝甲”的一部分，在戰場上會隨著多洛莉絲心意而切換形態形態，減震緩解關節的壓力、抓地、防滑、力量傳導……面對不同的地形亦有不同的戰鬥模式。\n跳舞的時候記得穿上高跟鞋。", "icon_duoluolisiqingdian_zs3", "0", 4, 3, "1_{lv}*100", "多洛莉絲·偶像", "1_110021_20", 10, "1_100", "310400,310401,310402", "0", "0", "0", "0", "0", "0", "0", "0"},
[310410] = {310410, "雷暴儀", "該武器本屬於已陣亡的前伊斯坎瓦亞成員，根據規定，由新加入的駕駛員繼承。瞭解當事人的身體狀況後，研發部果斷取消了對電流密度的限制，對武器進行升級改造，並經重新塗裝，才交至新駕駛員手中。\n“哪位前輩？我怎麼知道。反正留下來的也只是代號，只有代號。”", "icon_zhinvxing_zs1", "0", 3, 1, "1_{lv}*100", "織女星", "1_110021_10", 10, "1_100", "310410,310411,310412", "0", "0", "0", "0", "0", "0", "0", "0"},
[310411] = {310411, "外置器", "由於該駕駛員曾注射過大劑量的違禁藥物，中樞神經系統受到嚴重損傷，當年負責該手術的醫療人員經商議決定嵌入晶片輔助治療。為了保證晶片組能正常、穩定地運行，除定期檢查所需，當事人不得擅自取下該裝置。\n“取下頭飾以示尊重？來，你先把你的腦子取出來讓我看看。”", "icon_zhinvxing_zs2", "0", 3, 2, "3_{lv}*100", "織女星", "1_110021_10", 10, "3_100", "310410,310411,310412", "0", "0", "0", "0", "0", "0", "0", "0"},
[310412] = {310412, "極協套件", "該駕駛員左臂裝配的肌電假肢，是印加支部研發部近三年的明星產品之一。身為新產品的初試者，當事人不僅無需支付高昂的費用，還享有多項後期免費優質服務，包括且不限於更替電池、增添絕緣塗層、定期維護升級——只要她還是駕駛員。\n“……不得不承認，艾吉斯的科技確實厲害。”", "icon_zhinvxing_zs3", "0", 3, 3, "1_{lv}*100", "織女星", "1_110021_10", 10, "1_100", "310410,310411,310412", "0", "0", "0", "0", "0", "0", "0", "0"},
[310420] = {310420, "單線程生物", "為海蘿定制的通訊器。根據她的要求只保留了最低限度的聯絡功能，雖然科學官極力反對，但她似乎很相信自己的隊友。\n“畢竟我是單線程生物嘛，只要想著戰鬥就不太關心其他事情了，還是讓羅德來提醒我吧。”", "icon_hailuo_zs1", "0", 4, 1, "1_{lv}*100", "海蘿", "1_110021_20", 10, "1_100", "310420,310421,310422", "0", "0", "0", "0", "0", "0", "0", "0"},
[310421] = {310421, "能量指示器", "為海蘿定制的能量指示器。根據她的要求加入了特別提醒，在駕駛員能量即將耗盡的時候會用某種方式提醒海蘿，外在表現是會不斷閃爍紅燈。\n“某種方式是什麼……嗯，會不斷地震動，這樣我就能注意到了。”", "icon_hailuo_zs2", "0", 4, 2, "3_{lv}*100", "海蘿", "1_110021_20", 10, "3_100", "310420,310421,310422", "0", "0", "0", "0", "0", "0", "0", "0"},
[310422] = {310422, "只此一次的機會", "為海蘿定制的武器。根據她的要求做了特殊處理，使她能調動全身的尼姆比斯能進行攻擊，並為她設置了必殺技——危機情況下可以把所有的尼姆比斯能集中在一擊上。\n“用這一擊開拓未來……這樣的台詞很帥吧？”", "icon_hailuo_zs3", "0", 4, 3, "3_{lv}*100", "海蘿", "1_110021_20", 10, "3_100", "310420,310421,310422", "0", "0", "0", "0", "0", "0", "0", "0"},
[310430] = {310430, "應許系統", "由多瑙支部與聖濯教會聯合開發，搭載了擁有最新演算法與龐大數據庫的人工智慧，作戰中可隨時向其提出戰術方面的需求，並立刻得到頗具可行性的答復。\n“用這個系統替我傾聽告解，是不是就能省很多事了呢？不過……人的情感或許沒那麼容易計算呢。”", "icon_mila_zs1", "0", 4, 1, "1_{lv}*100", "米菈", "1_110021_20", 10, "1_100", "310430,310431,310432", "0", "0", "0", "0", "0", "0", "0", "0"},
[310431] = {310431, "福音傳媒", "由多瑙支部與聖濯教會聯合開發，以長柄斧為基礎結合了水壓式管風琴的構造，不僅斧頭本身的破壞力驚人，其附帶的音波攻擊同樣不容小覷。\n沒有它無法穿透的心之墻，且聽福音貫耳、深入骨髓。", "icon_mila_zs2", "0", 4, 2, "1_{lv}*100", "米菈", "1_110021_20", 10, "1_100", "310430,310431,310432", "0", "0", "0", "0", "0", "0", "0", "0"},
[310432] = {310432, "自律儀典", "由多瑙支部與聖濯教會聯合開發，運用了空氣動力學設計以及大量納米機械輔助，這身裝束在任何情況下都能保持完美優雅的狀態，每一陣風掀起的衣角裙擺都飄飄若仙。\n當儀式成了一種工作，還不如讓機械來將它完成。", "icon_mila_zs3", "0", 4, 3, "1_{lv}*100", "米菈", "1_110021_20", 10, "1_100", "310430,310431,310432", "0", "0", "0", "0", "0", "0", "0", "0"},
[310440] = {310440, "視覺之門", "海因給自己設計的AVG裝甲，最初只存在於設計圖上，隨著她陰差陽錯地成為了駕駛員，這套裝甲也得以幻化。該部件似乎擁有刺激大腦枕葉區，從而模擬四色視的能力。\n“該怎麼形容眼前的這道色彩呢？那就像是……通宵一晚終於能吃到早餐。”", "icon_haiyin_zs1", "0", 3, 1, "1_{lv}*100", "海因", "1_110021_10", 10, "1_100", "310440,310441,310442", "0", "0", "0", "0", "0", "0", "0", "0"},
[310441] = {310441, "繪世之杖", "海因給自己設計的AVG裝甲，最初只存在於設計圖上，隨著她陰差陽錯地成為了駕駛員，這套裝甲也得以幻化。該部件分為“調色器”與“筆”兩個部分，將調製後的尼姆比斯能當作顏料，即可畫物成真。\n“繪畫可以創造出整個世界。”", "icon_haiyin_zs2", "0", 3, 2, "3_{lv}*100", "海因", "1_110021_10", 10, "3_100", "310440,310441,310442", "0", "0", "0", "0", "0", "0", "0", "0"},
[310442] = {310442, "跋涉之足", "海因給自己設計的AVG裝甲，最初只存在於設計圖上，隨著她陰差陽錯地成為了駕駛員，這套裝甲也得以幻化。該部件搭載了智慧程式，縱使不擅運動也能在其輔助之下於戰場活動自如。\n“科技就是用來解決這種問題的。”", "icon_haiyin_zs3", "0", 3, 3, "1_{lv}*100", "海因", "1_110021_10", 10, "1_100", "310440,310441,310442", "0", "0", "0", "0", "0", "0", "0", "0"},
[310450] = {310450, "必要之物", "B17專用止咬器，亦是電擊裝置。在非巨大化狀態下，當事人曾多次表現出過度的攻擊性，因此日常需長期佩戴此裝置，減少不必要的麻煩。", "icon_feilier_zs1", "0", 4, 1, "1_{lv}*100", "吠黎爾", "1_110021_20", 10, "1_100", "310450,310451,310452", "0", "0", "0", "0", "0", "0", "0", "0"},
[310451] = {310451, "喜愛之物", "B17專用小型運輸機，本該只負責B17在非巨大化狀態下的搬運問題，但由於深受當事人喜愛，即便巨大化了也堅持要用它移動，於是研究所相關科研人員進行改裝，增添了等離子炮、雷達等功能。為了避免日常搬運途中走火，安裝有多層電子鎖。最核心的幾對金鑰，除清醒時的B17以外，研究所內僅有極少數人知曉。", "icon_feilier_zs2", "0", 4, 2, "3_{lv}*100", "吠黎爾", "1_110021_20", 10, "3_100", "310450,310451,310452", "0", "0", "0", "0", "0", "0", "0", "0"},
[310452] = {310452, "厭惡之物", "為B17量身定制的金剛狼爪，平日存放在運輸機內，僅巨大化時可取出使用。而啟動暫態升溫裝置後，能“撕”開世間絕大部分物質。由於相關資金挪用於改造運輸機，該武器未裝載任何保護設備。持續的高溫會對駕駛員右手造成嚴重損耗，需一定時間修復。", "icon_feilier_zs3", "0", 4, 3, "1_{lv}*100", "吠黎爾", "1_110021_20", 10, "1_100", "310450,310451,310452", "0", "0", "0", "0", "0", "0", "0", "0"},
[310460] = {310460, "斬斷礙事者之斧", "在佩佩塔被編入“歧花”時，薩哈拉的教師們為了送走這瘟神而專門打造的AVG武裝。斧身帶有自適應震蕩系統，會自動根據所斬之物的硬度調節震蕩頻率，並且減少對使用者的反作用力，保護使用者的手臂。\n不管是什麼東西，只要擋在我的前路，我都會把它斬斷。", "icon_peipeita_zs1", "0", 4, 1, "1_{lv}*100", "佩佩塔", "1_110021_20", 10, "1_100", "310460,310461,310462", "0", "0", "0", "0", "0", "0", "0", "0"},
[310461] = {310461, "想更接近你", "在佩佩塔被編入“歧花”時，薩哈拉的教師們為了送走這瘟神而專門打造的AVG武裝。雖然不能算是薩哈拉的最尖端的技術結晶，但高效的能量轉化效率和自動化的懸浮技術讓它成為最適合新手的飛行裝置。\n想更快一點，想更早一點，抵達你的身邊。", "icon_peipeita_zs2", "0", 4, 2, "1_{lv}*100", "佩佩塔", "1_110021_20", 10, "1_100", "310460,310461,310462", "0", "0", "0", "0", "0", "0", "0", "0"},
[310462] = {310462, "追逐戀情之靴", "在佩佩塔被編入“歧花”時，薩哈拉的教師們為了送走這瘟神而專門打造的AVG武裝。該腿甲附帶多種預設模式，能夠適應各種地形戰鬥，無論是空中、陸地、水中，它都能提供使用者強大的機動力。\n衝衝衝，戀愛的戰車絕不會止步於此。", "icon_peipeita_zs3", "0", 4, 3, "1_{lv}*100", "佩佩塔", "1_110021_20", 10, "1_100", "310460,310461,310462", "0", "0", "0", "0", "0", "0", "0", "0"},
[310470] = {310470, "愛的傳送器", "蕩漾兔的AVG武裝，外觀造型符合其網絡形象所佩耳麥，且額外追加了與領航的私人通訊頻道權限。\n“請讓我在戰場上也依舊歌唱吧，畢竟在有些作品裡，這樣做可以極大鼓舞士氣哦。”", "icon_dangyangtu_zs1", "0", 4, 1, "1_{lv}*100", "蕩漾兔", "1_110021_20", 10, "1_100", "310470,310471,310472", "0", "0", "0", "0", "0", "0", "0", "0"},
[310471] = {310471, "“嗚嗚醬”", "蕩漾兔的AVG武裝，外觀造型符合其網絡形象的吉祥物，據說可作為偵查、戰鬥、醫療一體式無人機，但從未有人見過它登場。\n“輪到它登場的話，一定是發生了世界毀滅級別的大災難吧。”", "icon_dangyangtu_zs2", "0", 4, 2, "3_{lv}*100", "蕩漾兔", "1_110021_20", 10, "3_100", "310470,310471,310472", "0", "0", "0", "0", "0", "0", "0", "0"},
[310472] = {310472, "狡兔之足", "蕩漾兔的AVG武裝，外觀造型符合其網絡形象的長靴，能夠提供無與倫比的移動力，彈射性能也十分優秀。\n“打不過想要逃跑的話，就來我身上吧，我會帶你遠離危險~”", "icon_dangyangtu_zs3", "0", 4, 3, "3_{lv}*100", "蕩漾兔", "1_110021_20", 10, "3_100", "310470,310471,310472", "0", "0", "0", "0", "0", "0", "0", "0"},
[310480] = {310480, "絕對陽光禁止之鏡", "摩根勒菲挑選，斯卡蒂冠名，領航認可的傳說之墨鏡。斯卡蒂讓領航以戴冠的形式把墨鏡架到了莉莉絲的頭髮上。\n莉莉絲對這幅墨鏡視若珍寶。", "icon_yongzhuanglilisi_zs1", "0", 4, 1, "3_{lv}*100", "莉莉絲·泳装", "1_110021_20", 10, "3_100", "310480,310481,310482", "0", "0", "0", "0", "0", "0", "0", "0"},
[310481] = {310481, "絕對害羞禁止之衣", "領航挑選，摩根勒菲冠名，斯卡蒂認可的傳說之寶衣。“你只是自己想看吧。”莉莉絲投來了鄙夷的目光。\n但不知出於什麼心思，她最終還是選擇了這款泳衣。", "icon_yongzhuanglilisi_zs2", "0", 4, 2, "3_{lv}*100", "莉莉絲·泳装", "1_110021_20", 10, "3_100", "310480,310481,310482", "0", "0", "0", "0", "0", "0", "0", "0"},
[310482] = {310482, "絕對接觸禁止之鞋", "斯卡蒂挑選，領航冠名，摩根勒菲認可的傳說之沙灘鞋。禁止接觸的意思似乎是指不許與地面接觸。\n當然，領航也不能接觸，絕對不可以！", "icon_yongzhuanglilisi_zs3", "0", 4, 3, "3_{lv}*100", "莉莉絲·泳装", "1_110021_20", 10, "3_100", "310480,310481,310482", "0", "0", "0", "0", "0", "0", "0", "0"},
[310490] = {310490, "覺悟利刃", "在“阿爾泰婭·維斯”進行巨大化的一段時間後出現的武器，與阿爾泰婭的身軀緊緊相連。目前只能判斷是產生某種異變的尼姆比斯能源結晶幻化出的武器，具備切割一切的性能。/n少女體內的潛能仍未得到開發，這與她身上埋著的謎團一同揭露——這是屬於她的力量嗎？還是說……", "icon_aertaiya_zs1", "0", 3, 1, "1_{lv}*100", "阿爾泰婭", "1_110021_10", 10, "1_100", "310490,310491,310492", "0", "0", "0", "0", "0", "0", "0", "0"},
[310491] = {310491, "“GOD DAMN”", "在加入“九頭蛇”之後，史蒂芬妮博士曾經詢問她是否需要專門設計一套裝甲，但遭到她拒絕，於是保留了她這身衣服。\n“沒有比這句話更適合我的裝備了。”", "icon_aertaiya_zs2", "0", 3, 2, "3_{lv}*100", "阿爾泰婭", "1_110021_10", 10, "3_100", "310490,310491,310492", "0", "0", "0", "0", "0", "0", "0", "0"},
[310492] = {310492, "觀賞用貓耳", "史蒂芬妮博士基於阿爾泰婭原本的衣物款式設計的頭部裝甲——雖說是裝甲，但基本不具備防禦的作用，其最大的作用就是輔助阿爾泰婭的通感能力，讓她最大限度解放自己幻化身軀的能力。\n她沒有任何技巧，是一個純粹的數值怪物。", "icon_aertaiya_zs3", "0", 3, 3, "1_{lv}*100", "阿爾泰婭", "1_110021_10", 10, "1_100", "310490,310491,310492", "0", "0", "0", "0", "0", "0", "0", "0"},
[310500] = {310500, "創世紀", "波琳娜注射“天堂藥劑”幻化後自然出現的AVG武器，似乎是啟動了被刻印在波琳娜體內的“藍圖”。擁有扳機的雙刀，不僅可以從發動遠距離攻擊，更可怕的功能是在刀刃切入原罪身體的那一刻，可以將洶湧的破壞能量一股腦注入其體內，從內而外將其湮滅。\n一擊滅世，一擊開天。", "icon_sdbolinna_zs1", "0", 4, 1, "1_{lv}*100", "波琳娜·圣诞节", "1_110021_20", 10, "1_100", "310500,310501,310502", "0", "0", "0", "0", "0", "0", "0", "0"},
[310501] = {310501, "罪之果", "波琳娜注射“天堂藥劑”幻化後自然出現的AVG裝甲，似乎是啟動了被刻印在波琳娜體內的“藍圖”。出現在身後的六對光翼不僅僅只是裝飾或象徵作用，經過儀器檢測發現翅膀及羽毛在以一種恒定的頻率震動，在空氣中共鳴從而形成了一層可以從物理層面上阻斷物體的護盾。\n從罪惡中綻放的生命之果。", "icon_sdbolinna_zs3", "0", 4, 2, "3_{lv}*100", "波琳娜·圣诞节", "1_110021_20", 10, "3_100", "310500,310501,310502", "0", "0", "0", "0", "0", "0", "0", "0"},
[310502] = {310502, "人性的基準線", "波琳娜注射“天堂藥劑”幻化後自然出現的頭部飾品，似乎是啟動了被刻印在波琳娜體內的“藍圖”。作用未知，僅僅在封存的【天使計畫】檔案中查到一句“用於維持人性，約束【神】的誕生。”\n波琳娜沒發現頭上有個環，不然她肯定要拿下來嘗嘗味道。", "icon_sdbolinna_zs2", "0", 4, 3, "1_{lv}*100", "波琳娜·圣诞节", "1_110021_20", 10, "1_100", "310500,310501,310502", "0", "0", "0", "0", "0", "0", "0", "0"},
[310510] = {310510, "誓約之劍", "純白色的誓約之劍，這不僅是一柄武器，更是對初心的守護，對信念的踐行。你是否準備好與這柄劍一同面對命運的試煉？\n騎士即將迎來與誓約之人一同舉劍的那天。", "icon_zlwshunsha_zs1", "0", 4, 1, "1_{lv}*100", "朱利烏斯·情人节", "1_110021_20", 10, "1_100", "310510,310511,310512", "0", "0", "0", "0", "0", "0", "0", "0"},
[310511] = {310511, "愛意之許", "愛是誓約，是守護，是勇氣。佩戴這枚頭飾的人，將以心意為劍，以感情為盾，與伴侶攜手走過每一段冒險旅程。\n傳說只有真正懷揣愛意的人才能喚醒它的力量，而它的光輝也會因佩戴者的真心而愈發耀眼。", "icon_zlwshunsha_zs2", "0", 4, 2, "3_{lv}*100", "朱利烏斯·情人节", "1_110021_20", 10, "3_100", "310510,310511,310512", "0", "0", "0", "0", "0", "0", "0", "0"},
[310512] = {310512, "心戀之鑰", "愛是一段旅途，而這雙鞋將帶你走向最美的歸宿。\n你的每一步都將帶著對愛的渴望與承諾，無論前路如何，都能堅定不移地追尋屬於自己的幸福。", "icon_zlwshunsha_zs3", "0", 4, 3, "7_{lv}*100", "朱利烏斯·情人节", "1_110021_20", 10, "7_100", "310510,310511,310512", "0", "0", "0", "0", "0", "0", "0", "0"},
[310520] = {310520, "潘朵拉引擎", "當潘朵拉的魔盒被打開，災厄與瘟疫從中逃出來時，希望女神被留在了盒子裡。\n那個孩子的名字，就這樣定下來了，是希望女神厄爾庇斯的另一個名字——斯珀絲。", "icon_siposi_zs1", "0", 4, 1, "3_{lv}*100", "斯珀絲", "1_110021_20", 10, "3_100", "310520,310521,310522", "0", "0", "0", "0", "0", "0", "0", "0"},
[310521] = {310521, "勇者之劍", "決定好了的事情就不能改變，要拯救世界，這是我在旅行之前就定好的事情。\n我送你回去，你幫我拯救世界。", "icon_siposi_zs2", "0", 4, 2, "1_{lv}*100", "斯珀絲", "1_110021_20", 10, "1_100", "310520,310521,310522", "0", "0", "0", "0", "0", "0", "0", "0"},
[310522] = {310522, "拯救未來", "我是不知道“軟弱”是什麼意思的勇者。是未來的救世主，人類最後的希望，註定要拯救世界的勇者。\n去拯救世界吧，一號同伴！", "icon_siposi_zs3", "0", 4, 3, "3_{lv}*100", "斯珀絲", "1_110021_20", 10, "3_100", "310520,310521,310522", "0", "0", "0", "0", "0", "0", "0", "0"},
[310530] = {310530, "鬼之發", "目前唯一一位元不需要科學官為其製作裝備的駕駛員。\n武器的話用頭髮就夠了，還有從嘴部射出光炮！", "icon_qingyv_zs1", "0", 4, 1, "1_{lv}*100", "青羽", "1_110021_20", 10, "1_100", "310530,310531,310532", "0", "0", "0", "0", "0", "0", "0", "0"},
[310531] = {310531, "鬼之膚", "目前唯一一位元不需要科學官為其製作裝備的駕駛員。\n身上的黑色部分即是肌膚，不知道為什麼，像防護裝甲一樣能起到防禦作用。", "icon_qingyv_zs2", "0", 4, 2, "3_{lv}*100", "青羽", "1_110021_20", 10, "3_100", "310530,310531,310532", "0", "0", "0", "0", "0", "0", "0", "0"},
[310532] = {310532, "鬼之衣", "目前唯一一位元不需要科學官為其製作裝備的駕駛員。\n青羽鍾愛的衣服，原因不明。", "icon_qingyv_zs3", "0", 4, 3, "3_{lv}*100", "青羽", "1_110021_20", 10, "3_100", "310530,310531,310532", "0", "0", "0", "0", "0", "0", "0", "0"},
[310540] = {310540, "鐘意的耳飾", "由艾吉斯科學部為天花打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n也許在熟悉過裝備之後，在裝備的增幅下一口氣能力發動次數真的能突破667次也說不定。", "icon_chuyuntianhua_zs1", "0", 4, 1, "7_{lv}*100", "出雲天花", "1_110021_20", 10, "7_100", "310540,310541,310542", "0", "0", "0", "0", "0", "0", "0", "0"},
[310541] = {310541, "天花特製戰鬥裝甲", "由艾吉斯科學部為天花打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n全方位強化天花身體素質的作戰服。", "icon_chuyuntianhua_zs2", "0", 4, 2, "3_{lv}*100", "出雲天花", "1_110021_20", 10, "3_100", "310540,310541,310542", "0", "0", "0", "0", "0", "0", "0", "0"},
[310542] = {310542, "天花特製接觸手套", "由艾吉斯科學部為天花打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n考慮到天花的近戰能力和能力的特性研製的手套，能很好地保護手。", "icon_chuyuntianhua_zs3", "0", 4, 3, "1_{lv}*100", "出雲天花", "1_110021_20", 10, "1_100", "310540,310541,310542", "0", "0", "0", "0", "0", "0", "0", "0"},
[310550] = {310550, "紅之罪", "red醬冒領紅博士的工資為自己研發的avg裝備，保持了常服時的造型但內部材料早已換成了非常昂貴而堅固的輕重量合金，同時集成了高性能通訊和探測雷達模組。\n尖尖的雙角，是邪惡的代表。", "icon_red_zs1", "0", 4, 1, "3_{lv}*100", "red", "1_110021_20", 10, "3_100", "310550,310551,310552", "0", "0", "0", "0", "0", "0", "0", "0"},
[310551] = {310551, "象徵性服裝", "red醬冒領紅博士的工資為自己研發的avg裝備，保持了常服時的造型但材料使用的是最高強度的柔性金屬，模擬布料般的舒適又能提供足夠的防護。\n穿上什麼樣衣服就會變成什麼樣的人。", "icon_red_zs2", "0", 4, 2, "3_{lv}*100", "red", "1_110021_20", 10, "3_100", "310550,310551,310552", "0", "0", "0", "0", "0", "0", "0", "0"},
[310552] = {310552, "不可知領域", "red醬冒領紅博士的工資為自己研發的avg裝備，沒有人知道裏面裝載了什麼，知道的人都選擇閉口不談。\n青春期少女的想法，猜不得。", "icon_red_zs3", "0", 4, 3, "3_{lv}*100", "red", "1_110021_20", 10, "3_100", "310550,310551,310552", "0", "0", "0", "0", "0", "0", "0", "0"},
[310560] = {310560, "聖前之刃", "在通往神而聖者，砥礪自己的道路上，會長走出了很長一段距離，最終在見到的小時候的自己之後停止了腳步。不知道她下一次攀登會是什麼時候。\n其實她憧憬的一直都是小時候的自己。", "icon_huizhang_zs1", "0", 3, 1, "1_{lv}*100", "會長", "1_110021_10", 10, "1_100", "310560,310561,310562", "0", "0", "0", "0", "0", "0", "0", "0"},
[310561] = {310561, "戰術指導眼镜", "戴上眼鏡的時候是普通形態，摘下眼鏡的時候是攻擊形態，很好理解吧？\n那你晚上睡覺的時候會摘下眼鏡嗎？", "icon_huizhang_zs2", "0", 3, 2, "3_{lv}*100", "會長", "1_110021_10", 10, "3_100", "310560,310561,310562", "0", "0", "0", "0", "0", "0", "0", "0"},
[310562] = {310562, "某所學校的制服", "像是會長存在證明一樣的衣服，這身衣服正是她的過去，象徵著她的“來時路”。\n她非常珍惜這份緣分。", "icon_huizhang_zs3", "0", 3, 3, "7_{lv}*100", "會長", "1_110021_10", 10, "7_100", "310560,310561,310562", "0", "0", "0", "0", "0", "0", "0", "0"},
[310570] = {310570, "竊竊私語之帽", "污穢的知識在吾的腦中響起，那是不被人所知的讓人瘋狂的知識，只有吾才能面不改色地把它待在頭上。\n“它有把我們變回去的辦法嗎？”“吾又聽不懂它說什麼。”", "icon_sikadimv_zs1", "0", 4, 1, "3_{lv}*100", "斯卡蒂·魔女", "1_110021_20", 10, "3_100", "310570,310571,310572", "0", "0", "0", "0", "0", "0", "0", "0"},
[310571] = {310571, "照亮禁忌之燈", "用吾等的足跡照亮這個充滿著章魚、章魚、章魚的世界！面對吾！章魚！\n“照亮的即是禁忌的知識，也是希望，你說對吧？。”“對是對……不過這燈是用什麼當作燃料的？”“靈魂。”", "icon_sikadimv_zs2", "0", 4, 2, "1_{lv}*100", "斯卡蒂·魔女", "1_110021_20", 10, "1_100", "310570,310571,310572", "0", "0", "0", "0", "0", "0", "0", "0"},
[310572] = {310572, "“吾的眷屬”", "世界的救世主也變成了章魚的樣子，好在吾及時救了他，不然由他所化凶獸就要肆虐整個世界。\n“這不是我嗎！？”", "icon_sikadimv_zs3", "0", 4, 3, "1_{lv}*100", "斯卡蒂·魔女", "1_110021_20", 10, "1_100", "310570,310571,310572", "0", "0", "0", "0", "0", "0", "0", "0"},
[310580] = {310580, "痛&愛", "由兩把電鋸組成的雙持武器，看著危險實則一點也不安全，使用不當容易傷害到自己。\n“既然巨大化下造成的傷口不會反應到本體上，那還有什麼理由害怕呢？”裝備設計者如是說。", "icon_mixia_zs1", "0", 4, 1, "1_{lv}*100", "米夏", "1_110021_20", 10, "1_100", "310580,310581,310582", "0", "0", "0", "0", "0", "0", "0", "0"},
[310581] = {310581, "柔軟的刺", "華而不實的AVG裝甲，就連最基礎的防護性能都未能達標，因為設計這套AVG本身目的，僅僅是用於測試藍圖小型化專案的測試。\n柔軟的刺，比堅硬的刺，更容易傷到人。", "icon_mixia_zs2", "0", 4, 2, "3_{lv}*100", "米夏", "1_110021_20", 10, "3_100", "310580,310581,310582", "0", "0", "0", "0", "0", "0", "0", "0"},
[310582] = {310582, "傳達不出的聲音", "擁有超高性能監聽功能的通訊設備，可以滴水不漏地監聽戰場上的任何聲音，然而對於使用者來說，太繁雜的聲音卻是對自身的干擾。\n“……”", "icon_mixia_zs3", "0", 4, 3, "1_{lv}*100", "米夏", "1_110021_20", 10, "1_100", "310580,310581,310582", "0", "0", "0", "0", "0", "0", "0", "0"},
[310590] = {310590, "帕拉斯之賜", "由艾吉斯多瑙支部研究轉為龍騎士配置的長槍型武裝，略顯奢華的裝飾並非徒有其表，只有被貫穿的敵人才知道其中的痛楚。\n長槍只是幌子，右手的短劍才是致勝法寶。", "icon_mihaier_zs1", "0", 4, 1, "1_{lv}*100", "米海爾", "1_110021_20", 10, "1_100", "310590,310591,310592", "0", "0", "0", "0", "0", "0", "0", "0"},
[310591] = {310591, "全勝之意", "由艾吉斯多瑙支部研究轉為龍騎士配置的通信裝置。由於龍騎士存在著暴走的風險，在附帶正常通信機能的同時，也起到穩定駕駛員腦波的作用。\n先贏下局部戰鬥，再擊潰精英敵人，最後是全面勝利。", "icon_mihaier_zs2", "0", 4, 2, "3_{lv}*100", "米海爾", "1_110021_20", 10, "3_100", "310590,310591,310592", "0", "0", "0", "0", "0", "0", "0", "0"},
[310592] = {310592, "凱旋", "由艾吉斯多瑙支部研究室專為龍騎士配置的機動裝置。展開後的機械結構像羽翼一般保持衝刺時的平衡，也能讓使用者做出出乎敵人意料的機動動作。\n不出所料，又是我贏了……但我又是在為什麼而戰鬥呢？", "icon_mihaier_zs3", "0", 4, 3, "1_{lv}*100", "米海爾", "1_110021_20", 10, "3_100", "310590,310591,310592", "0", "0", "0", "0", "0", "0", "0", "0"},
[310600] = {310600, "“遺贈”", "戈露卡的全身上下都潛藏著諸如此類的變形結構，根據第一實驗室的觀察報告，臂刀是其中她用著最順手也最不容易造成意外傷害的。\n這些時刻提醒著她自身異常之處的結構，就是過去給她留下的遺贈。", "icon_geluka_zs1", "0", 3, 1, "1_{lv}*100", "戈露卡", "1_110021_20", 10, "1_100", "310600,310601,310602", "0", "0", "0", "0", "0", "0", "0", "0"},
[310601] = {310601, "“過去”", "戈露卡從記憶的起點就一直穿著的衣服。防護性能如看上去一樣貧弱，但意外地可以保暖。\n她猶豫再三，還是決定把這件衣服視為自己存在的一部分。", "icon_geluka_zs2", "0", 3, 2, "3_{lv}*100", "戈露卡", "1_110021_20", 10, "3_100", "310600,310601,310602", "0", "0", "0", "0", "0", "0", "0", "0"},
[310602] = {310602, "“現在”", "戈露卡在博洛特內的街頭偶然得到的衣服。雖然她現在早就不需要用這種簡陋的衣服禦寒了，但還是堅持穿著它。\n她試圖銘記每一條與自己有關的生命。", "icon_geluka_zs3", "0", 3, 3, "3_{lv}*100", "戈露卡", "1_110021_20", 10, "3_100", "310600,310601,310602", "0", "0", "0", "0", "0", "0", "0", "0"},
[310610] = {310610, "美羅特製裝飾", "上運天美羅習慣性穿戴在脖子上的裝飾。\n感覺只要戴上這個項圈裝飾，就會很有“不良辣妹”的潮流感。", "icon_shangyuntianmeiluo_zs1", "0", 4, 1, "1_{lv}*100", "上運天美羅", "1_110021_20", 10, "1_100", "310610,310611,310612", "0", "0", "0", "0", "0", "0", "0", "0"},
[310611] = {310611, "美羅特製隊服", "魔防隊二番組組長上運天美羅的隊服，根據她個人喜好進行了適當的修改。\n只要她穿著這身衣服，大家都會下意識把她當做昔日的暴走族不良少女。", "icon_shangyuntianmeiluo_zs2", "0", 4, 2, "3_{lv}*100", "上運天美羅", "1_110021_20", 10, "3_100", "310610,310611,310612", "0", "0", "0", "0", "0", "0", "0", "0"},
[310612] = {310612, "美羅特製腿甲", "魔防隊二番組組長上運天美羅日常行動時穿戴的長靴。\n實際上只是普通的靴子而已，並沒有特別之處。", "icon_shangyuntianmeiluo_zs3", "0", 4, 3, "3_{lv}*100", "上運天美羅", "1_110021_20", 10, "3_100", "310610,310611,310612", "0", "0", "0", "0", "0", "0", "0", "0"},
[310620] = {310620, "基本的印象錨點", "朱利烏斯考慮過為那趟外出準備完全不一樣的髮型，但最後，她還是決定保持原狀。\n保留對方熟悉的部分能夠增加親和力，這是來自同僚的寶貴意見。", "icon_yundongzzhuliwusi_zs1", "0", 4, 1, "1_{lv}*100", "朱利烏斯·私服", "1_110021_20", 10, "1_100", "310620,310621,310622", "0", "0", "0", "0", "0", "0", "0", "0"},
[310621] = {310621, "必要的形象轉變", "完全沒有貴族風格，絲毫不帶騎士要素，一件你從來沒見朱利烏斯穿過的私服。\n要把改變在最容易辨識的地方展示出來，這是她在雜誌上專門標紅的建議。", "icon_yundongzzhuliwusi_zs2", "0", 4, 2, "3_{lv}*100", "朱利烏斯·私服", "1_110021_20", 10, "3_100", "310620,310621,310622", "0", "0", "0", "0", "0", "0", "0", "0"},
[310622] = {310622, "配套穿搭", "既沒有太過顯眼的裝飾，也不是華麗的裙裝，但朱利烏斯還是在觀察鏡中自己的過程中產生了一些心跳加速的感覺。\n而且還非常方便活動，完美。", "icon_yundongzzhuliwusi_zs3", "0", 4, 3, "3_{lv}*100", "朱利烏斯·私服", "1_110021_20", 10, "3_100", "310620,310621,310622", "0", "0", "0", "0", "0", "0", "0", "0"},
[320000] = {320000, "正義的不義之舉", "啟用這件裝備進行一次戰鬥所需要的尼姆比斯能可以維持一個正常小隊出擊3次有餘，其殺傷力也與消耗成正比。\n強大的火力，仿佛來自地獄的咆哮，席捲的烈焰必將一切事物焚燒殆盡。", "icon_jinkula_zs1", "0", 2, 1, "3_{lv}*100", "金庫啦", "1_110021_5", 10, "3_100", "320000,320001,320002", "0", "0", "0", "0", "0", "0", "0", "0"},
[320001] = {320001, "無所不能之財", "艾吉斯為金庫啦定制的足甲。\n聽聞是金庫啦直接上門指定了中意的科學官來製作。", "icon_jinkula_zs2", "0", 2, 2, "1_{lv}*100", "金庫啦", "1_110021_5", 10, "1_100", "320000,320001,320002", "0", "0", "0", "0", "0", "0", "0", "0"},
[320002] = {320002, "情感乃無價之物", "艾吉斯設計並製造的動力裝置，其內部整合了小型尼姆比斯反應堆，能夠為使用者提供大量動力。\n我會用有價之物來守護無價之物。", "icon_jinkula_zs3", "0", 2, 3, "1_{lv}*100", "金庫啦", "1_110021_5", 10, "1_100", "320000,320001,320002", "0", "0", "0", "0", "0", "0", "0", "0"},
[320010] = {320010, "無懈可擊的懶惰", "靜的人生目標是在家裏宅一輩子！如果說愛麗絲是“完美的淑女”的話，那麼靜就是“完美的吊車尾”！讓所有人對其不抱有期待的完美的吊車尾。雖然是這樣說，但是靜還是成為了駕駛員。\n世界上還有人對其抱有期待的話，那一定是愛麗絲和蒂娜。", "icon_jing_zs1", "0", 3, 1, "1_{lv}*100", "静", "1_110021_10", 10, "1_100", "320010,320011,320012", "0", "0", "0", "0", "0", "0", "0", "0"},
[320011] = {320011, "連續的倒數第一", "靜·克雷蒂亞仍然要離開學校與家，走向駕駛員的戰場。這樣的靜還能上戰場，歸功於她有一位優秀的姐姐——愛麗絲·克雷蒂亞。實在看不下去靜的怠惰，愛麗絲把靜安排到了自己的隊伍中，提供給靜庇佑的同時，希望能磨煉靜。\n靜之所以能如此自在的生活，完全是因為有姐姐的存在。", "icon_jing_zs2", "0", 3, 2, "3_{lv}*100", "静", "1_110021_10", 10, "3_100", "320010,320011,320012", "0", "0", "0", "0", "0", "0", "0", "0"},
[320012] = {320012, "未來該如何是好", "假如某一天，愛麗絲犧牲了，也許靜才會真正開始正視起自己的人生，正視自己得過且過的每一天，正視自己的過去，現在，乃至於未來。然後她會發現這些時刻，都有來自於愛麗絲為她展開的屏障與庇佑……但是這樣的未來是不可能發生的。\n正如靜如此信任著愛麗絲一樣，無暇的愛麗絲是不會倒下的。", "icon_jing_zs3", "0", 3, 3, "3_{lv}*100", "静", "1_110021_10", 10, "3_100", "320010,320011,320012", "0", "0", "0", "0", "0", "0", "0", "0"},
[320020] = {320020, "阿射", "該武器是由不知火主動向軍方訂制的裝備，據說耗費了比傳統量產型裝備多三倍的合金和尼姆比斯晶體，因此在射程、耐久度上極優，但對使用者的拉力要求極高。\n據傳四下無人時，她會以親昵的口吻稱呼自己的武器。雖然大家或多或少都有給自己武器取名的習慣，但是把武器當寵物的還是很少見的……呃，應該算少見的？", "icon_buzhihuo_zs1", "0", 2, 1, "3_{lv}*100", "不知火", "1_110021_5", 10, "3_100", "320020,320021,320022", "0", "0", "0", "0", "0", "0", "0", "0"},
[320021] = {320021, "三枝", "由不知火向軍方直接訂制的箭箱，裡面裝載的箭頭上均塗抹了可與空間摩擦直接產生熱能的塗料，箭腔內裝滿了大量的易燃易爆物，在撞擊到目標後，會產生劇烈的爆炸和高溫的火焰。\n要決定一場戰鬥的走勢，只需要三支箭就夠了。", "icon_buzhihuo_zs2", "0", 2, 2, "1_{lv}*100", "不知火", "1_110021_5", 10, "1_100", "320020,320021,320022", "0", "0", "0", "0", "0", "0", "0", "0"},
[320022] = {320022, "銃閣", "由九州總部製作的風林火山小隊專用裝甲，該裝甲擁有極高的防護且但重量極輕。\n不知火在隊伍中擔任著的“長媽媽”的位置……你問什麼是“長媽媽”？我也不是很清楚，但是我知道有另外一個小隊也有類似的存在，這個職位該不會是什麼歷史保留組合吧？", "icon_buzhihuo_zs3", "0", 2, 3, "1_{lv}*100", "不知火", "1_110021_5", 10, "1_100", "320020,320021,320022", "0", "0", "0", "0", "0", "0", "0", "0"},
[320030] = {320030, "單線制壓", "由卡佳地區最大的軍火製造商—“塞倫”製作的第一代重火力裝備，該武裝提供的初速度是同類武裝的5倍，因此穿甲能力極強。\n僅僅動用這件武器，就能對一條線路上的敵軍進行單方面的壓制。", "icon_yefugenniya_zs1", "0", 4, 1, "1_{lv}*100", "葉芙根尼婭", "1_110021_20", 10, "1_100", "320030,320031,320032", "0", "0", "0", "0", "0", "0", "0", "0"},
[320031] = {320031, "半城", "由卡佳地區最大的軍火製造商—“塞倫”製作的第一代重火力裝備，該武裝擁有輔助鎖定系統且每顆導彈均擁有自動追蹤系統，導彈內裝有大量高溫燃料。\n火力全開的葉芙根尼婭能抵得上半座城區的火力，但同時，也會摧毀半座城區。", "icon_yefugenniya_zs2", "0", 4, 2, "3_{lv}*100", "葉芙根尼婭", "1_110021_20", 10, "3_100", "320030,320031,320032", "0", "0", "0", "0", "0", "0", "0", "0"},
[320032] = {320032, "龍牙", "由卡佳地區最大的軍火製造商—“塞倫”為減少使用者因後坐力而造成打擊偏差而製作的機械外骨骼，該裝備每只機械足均裝有2個渦輪噴口、4根穩定用的鋼針，不僅能為穿著重型裝甲的駕駛員提供移動能力還兼備了減震系統。\n在龍牙的設計中，葉芙根尼婭提出希望可以有“不動”的功能，一旦動用這個能力，就意味著葉芙根尼婭不打算再繼續撤退了，她將死在這處戰場，這是她為自己選定的結局。", "icon_yefugenniya_zs3", "0", 4, 3, "3_{lv}*100", "葉芙根尼婭", "1_110021_20", 10, "3_100", "320030,320031,320032", "0", "0", "0", "0", "0", "0", "0", "0"},
[320040] = {320040, "破卻暗幕之弓", "曾經供奉在心經神社的神弓，在斬殺原罪並吸收了幻化核心後，獲得了能夠瞬間封鎖大面積的敵人行動的能力，形狀會隨著使用者的改變而改變。\n當我有資格拿起神弓時，身邊的黑暗消散了，我終於能走出神社，成為一名巫女。", "icon_huayu_zs1", "0", 2, 1, "3_{lv}*100", "花語", "1_110021_5", 10, "3_100", "320040,320041,320042", "0", "0", "0", "0", "0", "0", "0", "0"},
[320041] = {320041, "弓護", "艾吉斯設計並製造的手部裝甲，不光可以提供不錯的防護還能提升使用者的身體機能。\n直接撥動神弓的話，我的手指，乃至整個手臂會受到重傷，但是有了護臂我就可以長時間地戰鬥了。", "icon_huayu_zs2", "0", 2, 2, "1_{lv}*100", "花語", "1_110021_5", 10, "1_100", "320040,320041,320042", "0", "0", "0", "0", "0", "0", "0", "0"},
[320042] = {320042, "神之巫女", "艾吉斯設計並製造的速度型推進器，擁有可以消耗幻化核心的能量在短期內為機體提升大量動能的裝備。\n在戰場上可不能停滯不前，我是神之巫女，要為這悲慘的世界帶來最後的福音。", "icon_huayu_zs3", "0", 2, 3, "1_{lv}*100", "花語", "1_110021_5", 10, "1_100", "320040,320041,320042", "0", "0", "0", "0", "0", "0", "0", "0"},
[320050] = {320050, "復仇的曙光", "此裝備是軍火公司“塞倫”為戰士配備的單兵火力最高的裝備，擁有140發的載彈量且為雙管火力。\n“我不喜歡原罪，得請他們通通死掉才行……復仇？也許吧。”", "icon_yiliya_zs1", "0", 4, 1, "1_{lv}*100", "伊莉雅", "1_110021_20", 10, "1_100", "320050,320051,320052", "0", "0", "0", "0", "0", "0", "0", "0"},
[320051] = {320051, "幻鋼", "由軍火公司“塞倫”為肢體受傷的士兵研製的機械義肢，該義肢除了具備人體常規的機能外，根據個人需要還可以裝載少量的武器，這可以成為每個戰士的殺手鐧。\n這是我換取力量的代價，也是我唯一能抓住的希望。", "icon_yiliya_zs2", "0", 4, 2, "1_{lv}*100", "伊莉雅", "1_110021_20", 10, "1_100", "320050,320051,320052", "0", "0", "0", "0", "0", "0", "0", "0"},
[320052] = {320052, "救濟糧", "該彈鏈箱的結構為弧形結構，可以在用最小的空間裝載最多的彈藥，且整個裝備的負重較低，但有一定概率的卡彈風險，尤其在自然環境惡劣的情況下使用。\n“這些是要拿去喂原罪的小零食。”", "icon_yiliya_zs3", "0", 4, 3, "1_{lv}*100", "伊莉雅", "1_110021_20", 10, "1_100", "320050,320051,320052", "0", "0", "0", "0", "0", "0", "0", "0"},
[320070] = {320070, "高掌遠蹠萱花臂", "由九州總部特研科為火力型駕駛員研發的外骨骼，該裝甲可以將幻化核心提供的能量轉化為高溫鐳射噴射出去，擁有融化一切的能力。\n少見的外骨骼裝備，使用難度很高，如果不能把它運用得如臂指使，不建議投入真正的戰場。", "icon_huameng_zs1", "0", 2, 1, "3_{lv}*100", "華夢", "1_110021_5", 10, "3_100", "320070,320071,320072", "0", "0", "0", "0", "0", "0", "0", "0"},
[320071] = {320071, "開而為兩祂心通", "由九州總部特研科研制的一種通信裝置，在一代的基礎上增加了防幹擾系統。\n身為【武癡】的華戀，不夠純粹……因為她至少還能與隊友溝通，聽從安排。", "icon_huameng_zs2", "0", 2, 2, "3_{lv}*100", "華夢", "1_110021_5", 10, "3_100", "320070,320071,320072", "0", "0", "0", "0", "0", "0", "0", "0"},
[320072] = {320072, "鳳凰穿花奇巧足", "由九州總部特研科為駕駛員研發的外骨骼，該裝甲採用高密度的鈦合金打造而成，可以為使用者提供足夠的防護能力。\n華夢的肯定.jpg", "icon_huameng_zs3", "0", 2, 3, "1_{lv}*100", "華夢", "1_110021_5", 10, "1_100", "320070,320071,320072", "0", "0", "0", "0", "0", "0", "0", "0"},
[320080] = {320080, "帶來力量的東西", "該液體主要是以幻化核心為材料通過加工而成的一種燃料，據說使用效率比起固體更高。\n默默一直堅信這個是足以改變世界的技術。", "icon_bailimomo_zs1", "0", 3, 1, "1_{lv}*100", "百里默默", "1_110021_10", 10, "1_100", "320080,320081,320082", "0", "0", "0", "0", "0", "0", "0", "0"},
[320081] = {320081, "天下第一可愛", "這個東西是默默使用神秘的材料編制而成，據說其一，帶在頭上讓人感覺非常清爽，但是艾吉斯的同事總覺得這個發箍像是女性的衣物。\n據說其二，能偵測身邊一切事物的可愛力，並轉化為具體的數值。", "icon_bailimomo_zs2", "0", 3, 2, "1_{lv}*100", "百里默默", "1_110021_10", 10, "1_100", "320080,320081,320082", "0", "0", "0", "0", "0", "0", "0", "0"},
[320082] = {320082, "可愛力抑制器", "由於默默的力量實在過於強大，該裝備的作用是限制默默與機甲的同頻數據，以防止出現難以控制的災難。\n據說其一，一旦解除封印，隊友就會受不了百里默默的可愛，幹擾大家的作戰。", "icon_bailimomo_zs3", "0", 3, 3, "1_{lv}*100", "百里默默", "1_110021_10", 10, "1_100", "320080,320081,320082", "0", "0", "0", "0", "0", "0", "0", "0"},
[320090] = {320090, "雪渦妖精", "由卡佳地區最大的軍火製造商—“塞倫”根據空勤團委託研製的輕型鐳射光炮，據說在3000度的高溫下均不會受到影響，發射能量只需要少量的核能即可，非常經濟。\n大雪天有雪妖精出沒，遇見過雪妖精的人都會變成冰棒。", "icon_maliya_zs1", "0", 3, 1, "3_{lv}*100", "瑪利亞", "1_110021_10", 10, "3_100", "320090,320091,320092", "0", "0", "0", "0", "0", "0", "0", "0"},
[320091] = {320091, "有紀念意義的帽", "由卡佳地區軍需處統一製作的軍帽，據說材料混有刺激性香料，佩戴過的駕駛員都覺得很有精神，除此之外好像沒什麼特別的。\n帽子，帽子代表著一種信念，精神。具體是什麼我也說不上來。", "icon_maliya_zs2", "0", 3, 2, "1_{lv}*100", "瑪利亞", "1_110021_10", 10, "1_100", "320090,320091,320092", "0", "0", "0", "0", "0", "0", "0", "0"},
[320092] = {320092, "防滑鞋·高跟？", "由卡佳地區軍需處統一製作的機械高跟鞋，主要針對常年在極地作戰的駕駛員研製的，除了有禦寒作用外，還擁有防滑功能。\n看不出有禦寒作用和防滑作用，還穿著特別難受的鞋子。", "icon_maliya_zs3", "0", 3, 3, "1_{lv}*100", "瑪利亞", "1_110021_10", 10, "1_100", "320090,320091,320092", "0", "0", "0", "0", "0", "0", "0", "0"},
[320100] = {320100, "隱火存燎", "由艾吉斯總部設計並製造的巨型燃燒炮，採用高強度金屬製作，專為執行隱秘行動的部隊所設計。設計初衷便是在支援隱秘行動的基礎上保證殲滅力，裝填特質燃燒彈，產生的高溫能將幾乎所有材質熔化。\n“三分鐘，我要知道駕駛員冥火的所有資料。”", "icon_minghuo_zs1", "0", 2, 1, "3_{lv}*100", "冥火", "1_110021_5", 10, "3_100", "320100,320101,320102", "0", "0", "0", "0", "0", "0", "0", "0"},
[320101] = {320101, "無人知曉", "由艾吉斯總部設計並製造的特製金屬腿甲，相較於防禦性能，更著重於改造潛力，為滿足駕駛員個性定制的需求在裝甲上配置了介面用以配置外部裝備。\n只有忍心社的人才能互相辨認出自己人的偽裝……現在還多了一位奇怪的領航。", "icon_minghuo_zs2", "0", 2, 2, "3_{lv}*100", "冥火", "1_110021_5", 10, "3_100", "320100,320101,320102", "0", "0", "0", "0", "0", "0", "0", "0"},
[320102] = {320102, "另一個我", "由艾吉斯總部設計並製造的精神穩定裝置，由感應水晶構成，最大作用是穩定裝備者的精神，防止裝備者因精神崩壞引起暴走。\n有人能接納一體雙魂的我們嗎？", "icon_minghuo_zs3", "0", 2, 3, "3_{lv}*100", "冥火", "1_110021_5", 10, "3_100", "320100,320101,320102", "0", "0", "0", "0", "0", "0", "0", "0"},
[320110] = {320110, "業海還航", "由九州海軍兵器研究部製作的鯨型自律機甲，龐然巨軀中裝載著大量尼姆比斯能，可經由炮口蓄能發射，或於必要時從尾部噴出以達高機動效果。\n伽藍見本人更愛將其稱為“小白”，似乎源於她曾救助過的一頭抹香鯨。", "icon_jialanjian_zs1", "0", 4, 1, "1_{lv}*100", "伽藍見", "1_110021_20", 10, "1_100", "320110,320111,320112", "0", "0", "0", "0", "0", "0", "0", "0"},
[320111] = {320111, "止水澄心", "由九州海軍兵器研究部製作的水下特化作戰服，運用尖端納米技術結合新型材料打造，使表面與水體的摩擦近乎為零，穿戴者縱使全速航行也不至擾亂水流。\n“明鏡止水，方可澄心。”", "icon_jialanjian_zs2", "0", 4, 2, "3_{lv}*100", "伽藍見", "1_110021_20", 10, "3_100", "320110,320111,320112", "0", "0", "0", "0", "0", "0", "0", "0"},
[320112] = {320112, "諦觀法雨", "由九州海軍兵器研究部製作的通信天線，常時兼收全域波段。無論來自深海或天外，無論信號幅度多麼微不可聞，此裝備均能盡數辨識。\n“天音若雨，落歸鴻溟。”", "icon_jialanjian_zs3", "0", 4, 3, "1_{lv}*100", "伽藍見", "1_110021_20", 10, "1_100", "320110,320111,320112", "0", "0", "0", "0", "0", "0", "0", "0"},
[320120] = {320120, "獵食就緒", "該裝備是由多瑙支部為聚集著的原罪進行大規模打擊而設計的武裝。從幻化核心獲取能源，內部配置冷卻系統，支持各類彈藥裝填，發射彈藥種類可以根據戰局進行選擇。\n“聽我說，假如你被盯上，你最好祈禱自己從未犯下什麼錯誤。”", "icon_zhuliya_zs1", "0", 2, 1, "3_{lv}*100", "茱莉亞", "1_110021_5", 10, "3_100", "320120,320121,320122", "0", "0", "0", "0", "0", "0", "0", "0"},
[320121] = {320121, "施虐狂", "該裝備是由多瑙支部製造，配置於極少數特殊的駕駛員。盡可能減少裝甲覆蓋面以換取機動性，同時能夠將駕駛員的精神狀態反映至全身裝備。在駕駛員處於興奮狀態時能夠大幅度提升機甲性能。\n給我一個把柄，從此以後，人的生活將與你訣別，與光明說再見吧。", "icon_zhuliya_zs2", "0", 2, 2, "3_{lv}*100", "茱莉亞", "1_110021_5", 10, "3_100", "320120,320121,320122", "0", "0", "0", "0", "0", "0", "0", "0"},
[320122] = {320122, "盛放的天性", "該裝備是由多瑙支部製造，採用輕金屬設計，確保通信機能的同時能夠進行周邊隊友的位置搜索及定位。並且附帶數據分析機能，輔助駕駛員處理同時採集到的大量資訊。\n這裡簡直就是我的後花園，我很確信。還好我成為了駕駛員，駕駛員果然有趣。", "icon_zhuliya_zs3", "0", 2, 3, "1_{lv}*100", "茱莉亞", "1_110021_5", 10, "1_100", "320120,320121,320122", "0", "0", "0", "0", "0", "0", "0", "0"},
[320130] = {320130, "赴死的英雄", "薩哈拉支部所屬學院的制式武裝。薩哈拉本土製造，雖是學院配備的制式武裝，但其性能足以支撐大部分戰局。在面對大規模的原罪襲擊時也能夠做出一定程度的應對。\n“為了達成理想而獻出生命？我並不覺得這有什麼問題，但是……假如她們都能活下來，該多好啊。”", "icon_kalian_zs1", "0", 3, 1, "1_{lv}*100", "卡蓮", "1_110021_10", 10, "1_100", "320130,320131,320132", "0", "0", "0", "0", "0", "0", "0", "0"},
[320131] = {320131, "學醫誰都救不了", "薩哈拉支部所屬學院的制式腿甲。採用較輕材質製造，適合機動性較強的單位元配置。最大的特點是在側部提供了可攜式手榴彈的配置槽，能夠在提供防禦能力的同時擴大裝備者的打擊面。\n“僅僅只是作為一個醫生或者駕駛員，是不夠的，我深刻地意識到了這一點。”", "icon_kalian_zs2", "0", 3, 2, "3_{lv}*100", "卡蓮", "1_110021_10", 10, "3_100", "320130,320131,320132", "0", "0", "0", "0", "0", "0", "0", "0"},
[320132] = {320132, "白睡蓮的誓言", "薩哈拉支部所屬學院的制式指揮官型通信設備。作為學院中每人都會配備的通信設備，指揮官型在持有基本的通信定位功能外，還附加了收集戰場周邊情報的功能，因此對於裝備者的數據分析能力要求較高。\n“不滅的意志不僅僅屬於我，還屬於其他人，我會活下去，大家都會活下去。”", "icon_kalian_zs3", "0", 3, 3, "1_{lv}*100", "卡蓮", "1_110021_10", 10, "1_100", "320130,320131,320132", "0", "0", "0", "0", "0", "0", "0", "0"},
[320140] = {320140, "犬型機甲初型", "米狄爾族科技與艾吉斯機械的融合產物，控制AI使用了人格晶片技術，但是最終控制權完全掌握在其主人手裏，也就是掌握此機關的駕駛員，可以有效防止暴走的情況發生。\n在沒有戰鬥的時候，其也可以像駕駛員一樣縮小變成寵物一樣的存在。", "icon_xifalisi_zs1", "0", 2, 1, "1_{lv}*100", "西法麗斯", "1_110021_5", 10, "1_100", "320140,320141,320142", "0", "0", "0", "0", "0", "0", "0", "0"},
[320141] = {320141, "環境感應手套", "米狄爾族科技製造的手套裝備，內置了小型的仿製米狄爾增幅水晶，通過精神力可以對周圍1公里範圍內的事物進行探查。但是對精神力要求極高，目前只有幾位米狄爾族的駕駛員可以使用。\n“通過雙手獲得的感受更加真實，也更加殘酷。”", "icon_xifalisi_zs2", "0", 2, 2, "3_{lv}*100", "西法麗斯", "1_110021_5", 10, "3_100", "320140,320141,320142", "0", "0", "0", "0", "0", "0", "0", "0"},
[320142] = {320142, "思維傳導器", "米狄爾族科技製造的思維傳導器，內置仿製的米狄爾增幅水晶，可以將使用者的想法傳遞到接受控制的裝備上，目前僅用來控制“夥伴戰鬥機關”在戰鬥的時候發出指令。\n“我心裏的秘密可不能被別人知道。”", "icon_xifalisi_zs3", "0", 2, 3, "1_{lv}*100", "西法麗斯", "1_110021_5", 10, "1_100", "320140,320141,320142", "0", "0", "0", "0", "0", "0", "0", "0"},
[320150] = {320150, "多瑙之花", "由艾吉斯支部—多瑙支部研究室專為多瑙第一親衛班打造的武器。擁有獨特的傘狀外形，實則是火力控制的中樞，通過該傘可以有效整合全身配備的火力。當然由於傘柄使用鈦合金打造，在近身戰鬥方面的效果也不錯。\n多瑙的公主，多瑙之花……都是些虛無的頭銜而已。", "icon_weisipaer_zs1", "0", 3, 1, "1_{lv}*100", "薇絲帕爾", "1_110021_10", 10, "1_100", "320150,320151,320152", "0", "0", "0", "0", "0", "0", "0", "0"},
[320151] = {320151, "戰鬥服·女僕型", "由艾吉斯支部—多瑙支部研究室專為多瑙第一親衛班打造的戰鬥服。別看好像只是柔軟的布料，其實裡面摻雜了很多柔性金屬，在保證舒適的同時也提供了不俗的抗打擊能力。\n兼備舒適和防護，雖不知是誰的惡趣味，這件女僕裝倒也符合貴族的標準。", "icon_weisipaer_zs2", "0", 3, 2, "3_{lv}*100", "薇絲帕爾", "1_110021_10", 10, "3_100", "320150,320151,320152", "0", "0", "0", "0", "0", "0", "0", "0"},
[320152] = {320152, "先驅者", "由艾吉斯支部—多瑙支部研究室專為多瑙第一親衛班打造的動力裝置。比起速度更加注重穩定，憑藉內部的重力模組可以讓駕駛員在身輕如燕和不動如山兩種狀態間自由切換，非常適合火力型駕駛員使用。\n在過去，貴族一直是先驅的代表，不知何時貴族成為了守舊的象徵。", "icon_weisipaer_zs3", "0", 3, 3, "1_{lv}*100", "薇絲帕爾", "1_110021_10", 10, "1_100", "320150,320151,320152", "0", "0", "0", "0", "0", "0", "0", "0"},
[320160] = {320160, "星群之光", "由艾吉斯九州總部研發部為絞皇大隊開發的裝備，外形參考了舞臺上的燈光系統。雖然看上去只是一個舞臺燈但是其實是個擁有超高圖元的攝像頭，通過反重力裝置懸浮在戰場高處可以敏銳捕捉到敵人的風吹草動。\n來自星星的光芒照亮整個舞臺。", "icon_saladisuoni_zs1", "0", 2, 1, "3_{lv}*100", "薩拉蒂", "1_110021_5", 10, "3_100", "320160,320161,320162", "0", "0", "0", "0", "0", "0", "0", "0"},
[320161] = {320161, "刻耳柏洛斯之耳", "由艾吉斯九州總部研發部為絞皇大隊開發的通訊器，同時也是個擁有極強隔音效果的耳機，戴上之後可以將外界的一切聲音都隔絕，只能聽見內部播音設備傳來的聲音。這樣可以保證使用者不受外界的幹擾，當然也就不能及時發現靠近的危險，所以需要在絕對安全的情況下使用，比如在可靠的隊友身邊。\n之所以沉浸在音樂的世界裡，還不是因為現實太無聊了。", "icon_saladisuoni_zs2", "0", 2, 2, "3_{lv}*100", "薩拉蒂", "1_110021_5", 10, "3_100", "320160,320161,320162", "0", "0", "0", "0", "0", "0", "0", "0"},
[320162] = {320162, "深淵掌控", "由艾吉斯九州總部研發部為絞皇大隊開發的火力武器，通過高頻振動來發射威力巨大的音波，對目標進行攻擊。為了方便使用特意將其控制臺做成打碟機的操作方式，使用者還可以將自己喜歡的音樂加載入樂庫作為攻擊時的伴奏。\n還好周圍的居民已經全部撤離，不然就要被告擾民了。", "icon_saladisuoni_zs3", "0", 2, 3, "1_{lv}*100", "薩拉蒂", "1_110021_5", 10, "1_100", "320160,320161,320162", "0", "0", "0", "0", "0", "0", "0", "0"},
[320170] = {320170, "鈴的夏天", "鈴的泳圈，在鈴尚未學會游泳之前購買的泳圈，即使現在已經學會游泳，每年夏天鈴還是會帶上它，順便一提，為這個泳圈買單的是彩華。\n賦予了鈴安全感的寶物。", "icon_yongzhuangling_zs1", "0", 4, 1, "1_{lv}*100", "鈴", "1_110021_20", 10, "1_100", "320170,320171,320172", "0", "0", "0", "0", "0", "0", "0", "0"},
[320171] = {320171, "狐丸（泳裝版）", "只有在夏天才會出現的狐丸，溺寵鈴的天華閣成員帶給鈴的禮物，由科學官重新設計的新型號，可不要小看它，雖然有著玩具的外貌，卻不要小看它的“小驚喜”。\n究竟是誰往這個狐丸裡加的攻擊模組？！", "icon_yongzhuangling_zs2", "0", 4, 2, "1_{lv}*100", "鈴", "1_110021_20", 10, "1_100", "320170,320171,320172", "0", "0", "0", "0", "0", "0", "0", "0"},
[320172] = {320172, "陽光停駐之地", "鈴因為想要直視太陽而委託科學官製作的特殊墨鏡，後來她發現即使戴著墨鏡看太陽還是會讓人暈呼呼的，於是放棄了，現在作為普通的護目墨鏡待在鈴的身邊。\n在墨鏡的眼鏡腿上寫著一行字，其大意為“不可直視。”", "icon_yongzhuangling_zs3", "0", 4, 3, "1_{lv}*100", "鈴", "1_110021_20", 10, "1_100", "320170,320171,320172", "0", "0", "0", "0", "0", "0", "0", "0"},
[320180] = {320180, "星弧棧橋", "希夏的AVG武裝，由她自己親自設計，據說靈感源於某部科幻電影中的太空飛船，雖名為橋，卻可以釋放能量光束。\n如何將太空中的棧橋造型設計運用在地面上呢？希夏為此苦惱著。", "icon_xixia_zs1", "0", 4, 1, "1_{lv}*100", "希夏", "1_110021_20", 10, "1_100", "320180,320181,320182", "0", "0", "0", "0", "0", "0", "0", "0"},
[320181] = {320181, "巨大鳶尾", "希夏的AVG武裝，用於接收資訊。以珀因雷德峽穀間的鳶尾花作為造型，原因是鳶尾花那有關彩虹女神的傳說。\n希夏平時也會戴著鳶尾花髮飾，多數時間是工藝首飾，在應季時則會佩戴真正的鮮花。", "icon_xixia_zs2", "0", 4, 2, "1_{lv}*100", "希夏", "1_110021_20", 10, "1_100", "320180,320181,320182", "0", "0", "0", "0", "0", "0", "0", "0"},
[320182] = {320182, "築夢黑箱", "希夏的AVG武裝，箱中裝有許多大型機械，便於她根據戰略指示，隨時隨地建造軍事工程。\n雖是工具箱，卻刻意設計成全黑的模樣，讓人乍一看還以為藏著什麼危險東西。", "icon_xixia_zs3", "0", 4, 3, "1_{lv}*100", "希夏", "1_110021_20", 10, "1_100", "320180,320181,320182", "0", "0", "0", "0", "0", "0", "0", "0"},
[320190] = {320190, "監管者", "由奧德賽重工為黑荊棘小隊研發製作的戰術頭盔。頭盔內置的目鏡集成了夜視，熱成像，尼姆比斯探測等多種戰術功能，可以讓使用者應對各種類型的戰鬥。但是需要注意的是尼姆比斯探測的精准度可能會受到駕駛員本身的幹擾並且會有暴露自身位置的風險，並不推薦頻繁使用。\n我們不可能看到黑暗，這不符合眼睛的光學結構。", "icon_kaiteling_zs1", "0", 4, 1, "1_{lv}*100", "凱特琳", "1_110021_20", 10, "1_100", "320190,320191,320192", "0", "0", "0", "0", "0", "0", "0", "0"},
[320191] = {320191, "守護者", "由奧德賽重工為黑荊棘小隊研發製作的戰衣。用高分子材料編織的布料可以起到單向的防彈效果，衍生到巨大化戰場上能夠抵抗原罪的部分攻擊。同時黑色的著裝風格也是黑荊棘小隊的標誌性特徵之一。\n荊棘是守護的外衣。", "icon_kaiteling_zs2", "0", 4, 2, "1_{lv}*100", "凱特琳", "1_110021_20", 10, "1_100", "320190,320191,320192", "0", "0", "0", "0", "0", "0", "0", "0"},
[320192] = {320192, "滅絕者", "由奧德賽重工為凱特琳研發製作的遠端狙殺型武器。為了承載足夠大的尼姆比斯能量流速而將整個的體積擴大到一個誇張的地步，以此換來的是對原罪精英單位的絕對消滅，據說連准罪級的裝甲都扛不住這一槍的威力。\n滅絕它們，為了保護我們。", "icon_kaiteling_zs3", "0", 4, 3, "1_{lv}*100", "凱特琳", "1_110021_20", 10, "1_100", "320190,320191,320192", "0", "0", "0", "0", "0", "0", "0", "0"},
[320200] = {320200, "全感應浮游炮", "米狄爾族科技製造的量子浮游炮，通過與駕駛員精神感應進行操控。待機狀態時可以從幻化核心中補充能量，攻擊是會分散成粒子狀在目標附近出現以達到精確打擊的效果。\n“猜猜我是誰？猜錯的話就把你被分解掉。”", "icon_fuluoweila_zs1", "0", 4, 1, "1_{lv}*100", "弗洛維拉", "1_110021_20", 10, "1_100", "320200,320201,320202", "0", "0", "0", "0", "0", "0", "0", "0"},
[320201] = {320201, "全感應浮游環", "米狄爾族科技製造的浮游環，能夠在駕駛員戰鬥中即時收集周邊環境資訊傳輸給駕駛員，輔助其做出合理的決策。同時也能幫助定位，在視力受阻的情況下規劃行進路線。\n“若此後再無燈火，我就是唯一的光。”", "icon_fuluoweila_zs2", "0", 4, 2, "1_{lv}*100", "弗洛維拉", "1_110021_20", 10, "1_100", "320200,320201,320202", "0", "0", "0", "0", "0", "0", "0", "0"},
[320202] = {320202, "精神力增幅水晶", "米狄爾族科技製造的增幅器，原理是模仿米狄爾星的一種水晶礦石的結構，可以大幅強化米狄爾族人的精神感應能力。由於目前的製作工藝複雜而且僅對米狄爾人有效的特性，所以存量並不富裕，處於回收順位元最高，需要不計代價保全的裝備。\n“我感受到那如同野獸一般無序但是殘忍的思維。”", "icon_fuluoweila_zs3", "0", 4, 3, "1_{lv}*100", "弗洛維拉", "1_110021_20", 10, "1_100", "320200,320201,320202", "0", "0", "0", "0", "0", "0", "0", "0"},
[320210] = {320210, "音者自吟", "九洲研發部以韶音提交的設計手稿為基礎，稍加修改，製作而成的炮擊裝置。由於設計本身極具特色，現已被編寫進教材，供實習員翻閱學習。\n弦吟以軍號，炮鳴以告捷。", "icon_shaoyin_zs1", "0", 4, 1, "1_{lv}*100", "韶音", "1_110021_20", 10, "1_100", "320210,320211,320212", "0", "0", "0", "0", "0", "0", "0", "0"},
[320211] = {320211, "騎物自奇", "九洲研發部以韶音提交的設計手稿為基礎，加以改造、完善，製作而成的運輸裝備。該裝置看似笨重，實則由新型輕質材料鑄造，在戰場上移動極其靈敏。\n干戈間來去自若，確為奇物。", "icon_shaoyin_zs2", "0", 4, 2, "1_{lv}*100", "韶音", "1_110021_20", 10, "1_100", "320210,320211,320212", "0", "0", "0", "0", "0", "0", "0", "0"},
[320212] = {320212, "智士自知", "九洲研發部以韶音提交的設計手稿為基礎，加以改造、完善，製作而成的輔助配件。內置人工智慧系統，可輔助韶音開展多線程工作，從而提高大腦使用率。\n知者不自知，亦為無智。", "icon_shaoyin_zs3", "0", 4, 3, "1_{lv}*100", "韶音", "1_110021_20", 10, "1_100", "320210,320211,320212", "0", "0", "0", "0", "0", "0", "0", "0"},
[320220] = {320220, "白翼", "由艾吉斯支部—多瑙支部研究室專為鐵鴉成員萊帕尼打造的浮游機體，造型上為了貼合使用者的氣質與容貌，選擇了更具“天使”風格的方案。然而見識了炮火強度的人都一致認為它和“天使”兩字沾不上邊。\n“這該不會是懲戒天使的翅膀吧……”", "icon_laipani_zs1", "0", 4, 1, "1_{lv}*100", "萊帕尼", "1_110021_20", 10, "1_100", "320220,320221,320222", "0", "0", "0", "0", "0", "0", "0", "0"},
[320221] = {320221, "不低", "由艾吉斯支部—多瑙支部研究室專為鐵鴉成員萊帕尼打造的作戰裝甲，造型上為了貼合使用者的氣質與容貌，選擇了更具“天使”風格的方案。在抵消或減輕敵方攻擊的同時，也保證了駕駛員的活動便捷度，讓其得以發揮出最大的戰力。\n“嗚哇，這裝甲覆蓋率會不會太低了點？”", "icon_laipani_zs2", "0", 4, 2, "3_{lv}*100", "萊帕尼", "1_110021_20", 10, "3_100", "320220,320221,320222", "0", "0", "0", "0", "0", "0", "0", "0"},
[320222] = {320222, "我，天使", "由艾吉斯支部—多瑙支部研究室專為鐵鴉成員萊帕尼打造的武器控制器，造型上為了貼合使用者的氣質與容貌，選擇了更具“天使”風格的方案。內置腦波傳動系統，可通過精神感應波作出遙控，十分便利。\n“還挺可愛的呢……除了名字。”", "icon_laipani_zs3", "0", 4, 3, "1_{lv}*100", "萊帕尼", "1_110021_20", 10, "1_100", "320220,320221,320222", "0", "0", "0", "0", "0", "0", "0", "0"},
[320230] = {320230, "引力潮汐效應", "薩哈拉學院的工程科的老師與學生共同研製的偵察通訊裝置。在絕大多數的環境下都能保持信號的穩定，以便隨時接受從前方傳來的訊息，為超視距打擊做準備。\n海水的起落無關魚蝦的沉浮，而是受控於星辰的引力。", "icon_sitila_zs1", "0", 3, 1, "1_{lv}*100", "斯緹菈", "1_110021_10", 10, "1_100", "320230,320231,320232", "0", "0", "0", "0", "0", "0", "0", "0"},
[320231] = {320231, "群星的色彩", "薩哈拉學院的工程科的老師與學生共同研製的防護裝置。原本的設計方案是通過特殊塗料達成光學迷彩的效果，但是考慮到斯緹菈實際的戰略位置，最終放棄了這個設計，著重於保暖的功能。\n群星的璀璨是永恆的虛無。", "icon_sitila_zs2", "0", 3, 2, "3_{lv}*100", "斯緹菈", "1_110021_10", 10, "3_100", "320230,320231,320232", "0", "0", "0", "0", "0", "0", "0", "0"},
[320232] = {320232, "視界之外", "薩哈拉學院的工程科的老師與學生共同研製的狙擊槍。狙擊鏡的設計上完全聽取了斯緹菈的意見，模仿天文望遠鏡的結構可以看到遠超常規狙擊鏡目視距離極限的目標。同時狙擊鏡上額外安置的小型瞄準鏡，在近距離戰鬥時可以提供更舒適的視野。\n比起操使她與敵人戰鬥，我更希望用她仰望星辰。", "icon_sitila_zs3", "0", 3, 3, "1_{lv}*100", "斯緹菈", "1_110021_10", 10, "1_100", "320230,320231,320232", "0", "0", "0", "0", "0", "0", "0", "0"},
[320240] = {320240, "為夏日所祈福", "女主角宇宙少有的無害執念體，弗蘭卡的王牌之一，有傳聞說這是由弗蘭卡自己的執念所催生的執念體。據說戴著這個髮飾出門的那天，必定是艷陽高照的好天氣。\n該執念體的本體是你曾經送給弗蘭卡的髮飾，被她視若珍寶。", "icon_yongzhuangfulanka_zs1", "0", 3, 1, "1_{lv}*100", "弗蘭卡·泳裝", "1_110021_10", 10, "1_100", "320240,320241,320242", "0", "0", "0", "0", "0", "0", "0", "0"},
[320241] = {320241, "古老的超古董泳衣", "伴隨著古老者走過了無盡歲月的泳衣，不管是弗蘭卡的身材還是這件泳衣都沒有任何變化，是能在博物館展覽的至寶。\n弗蘭卡雖然對自己的身材沒有什麼意見——絕對沒有什麼意見，但偶爾也是會想，要是自己再發育一下會怎麼樣。", "icon_yongzhuangfulanka_zs2", "0", 3, 2, "1_{lv}*100", "弗蘭卡·泳裝", "1_110021_10", 10, "1_100", "320240,320241,320242", "0", "0", "0", "0", "0", "0", "0", "0"},
[320242] = {320242, "天真無邪者", "讓本就看起來很無害的弗蘭卡更加小孩子氣的鞋子。是舉世無雙的陷阱，誰能想到這樣的天真無邪者生氣起來的時候能一拳把星球打爆。\n多瑙特別聯合部隊中最有話語權的是生氣時候的弗蘭卡。", "icon_yongzhuangfulanka_zs3", "0", 3, 3, "1_{lv}*100", "弗蘭卡·泳裝", "1_110021_10", 10, "1_100", "320240,320241,320242", "0", "0", "0", "0", "0", "0", "0", "0"},
[320250] = {320250, "平庸者的反抗", "在艾吉斯中最常見的一款浮游炮，專為偵察、戰鬥和支援任務設計，具備高機動性和多功能性，能夠在戰鬥中自動調節位置，並通過與操作者的神經鏈接實現精准打擊。/n即使是最常見的武器，只要操作得當，一樣能發揮出卓越的效果。", "icon_feiling_zs1", "0", 3, 1, "1_{lv}*100", "菲琳", "1_110021_10", 10, "1_100", "320250,320251,320252", "0", "0", "0", "0", "0", "0", "0", "0"},
[320251] = {320251, "平庸者的過去", "即便在加入卡佳支部，成為隸屬第一研究室的第一研究室行動隊的一員後，菲琳也沒有更換制服的打算——這身制服承載了她的過去。/n有些傷痕永遠無法痊癒，但只要接受它，它就不再是傷痕，而是裝飾。", "icon_feiling_zs2", "0", 3, 2, "3_{lv}*100", "菲琳", "1_110021_10", 10, "3_100", "320250,320251,320252", "0", "0", "0", "0", "0", "0", "0", "0"},
[320252] = {320252, "平庸者的福音", "原型是艾吉斯最為常見的駕駛員通訊設備，但在菲琳加入卡佳支部後得到了一定程度上的強化改造，現集成了通訊、資訊處理、環境感知和增強現實顯示等多種功能，是菲琳執行任務時必不可少的夥伴。/n從來沒想過，現實居然能如此清晰。", "icon_feiling_zs3", "0", 3, 3, "1_{lv}*100", "菲琳", "1_110021_10", 10, "1_100", "320250,320251,320252", "0", "0", "0", "0", "0", "0", "0", "0"},
[320260] = {320260, "勝利衝鋒號（暫定名）", "對於莉法而言，摩托車即是代步工具，又是備用能源。其中內置了幻化核心可以延長幻化的時間。\n今天的莉法小姐，也在駕駛著勝利衝鋒號（暫定名）拯救世界。", "icon_lifajiche_zs1", "0", 4, 1, "1_{lv}*100", "莉法·騎行服", "1_110021_20", 10, "1_100", "320260,320261,320262", "0", "0", "0", "0", "0", "0", "0", "0"},
[320261] = {320261, "無頭盔時間", "拋去頭盔之後露出的真面目，讓人不禁疑惑這麼長的頭髮是如何被包容在小小的頭盔裡的。莉法本人更鍾愛現在這個形態。\n“為什麼會有人說我頭盔下不應該有腦袋？”", "icon_lifajiche_zs2", "0", 4, 2, "1_{lv}*100", "莉法·騎行服", "1_110021_20", 10, "1_100", "320260,320261,320262", "0", "0", "0", "0", "0", "0", "0", "0"},
[320262] = {320262, "沒有臭味", "這種款式的靴子穿著時間稍微長一點就會有臭味，在經歷了2年的技術難關攻克之後，現在的靴子即使穿著24小時也不會有臭味。\n“這項技術必須要傳播出去，造福人類。”", "icon_lifajiche_zs3", "0", 4, 3, "1_{lv}*100", "莉法·騎行服", "1_110021_20", 10, "1_100", "320260,320261,320262", "0", "0", "0", "0", "0", "0", "0", "0"},
[320270] = {320270, "葡萄果汁", "克裡姆最喜歡喝的東西，由第一研究室設計改進後錄入藍圖，使用方法只有克裏姆自己知道。至於為什麼會選這個“東西”，恐怕是負責的設計師也喝多了。\n更喜歡喝小麥果汁。", "icon_sdkelimu_zs1", "0", 3, 1, "1_{lv}*100", "克裡姆·耶誕節", "1_110021_10", 10, "1_100", "320270,320271,320272", "0", "0", "0", "0", "0", "0", "0", "0"},
[320271] = {320271, "聖誕節氛圍", "克裡姆珍藏的一件紅色大衣，有很多細小的破洞但是都被克裏姆補上了，只有在聖誕節期間才會被拿出來穿。\n好像沒了這件紅色大衣聖誕節就不是聖誕節了一樣。", "icon_sdkelimu_zs3", "0", 3, 2, "1_{lv}*100", "克裡姆·耶誕節", "1_110021_10", 10, "1_100", "320270,320271,320272", "0", "0", "0", "0", "0", "0", "0", "0"},
[320272] = {320272, "空無一物的禮物袋", "克裡姆背在身後的禮物袋，是和大衣配套的裝飾品？在錄入藍圖後塞入了大量功能模組，成了個名副其實的禮物袋。\n鼓鼓囊囊的袋子，95%的內容物是氮氣。", "icon_sdkelimu_zs2", "0", 3, 3, "1_{lv}*100", "克裡姆·耶誕節", "1_110021_10", 10, "1_100", "320270,320271,320272", "0", "0", "0", "0", "0", "0", "0", "0"},
[320280] = {320280, "巧克力製匕首", "這是一場發生在情人節前夕的兇殺案，犯人在廚房用早就準備好的冰凍巧克力制匕首殺死了受害人，然後把巧克力匕首融化了毀滅了兇器。\n總之，未來是打算偵破這樣的案件，真的會有這樣的案件發生嗎……", "icon_weilaiqrj_zs1", "0", 4, 1, "1_{lv}*100", "未來·情人節", "1_110021_20", 10, "1_100", "320280,320281,320282", "0", "0", "0", "0", "0", "0", "0", "0"},
[320281] = {320281, "成為“偵探”的帽子", "戴上帽子後就會成為“超級戀愛偵探助手”，摘下帽子就是普通人。所以未來在遇到“案件”的時候都會嘟囔著“好麻煩啊~”把帽子摘了。\n不知道為什麼戴上帽子的時候，“事件”就源源不斷地冒出來。為什麼？", "icon_weilaiqrj_zs2", "0", 4, 2, "3_{lv}*100", "未來·情人節", "1_110021_20", 10, "3_100", "320280,320281,320282", "0", "0", "0", "0", "0", "0", "0", "0"},
[320282] = {320282, "準備逃跑", "超級戀愛偵探助手未來對客人和嫌犯的著裝和態度都十分敏感，能注意到衣著風格、污染（例如靴子上的土塊），心理活動、物理反應，並由此推斷出之前的經過和最近的歷史。\n當她推斷出事情會很棘手的時候就會開始推脫，不想接受委託。“我只是在cosplay而已！”", "icon_weilaiqrj_zs3", "0", 4, 3, "7_{lv}*100", "未來·情人節", "1_110021_20", 10, "7_100", "320280,320281,320282", "0", "0", "0", "0", "0", "0", "0", "0"},
[320290] = {320290, "野貓", "你走在小巷裡，腳步輕快，直到一團模糊的影子在前方晃了一下——是一隻野貓。\n它渾身是雜亂的毛，灰撲撲的，看起來像是個經歷過不少風霜的流浪者。但它的眼睛卻異常明亮，像是天色未暗盡時閃爍的星子。它停在原地，歪頭看你，尾巴慢悠悠地掃過地面。", "icon_dafululu_zs2", "0", 4, 1, "3_{lv}*100", "芙露露", "1_110021_20", 10, "3_100", "320290,320291,320292", "0", "0", "0", "0", "0", "0", "0", "0"},
[320291] = {320291, "三十歲的貓", "你蹲下來，朝它伸出手，指尖輕輕摩挲著空氣，學著貓的聲音“喵”了一下。\n野貓眨了眨眼，踱著步子靠近你幾分，鼻尖嗅了嗅你的指尖，隨後猛地甩開尾巴，像是對你暫且認可了。", "icon_dafululu_zs1", "0", 4, 2, "1_{lv}*100", "芙露露", "1_110021_20", 10, "1_100", "320290,320291,320292", "0", "0", "0", "0", "0", "0", "0", "0"},
[320292] = {320292, "貓的憂鬱", "它乾脆翻了個身，露出毛茸茸的肚子，四爪在空中輕輕蹬著，喉嚨裡發出一聲滿足的咕嚕聲。\n風吹起了你的髮絲，也帶起了貓柔軟的毛。你忍不住伸手，輕輕地摸了摸它的腦袋，它微微眯起眼，象徵性地用爪子輕拍了一下你的手指，力度輕得像羽毛拂過。你忍不住想，或許在這條寂靜的街巷裡，在這個短暫的時刻，你們彼此都是對方的歸宿。", "icon_dafululu_zs3", "0", 4, 3, "1_{lv}*100", "芙露露", "1_110021_20", 10, "1_100", "320290,320291,320292", "0", "0", "0", "0", "0", "0", "0", "0"},
[320300] = {320300, "武裝小町", "由艾吉斯科學部為東日萬凜打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n得益于日萬凜的能力，科學部不必特別為她準備武器，多出來的能量預計會用在強化裝甲的其他部件上。", "icon_dongriwanlin_zs1", "0", 4, 1, "1_{lv}*100", "東日萬凜", "1_110021_20", 10, "1_100", "320300,320301,320302", "0", "0", "0", "0", "0", "0", "0", "0"},
[320301] = {320301, "日萬凜特製隊服", "由艾吉斯科學部為東日萬凜打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n配合日萬凜的能力極大化特化了靈活性的裝甲。", "icon_dongriwanlin_zs2", "0", 4, 2, "3_{lv}*100", "東日萬凜", "1_110021_20", 10, "3_100", "320300,320301,320302", "0", "0", "0", "0", "0", "0", "0", "0"},
[320302] = {320302, "日萬凜特製腿甲", "由艾吉斯科學部為東日萬凜打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n科學官們把大部分的時間都投入到了腿甲性能的設計與爭論中……", "icon_dongriwanlin_zs3", "0", 4, 3, "1_{lv}*100", "東日萬凜", "1_110021_20", 10, "1_100", "320300,320301,320302", "0", "0", "0", "0", "0", "0", "0", "0"},
[320310] = {320310, "盛大登場的穿徹撕裂之弩", "世界上地獄、冥府之類的東西存在嗎？惡人轉世之後還會是惡人嗎？世界上壞人的數量是不是永遠不會減少？\n如果是的話就好了。壞人永遠都殺不盡，我轉世之後還能繼續殺。", "icon_moqianqiu_zs1", "0", 4, 1, "1_{lv}*100", "千秋·特裝", "1_110021_20", 10, "1_100", "320310,320311,320312", "0", "0", "0", "0", "0", "0", "0", "0"},
[320311] = {320311, "無光之翼", "所謂的社會敗類，即品行低劣者。當一群品行低劣者互相毆打搏殺的時候不會有人為他們惋惜，也不會有人為他們喝彩。他們是人類的孩子，他們是人類的父母，但他們不是人類。\n睜眼如此，閉眼如此。", "icon_moqianqiu_zs2", "0", 4, 2, "3_{lv}*100", "千秋·特裝", "1_110021_20", 10, "3_100", "320310,320311,320312", "0", "0", "0", "0", "0", "0", "0", "0"},
[320312] = {320312, "咆哮之靴", "我堅信變得幸福的道路是不存在的。\n時間流逝，如不咆哮便死去吧。", "icon_moqianqiu_zs3", "0", 4, 3, "1_{lv}*100", "千秋·特裝", "1_110021_20", 10, "1_100", "320310,320311,320312", "0", "0", "0", "0", "0", "0", "0", "0"},
[320320] = {320320, "“魔杖”", "伊妲的自製武器，可以視情況不同而裝填不同的彈藥，伊妲使用最多的還是可以造成大範圍無死角殺傷的龍息彈。\n木制，能夠釋放火焰，需要念咒——“裝填”，這不是魔杖是什麼？", "icon_yida_zs1", "0", 3, 1, "1_{lv}*100", "伊妲", "1_110021_10", 10, "1_100", "320320,320321,320322", "0", "0", "0", "0", "0", "0", "0", "0"},
[320321] = {320321, "伊妲感應", "伊妲的自製視覺輔助設備，能夠自動識別周圍可能隱藏的危險，但是所顯示的危險數量未免有點太多了。\n檢測到危險對象，犬科動物幼體，攜帶病毒概率50%，請小心觸摸。", "icon_yida_zs2", "0", 3, 2, "1_{lv}*100", "伊妲", "1_110021_10", 10, "1_100", "320320,320321,320322", "0", "0", "0", "0", "0", "0", "0", "0"},
[320322] = {320322, "百出“破綻”", "伊妲的自製戰鬥服，採用了柔性金屬，看似如布料般柔軟但可以抵擋子彈，幻化成AVG裝備後可以抵禦大部分原罪的遠程攻擊。\n“破綻”百出，卻是誘人的“陷阱”。", "icon_yida_zs3", "0", 3, 3, "3_{lv}*100", "伊妲", "1_110021_10", 10, "3_100", "320320,320321,320322", "0", "0", "0", "0", "0", "0", "0", "0"},
[320330] = {320330, "業餘選手的余裕", "只要是球拍就足夠了——帶著這樣的想法而準備的球拍，手感上可能和廉價的網球拍沒有區別，但可能相當結實。\n“我是業餘網球選手，領航想贏過我還差得遠呢……嗯？”", "icon_geluoliyaqf_zs1", "0", 4, 1, "1_{lv}*100", "格洛麗亞·球服", "1_110021_20", 10, "1_100", "320330,320331,320332", "0", "0", "0", "0", "0", "0", "0", "0"},
[320331] = {320331, "角只是裝飾", "格洛麗亞為了遮陽而設計的網球帽，和普通的網球帽並沒有多大區別——非要說的話，只有帽子上的角有些特殊。\n“只是個人喜好而已。”", "icon_geluoliyaqf_zs2", "0", 4, 2, "3_{lv}*100", "格洛麗亞·球服", "1_110021_20", 10, "3_100", "320330,320331,320332", "0", "0", "0", "0", "0", "0", "0", "0"},
[320332] = {320332, "決勝服", "由格洛麗亞自行設計的服裝，主要的設計理念是輕便透氣，不影響行動。\n“要決勝的不只是網球，還有別的事情。”", "icon_geluoliyaqf_zs3", "0", 4, 3, "1_{lv}*100", "格洛麗亞·球服", "1_110021_20", 10, "1_100", "320330,320331,320332", "0", "0", "0", "0", "0", "0", "0", "0"},
[320340] = {320340, "飛行對策措施", "葉芙根尼婭在前往試用這套AVG裝甲當天被贈予的墨鏡，意外地很實用，從此就被她順手帶在身上。\n對耳朵沒有負擔，能擋風，還能有效防止雪盲。", "icon_yefugenniyadh_zs1", "0", 4, 1, "3_{lv}*100", "葉芙根尼婭·D.F.A", "1_110021_20", 10, "3_100", "320340,320341,320342", "0", "0", "0", "0", "0", "0", "0", "0"},
[320341] = {320341, "D.F.A", "“死亡從天而降”，卡佳支部的工程師為葉芙根尼婭製作的，和她以往的戰鬥風格差之千里的高速機動背包。\n即使是太陽般的人，也會想給自己的生活添點新意。", "icon_yefugenniyadh_zs2", "0", 4, 2, "7_{lv}*100", "葉芙根尼婭·D.F.A", "1_110021_20", 10, "7_100", "320340,320341,320342", "0", "0", "0", "0", "0", "0", "0", "0"},
[320342] = {320342, "PB-037D-“蜂刺”", "卡佳支部開發的試驗性對原罪武裝，在原理和實際效果上都非常類似打樁機，也支持作為普通的拳套使用。\n伊斯卡拉在看到這個設計時兩眼放光，但使用者本人更多只是鐘意于它的輕便易用。", "icon_yefugenniyadh_zs3", "0", 4, 3, "1_{lv}*100", "葉芙根尼婭·D.F.A", "1_110021_20", 10, "1_100", "320340,320341,320342", "0", "0", "0", "0", "0", "0", "0", "0"},
[320350] = {320350, "心形項鍊", "蝦夷夜雲無論在何時都隨身佩戴的項鍊。\n這背後是否有著什麼秘密，又或者只是她隨心所欲帶來的一個小小習慣，只有她自己知道。", "icon_xiayiyeyun_zs1", "0", 4, 1, "1_{lv}*100", "蝦夷夜雲", "1_110021_20", 10, "1_100", "320350,320351,320352", "0", "0", "0", "0", "0", "0", "0", "0"},
[320351] = {320351, "夜雲特製隊服", "魔防隊五番組組長蝦夷夜雲的隊服，根據她個人喜好進行了適當的修改。\n“清涼，隨風而動，這樣就是最棒的！”", "icon_xiayiyeyun_zs2", "0", 4, 2, "3_{lv}*100", "蝦夷夜雲", "1_110021_20", 10, "3_100", "320350,320351,320352", "0", "0", "0", "0", "0", "0", "0", "0"},
[320352] = {320352, "夜雲特製長靴", "魔防隊五番組組長蝦夷夜雲日常行動時穿戴的長靴。\n實際上只是普通的靴子而已，並沒有特別之處。", "icon_xiayiyeyun_zs3", "0", 4, 3, "7_{lv}*100", "蝦夷夜雲", "1_110021_20", 10, "7_100", "320350,320351,320352", "0", "0", "0", "0", "0", "0", "0", "0"},
[320360] = {320360, "執子之手", "藏在花束中的刺劍，被刺傷時還能聞到淡淡的花香。\n執子之手，與子偕老。", "icon_lilisihs_zs1", "0", 4, 1, "1_{lv}*100", "莉莉絲·婚紗", "1_110021_20", 10, "1_100", "320360,320361,320362", "0", "0", "0", "0", "0", "0", "0", "0"},
[320361] = {320361, "刻骨銘心的誓言", "白色頭紗，點綴着紫色的花朵，這樣的搭配不僅凸顯了氣質，更讓整個場景充滿浪漫的氛圍。\n最感人的誓言便是婚禮上的那一句“我也願意”。", "icon_lilisihs_zs2", "0", 4, 2, "1_{lv}*100", "莉莉絲·婚紗", "1_110021_20", 10, "1_100", "320360,320361,320362", "0", "0", "0", "0", "0", "0", "0", "0"},
[320362] = {320362, "純白的約定", "純白的婚紗，宛如冬日中最聖潔的雪景，訴說着心中最純粹的感情。\n無論未來的路有多麼崎嶇，都要攜手走過每一個難忘的瞬間。", "icon_lilisihs_zs3", "0", 4, 3, "3_{lv}*100", "莉莉絲·婚紗", "1_110021_20", 10, "3_100", "320360,320361,320362", "0", "0", "0", "0", "0", "0", "0", "0"},
[330000] = {330000, "卡普", "歐朵啦自己設計並製造的智慧型機器人原型，在搭載了同調系統後能夠在戰鬥中穩定傳輸使用者的精神力量。\n也許在不久的將來，史蒂芬妮博士就能卸下身上的部分重擔了吧。", "icon_oubeila_zs1", "0", 2, 1, "3_{lv}*100", "歐朵啦", "1_110021_5", 10, "3_100", "330000,330001,330002", "0", "0", "0", "0", "0", "0", "0", "0"},
[330001] = {330001, "禦座之盾", "歐朵啦自己設計的大型實體盾牌，以犧牲機動力的方式極大的提升了防禦力，通常來說，支援角色都可以使用，現已準備普及給適格率不高的駕駛員。\n如此一來，歐朵啦的身上就多了一份功績，這份功績在什麼時候會發揮出決定性的作用？希望永遠沒有這一天。", "icon_oubeila_zs2", "0", 2, 2, "8_{lv}*200", "歐朵啦", "1_110021_5", 10, "8_200", "330000,330001,330002", "0", "0", "0", "0", "0", "0", "0", "0"},
[330002] = {330002, "空天王座", "空天戰艦的原型試驗機，搭載有微型二代尼姆比斯反應堆，能夠在戰場上提供大量能源。\n王座上坐著一位嬌小的少女，是她的意志主宰著空天戰艦，在她的領域，敵手只有一位——", "icon_oubeila_zs3", "0", 2, 3, "8_{lv}*200", "歐朵啦", "1_110021_5", 10, "8_200", "330000,330001,330002", "0", "0", "0", "0", "0", "0", "0", "0"},
[330010] = {330010, "晨曦初生", "艾吉斯設計的同調裝置，能夠在戰鬥中穩定傳輸使用者的精神力量。\n如一縷恰好的晨曦，散發著乳白色的光揮灑在每一位與她相處的人身上，你可能沒有察覺這縷光的溫度，卻在走入陰處時感到有一絲寒冷。", "icon_fulanka_zs1", "0", 2, 1, "3_{lv}*100", "弗蘭卡", "1_110021_5", 10, "3_100", "330010,330011,330012", "0", "0", "0", "0", "0", "0", "0", "0"},
[330011] = {330011, "日懸之時", "艾吉斯設計的力場偏移裝置，可以扭曲敵人的進攻。\n即使是不起眼的她，也依然能綻放，她總是堅強而溫柔。", "icon_fulanka_zs2", "0", 2, 2, "8_{lv}*200", "弗蘭卡", "1_110021_5", 10, "8_200", "330010,330011,330012", "0", "0", "0", "0", "0", "0", "0", "0"},
[330012] = {330012, "白色的星星", "艾吉斯設計並製造的動力裝置，其內部整合了小型尼姆比斯反應堆，能夠為使用者提供大量動力。\n白色星星散發著微弱的光。", "icon_fulanka_zs3", "0", 2, 3, "8_{lv}*200", "弗蘭卡", "1_110021_5", 10, "8_200", "330010,330011,330012", "0", "0", "0", "0", "0", "0", "0", "0"},
[330020] = {330020, "愛麗絲用·九節鞭", "克雷蒂亞家設計並製造的教官軍用裝備，使用幻化核心能量轉化技術，可以將教鞭中儲存的能量注入到隊友的機甲中，以此來提高作戰效能。\n愛麗絲大小姐，她是我們唯一的繼承人，請更驕傲地抬起頭吧，我會注視著您。", "icon_dina_zs1", "0", 2, 1, "3_{lv}*100", "蒂娜", "1_110021_5", 10, "3_100", "330020,330021,330022", "0", "0", "0", "0", "0", "0", "0", "0"},
[330021] = {330021, "靜用·高位接收器", "克雷蒂亞家設計並製造的教官軍用裝備，使用幻化核心來提升信號的頻率，該裝備擁有防電磁幹擾和強大的通訊能力。\n靜大小姐，克雷蒂亞家並不會對您有特別的要求，請好好地、按照自己意願地，活成想要成為的人吧。", "icon_dina_zs2", "0", 2, 2, "3_{lv}*100", "蒂娜", "1_110021_5", 10, "3_100", "330020,330021,330022", "0", "0", "0", "0", "0", "0", "0", "0"},
[330022] = {330022, "獨一無二的兩人", "克雷蒂亞家設計並製造的教官軍用裝備，採用足量的合金，並鑲嵌了少量的幻化核心晶片，非常結實耐用。\n你們兩人都是很優秀的人呢。", "icon_dina_zs3", "0", 2, 3, "8_{lv}*200", "蒂娜", "1_110021_5", 10, "8_200", "330020,330021,330022", "0", "0", "0", "0", "0", "0", "0", "0"},
[330030] = {330030, "噴射者", "該裝備是為醫療兵種研製的一種診療工具，外觀酷似軍用步槍，以燃燒尼姆比斯能為動能，將槍管內的液體快速噴灑到友軍身上，以此達到診療的目的。\n克裡姆想把槍管內的液體換成粉紅色，被大家嚴肅、快速地制止了。", "icon_kelimu_zs1", "0", 2, 1, "3_{lv}*100", "克裡姆", "1_110021_5", 10, "3_100", "330030,330031,330032", "0", "0", "0", "0", "0", "0", "0", "0"},
[330031] = {330031, "朱可夫", "“塞倫”公司生產的第一款自律機器人，雖然造型的審美上不是很符合大眾的口味，但基本的功能還是具備的，比如航拍、彈藥攜帶，另外該機器人的主要燃料為天然氣，因此成本極低。\n從這件裝備可以看出【灰燼】的貧窮，但同時這份貧窮也是突破科研關卡的力量，用天然氣來取代了尼姆比斯能，這是艾吉斯的人從未設想的。", "icon_kelimu_zs2", "0", 2, 2, "3_{lv}*100", "克裡姆", "1_110021_5", 10, "3_100", "330030,330031,330032", "0", "0", "0", "0", "0", "0", "0", "0"},
[330032] = {330032, "飽腹的美夢", "由高密度的合金熔煉而成，擁有極厚的裝甲，但對使用者的體格有一定要求。\n克裡姆只是想讓所有人都吃飽飯……誠然這是孩子氣的話，是不可能實現的，但當大家看到為這個目標而努力的克裡姆，就不自覺地站到了她的身邊，這大概就是克裡姆的魅力吧。", "icon_kelimu_zs3", "0", 2, 3, "8_{lv}*200", "克裡姆", "1_110021_5", 10, "8_200", "330030,330031,330032", "0", "0", "0", "0", "0", "0", "0", "0"},
[330040] = {330040, "鳳鳴天紫金葫蘆", "由九州總部特研科研制的新型醫療容器，內置裝有大量的高頻液態醫療機器人，不僅可以修復肉體還能對裝甲進行修善。\n可是我的葫蘆是綠色的……", "icon_caihua_zs1", "0", 2, 1, "3_{lv}*100", "彩華", "1_110021_5", 10, "3_100", "330040,330041,330042", "0", "0", "0", "0", "0", "0", "0", "0"},
[330041] = {330041, "玉如意縛妖二極", "由九州總部特研科為支援型駕駛員研發的外骨骼，該裝甲雖然提供不了什麼防護，但是食指和中指裝有電擊設備，可以對友軍提供電療。\n不僅能提高醫療效果，還能當做拳套使用，這個醫生的體術超強的……", "icon_caihua_zs2", "0", 2, 2, "3_{lv}*100", "彩華", "1_110021_5", 10, "3_100", "330040,330041,330042", "0", "0", "0", "0", "0", "0", "0", "0"},
[330042] = {330042, "紫綬仙幡雲護衣", "由九州總部特研科為支援型駕駛員研發的外骨骼，該裝甲可以大幅度的替身穿戴者的防護能力。\n孱弱的醫生不配站在戰場，在體能與精神上總要有一項拔尖，而彩華兩者兼顧，這件裝備聽說是她為了給自己增加負重訓練而定制的。", "icon_caihua_zs3", "0", 2, 3, "8_{lv}*200", "彩華", "1_110021_5", 10, "8_200", "330040,330041,330042", "0", "0", "0", "0", "0", "0", "0", "0"},
[330050] = {330050, "天職", "由卡佳地區軍方自己研製的駕駛員用醫療注射器，該注射器由輕金屬打造而成，便於攜帶時進行高速長距離移動，旨在為隊友提供及時的支援，穩定性強能夠在各作戰環境中應用。\n這就是我的武器，而我的戰場無處不在。", "icon_reniya_zs1", "0", 4, 1, "8_{lv}*200", "熱尼亞", "1_110021_20", 10, "8_200", "330050,330051,330052", "0", "0", "0", "0", "0", "0", "0", "0"},
[330051] = {330051, "尾狀通信器", "由卡佳地區軍方自己研製的尾狀通信器，該通信器在具備基礎的通信功能上還帶有高性能的探測機能。在戰場上隨時能夠取得敵我雙方的位置及受傷狀態，以便駕駛員進行支援。\n更快地支援，這是從神明手中搶奪獵物。", "icon_reniya_zs2", "0", 4, 2, "3_{lv}*100", "熱尼亞", "1_110021_20", 10, "3_100", "330050,330051,330052", "0", "0", "0", "0", "0", "0", "0", "0"},
[330052] = {330052, "與死神的持久戰", "由卡佳地區軍方自己研製的醫療箱，為了輕便性選擇了由輕金屬製造。內置各種藥瓶和不同口徑的注射器。在提供應急處理的同時也考慮到戰場情況配置了多種提升核心活性化的藥劑。\n長線作戰醫護是我的專長，沒有人能在我的領域中勝過我，神也不行。", "icon_reniya_zs3", "0", 4, 3, "8_{lv}*200", "熱尼亞", "1_110021_20", 10, "8_200", "330050,330051,330052", "0", "0", "0", "0", "0", "0", "0", "0"},
[330060] = {330060, "神樂鈴", "曾經供奉在心經神社的神樂鈴，在淨化原罪並吸收了幻化核心後，擁有了強大的力量，獲得了能夠大範圍提升我方駕駛員幻化核心活體度的能力。\n光有信徒可無法支撐起一個神社的運營，就讓大姐姐我來吧！", "icon_yingcao_zs1", "0", 2, 1, "3_{lv}*100", "瑩草", "1_110021_5", 10, "3_100", "330060,330061,330062", "0", "0", "0", "0", "0", "0", "0", "0"},
[330061] = {330061, "心經屋的幕僚", "艾吉斯設計並製造的腿部合金裝甲，覆蓋面雖大，但為了保證穿戴者的機動力採用了較輕的材質。\n對於大姐姐我來說，支撐著這樣的兩個人也不賴呢~", "icon_yingcao_zs2", "0", 2, 2, "8_{lv}*200", "瑩草", "1_110021_5", 10, "8_200", "330060,330061,330062", "0", "0", "0", "0", "0", "0", "0", "0"},
[330062] = {330062, "不純粹的巫女", "艾吉斯設計並製造的動力裝置，通過幻化核心的能量產生巨大推進力，由於能量消耗較大因此常配備於支援型駕駛員。\n這個年代還有純粹的巫女嗎？！唔……也許隊長算一個吧……", "icon_yingcao_zs3", "0", 2, 3, "8_{lv}*200", "瑩草", "1_110021_5", 10, "8_200", "330060,330061,330062", "0", "0", "0", "0", "0", "0", "0", "0"},
[330070] = {330070, "機械天使·人偶", "此為瑪雅支部製造的機器兵器T型配備的支援型自律人偶，採用稀有金屬研製。通過與T型連接，得到幻化核心的供能作為驅動力，並能將得到的能量用來支援我方。\n人類……創造了我卻又害怕我，這究竟是為什麼……", "icon_txing_zs1", "0", 4, 1, "8_{lv}*200", "T型", "1_110021_20", 10, "8_200", "330070,330071,330072", "0", "0", "0", "0", "0", "0", "0", "0"},
[330071] = {330071, "機械天使·全裙甲", "此為瑪雅支部製造的機器兵器T型配備的裙甲，裝甲採用稀有金屬進行研製，在重視便攜性的基礎上增加了裙甲展開的功能，裙甲展開中能夠獲得全方位的防衛。\n我是……天使？……我更想成為人類。", "icon_txing_zs2", "0", 4, 2, "8_{lv}*200", "T型", "1_110021_20", 10, "8_200", "330070,330071,330072", "0", "0", "0", "0", "0", "0", "0", "0"},
[330072] = {330072, "機械天使·收集器", "此為瑪雅支部製造的機器兵器T型配備的通信裝置，採用稀有金屬進行研製。為輔助支援型自律兵器T型進行高效的支援，在我方情報的接受處理速度上進一步提升。\nT型的誕生可以用“預謀”這個詞來形容，從方案通過到產出，僅僅只有三個月，奧德賽重工到底在搞什麼啊……", "icon_txing_zs3", "0", 4, 3, "8_{lv}*200", "T型", "1_110021_20", 10, "8_200", "330070,330071,330072", "0", "0", "0", "0", "0", "0", "0", "0"},
[330080] = {330080, "聖潔之槍", "由艾吉斯多瑙支部研究室專為龍騎士配置的長槍型武裝。伴隨著龐大體積的是其驚人的衝擊力，能夠輕鬆貫穿原罪的裝甲。長槍側翼的旗幟比起實戰意義，更是信念的象徵。\n作為引導友軍的信標而閃耀光彩。", "icon_yishabeila_zs1", "0", 4, 1, "8_{lv}*200", "伊莎貝拉", "1_110021_20", 10, "8_200", "330080,330081,330082", "0", "0", "0", "0", "0", "0", "0", "0"},
[330081] = {330081, "天命角冠", "由艾吉斯多瑙支部研究室專為龍騎士配置的通信裝置。由於龍騎士存在著暴走的風險，在附帶正常通信機能的同時，也起到穩定駕駛員腦波的作用。\n絕不會漏聽一句天命。", "icon_yishabeila_zs2", "0", 4, 2, "8_{lv}*200", "伊莎貝拉", "1_110021_20", 10, "8_200", "330080,330081,330082", "0", "0", "0", "0", "0", "0", "0", "0"},
[330082] = {330082, "星尾", "由艾吉斯多瑙支部專為龍騎士配置的出力平衡裝置。由於龍騎士裝甲在維持高出力狀態時會加劇能源消耗，進而導致駕駛員對尼姆比斯渴求度增高，需要出力穩定裝置來防止暴走。\n如果尾巴在戰鬥中被切斷，也可化作新的武器。", "icon_yishabeila_zs3", "0", 4, 3, "8_{lv}*200", "伊莎貝拉", "1_110021_20", 10, "8_200", "330080,330081,330082", "0", "0", "0", "0", "0", "0", "0", "0"},
[330090] = {330090, "擴散型支援裝置", "米狄爾族科技製造的支援裝置，內置高度集成的米狄爾增幅水晶仿製品，可以擴大使用者的支援範圍，據說甚至能達到視野外。但是對使用者的精神力要求極高，目前只有米狄爾族的人勉強可以使用。\n“就算死後會上天堂，也不如活著感到幸福。”", "icon_aiyiwadi_zs1", "0", 4, 1, "3_{lv}*100", "艾伊瓦蒂", "1_110021_20", 10, "3_100", "330090,330091,330092", "0", "0", "0", "0", "0", "0", "0", "0"},
[330091] = {330091, "感應回路", "米狄爾族科技製造的戰鬥服，通過埋藏在衣服下的能量回路來加快精神力的傳導。當然這樣的代價就是犧牲了防禦能力，幾乎不比沒穿衣服強多少。但是衣服的風格據說很受米狄爾族喜歡。\n“旅行終有終點，但不應該在這裡。 ”", "icon_aiyiwadi_zs2", "0", 4, 2, "8_{lv}*200", "艾伊瓦蒂", "1_110021_20", 10, "8_200", "330090,330091,330092", "0", "0", "0", "0", "0", "0", "0", "0"},
[330092] = {330092, "支援型浮游環", "米狄爾族科技製造的浮游環，製造過程中除了使用了特製合金，還加入了一些增幅水晶的碎末以此來加強了對使用者精神力的增幅。當然標準的戰場資訊收集和通訊功能也有保留。\n“那些在我腦海中滋滋作響的雜音，或許是那些文明的迴響。”", "icon_aiyiwadi_zs3", "0", 4, 3, "8_{lv}*200", "艾伊瓦蒂", "1_110021_20", 10, "8_200", "330090,330091,330092", "0", "0", "0", "0", "0", "0", "0", "0"},
[330100] = {330100, "“小型”醫療槍", "由渠親自設計並委託瑪雅支部製作的醫療槍械，以可拆卸的液彈作為能源，將處理後的尼姆比斯射向友軍來達到遠距離治療的目的。\n“放心，中一槍不會死的。”", "icon_qu_zs1", "0", 3, 1, "8_{lv}*200", "渠", "1_110021_10", 10, "8_200", "330100,330101,330102", "0", "0", "0", "0", "0", "0", "0", "0"},
[330101] = {330101, "“靈耳”", "由渠親自設計並委託瑪雅支部製作的通訊輔助裝置，因為渠更信賴自己的耳朵，所以該裝置只起到輔助作用，比如作為耳朵的支撐。\n“我聽到了哦，你緊張的心跳聲。”", "icon_qu_zs2", "0", 3, 2, "3_{lv}*100", "渠", "1_110021_10", 10, "3_100", "330100,330101,330102", "0", "0", "0", "0", "0", "0", "0", "0"},
[330102] = {330102, "透氣保暖靴", "由渠親自設計並委託瑪雅支部製作的靴子，主要作用是保證腿部的幹爽和舒適。\n“舒服...真舒服。”", "icon_qu_zs3", "0", 3, 3, "3_{lv}*100", "渠", "1_110021_10", 10, "3_100", "330100,330101,330102", "0", "0", "0", "0", "0", "0", "0", "0"},
[330110] = {330110, "至純金杯", "梅莉雅的AVG武裝，以聖濯教會的聖物金杯為原型製造，根據典籍所述，用其所盛的液體將用之不竭。AVG武裝的設計也以該傳說為靈感，擁有對液態尼姆比斯能利用效率極高的特點。\n梅莉雅曾試圖用聖物金杯複製液態黃金，其結果自不待言。", "icon_meiliya_zs1", "0", 4, 1, "8_{lv}*200", "梅莉雅", "1_110021_20", 10, "8_200", "330110,330111,330112", "0", "0", "0", "0", "0", "0", "0", "0"},
[330111] = {330111, "聖泉藍袍", "梅莉雅的AVG武裝，造型根據其平常任聖女一職所必須穿戴的裝束設計。衣物大面積的白色部分象徵著覆雪高山，蒼藍色的聖泉則從期間奔湧而下，啟蒙著人們的理念與美德。\n梅莉雅自己也聲稱，穿著此裝束時心情會稍微變好一些。", "icon_meiliya_zs2", "0", 4, 2, "3_{lv}*100", "梅莉雅", "1_110021_20", 10, "3_100", "330110,330111,330112", "0", "0", "0", "0", "0", "0", "0", "0"},
[330112] = {330112, "渴念紅裙", "梅莉雅的AVG武裝，按照其本人要求，造型設計得與她日常所穿的連衣裙保持一致。鮮紅的色彩象徵著人內心最為原始的慾望，而這慾望將永遠被外面那層聖袍抑制。\n“可是，真的能夠抑制住嗎？”", "icon_meiliya_zs3", "0", 4, 3, "8_{lv}*200", "梅莉雅", "1_110021_20", 10, "8_200", "330110,330111,330112", "0", "0", "0", "0", "0", "0", "0", "0"},
[330120] = {330120, "象徵意義", "就如多蘿西小姐對於這把武器的命名一樣，這把武器的象徵意義大於它的實際價值，好在這把武器足夠堅固，被如此隨意地對待，直到現在也沒有損壞。\n“究竟什麼時候才會發生呢……”", "icon_duoluoxiyongzhuang_zs1", "0", 3, 1, "8_{lv}*200", "多蘿西·泳裝", "1_110021_10", 10, "8_200", "330120,330121,330122", "0", "0", "0", "0", "0", "0", "0", "0"},
[330121] = {330121, "欺騙方案", "在每次多蘿西施法的時候，假如此次施法需要施法材料，“欺騙方案”就會“欺騙”法術，消耗一部分自己，使該次施法成功釋放。\n“咦……已經不能用了嗎，我的手鐲！”", "icon_duoluoxiyongzhuang_zs2", "0", 3, 2, "3_{lv}*100", "多蘿西·泳裝", "1_110021_10", 10, "3_100", "330120,330121,330122", "0", "0", "0", "0", "0", "0", "0", "0"},
[330122] = {330122, "“第七序列”", "多蘿西的族人稱呼她為“第七序列魔女”，認為她是預言中渡過末日的必需品，是拯救世界的第七個至關緊要的素材。多蘿西認為這是迷信，於是她逃走了。\n“……世界末日真的降臨了？！”", "icon_duoluoxiyongzhuang_zs3", "0", 3, 3, "3_{lv}*100", "多蘿西·泳裝", "1_110021_10", 10, "3_100", "330120,330121,330122", "0", "0", "0", "0", "0", "0", "0", "0"},
[330130] = {330130, "引路之針", "該裝備是一名沉迷魔法少女幻想的科學官研發出的第二代支援型裝備，裝備採用神秘的“S”金屬，據說該物質並不存於這個宇宙，因此現世的所有攻擊方式都無法摧毀這件裝備。（出自該科學官之口，真實性有待考證）儲存於核心中的尼姆比斯能量通過它會更為有效地傳遞給其他駕駛員\n希望就在前方，你將被指引著前進。", "icon_fululu_zs1", "0", 2, 1, "8_{lv}*200", "芙露露", "1_110021_5", 10, "8_200", "330130,330131,330132", "0", "0", "0", "0", "0", "0", "0", "0"},
[330131] = {330131, "期許之翼", "該裝備是一名沉迷魔法少女幻想的科學官研發出的第二代輔助型裝備，裝備是用足量的鈦合金製作而成，採用了羽翼狀設計，與同隊的其他人不同，它在提供強力的推進力的同時，也保證了更好的轉向能力，使得她在戰場上能充分發揮子的靈活性。\n想要變得更快，這樣就不會再一次錯過時間。", "icon_fululu_zs2", "0", 2, 2, "3_{lv}*100", "芙露露", "1_110021_5", 10, "3_100", "330130,330131,330132", "0", "0", "0", "0", "0", "0", "0", "0"},
[330132] = {330132, "遺棄之貓", "該裝備是一名沉迷魔法少女幻想的科學官研發出的第二代輔助型裝備，具備索敵通信機能的同時，能夠對裝備者的精神感應力起到一定的促進作用。\n她需要親情，請好好地看著她。", "icon_fululu_zs3", "0", 2, 3, "3_{lv}*100", "芙露露", "1_110021_5", 10, "3_100", "330130,330131,330132", "0", "0", "0", "0", "0", "0", "0", "0"},
[330140] = {330140, "236K的溫柔", "卡佳支部為莫莫卡定制的能量增幅器，可以提升支援型駕駛員的能量轉換效率，提供更高效的治療。同時採用卡佳專有的適寒合金作為原料，就算是極寒環境中也能保持百分百的戰鬥力。\n這是來自零下37度的溫柔", "icon_momoka_zs1", "0", 3, 1, "8_{lv}*200", "莫莫卡", "1_110021_10", 10, "8_200", "330140,330141,330142", "0", "0", "0", "0", "0", "0", "0", "0"},
[330141] = {330141, "暴雪預警", "卡佳支部為莫莫卡定制的偵測裝置，主要用於偵測潛伏在雪地之下的原罪。由於技術有限，只能對核心處於活躍狀態的原罪有效，並且在惡劣的天氣環境中，偵測的範圍和有效性會進一步降低，所以不要盲信偵測的結果。\n“暴雪預警響了，壞天氣要來了。”“得了吧，這暴雪預警什麼時候准過啊。”", "icon_momoka_zs2", "0", 3, 2, "3_{lv}*100", "莫莫卡", "1_110021_10", 10, "3_100", "330140,330141,330142", "0", "0", "0", "0", "0", "0", "0", "0"},
[330142] = {330142, "“雪橇”", "卡佳支部為莫莫卡定制的全地形機動輔助裝置，內置了小型反重力裝置，可以在短時間內提供懸浮的動力，幫助莫莫卡越過一些險峻的地形。但是使用反重力引擎運載人員對核心的消耗極大，非必要的情況下一般建議僅保持最低的待機懸浮狀態運行。\n來卡佳不坐雪橇就像去九州不吃拉麵。", "icon_momoka_zs3", "0", 3, 3, "3_{lv}*100", "莫莫卡", "1_110021_10", 10, "3_100", "330140,330141,330142", "0", "0", "0", "0", "0", "0", "0", "0"},
[330150] = {330150, "H—治癒之槍", "莉娜獨特的AVG武裝，雖說是槍械的外形，發射出的卻是治療藥物。比普通的支援裝備更有效率，但也更考驗裝備者的射擊天賦。\n“biu~biu~biu~”察覺到了你對手槍的疑惑，莉娜本人用手指比了一個對你開槍的動作，好吧，似乎她認為這樣很帥。", "icon_lina_zs1", "0", 4, 1, "8_{lv}*200", "莉娜", "1_110021_20", 10, "8_200", "330150,330151,330152", "0", "0", "0", "0", "0", "0", "0", "0"},
[330151] = {330151, "B—勇氣的傳達", "莉娜並不獨特的AVG武裝，為了更快地給予被拯救者安慰和勇氣，以及為了更快地發現救援信號，在通訊和感應方向特化的通訊器。\n“雖然比不過boy的能力就是了……”莉娜小姐似乎非常羨慕你【通感】的能力。", "icon_lina_zs2", "0", 4, 2, "3_{lv}*100", "莉娜", "1_110021_20", 10, "3_100", "330150,330151,330152", "0", "0", "0", "0", "0", "0", "0", "0"},
[330152] = {330152, "A—支援加速度", "莉娜獨特的AVG武裝，為了匹配莉娜的身體能力和在戰場上來去自如的戰鬥風格，特意為其做了速度的特化。\n“在戰場上找到傷員和即將受傷的駕駛員，然後迅速給她們一槍，就這麼簡單。”莉娜小姐曾經這樣嚇到了很多駕駛員。", "icon_lina_zs3", "0", 4, 3, "8_{lv}*200", "莉娜", "1_110021_20", 10, "8_200", "330150,330151,330152", "0", "0", "0", "0", "0", "0", "0", "0"},
[330160] = {330160, "追憶的流光", "由紅博士為多洛莉絲研發的AVG裝甲，說是研發，其實只是把之前的偶像服換了一種形式，並沒有什麼能量形態上的變化。\n“果然還是太招人的眼球了。”多洛莉絲想到。", "icon_duoluolisicf_zs1", "0", 4, 1, "8_{lv}*200", "多洛莉絲·禮服", "1_110021_20", 10, "8_200", "330160,330161,330162", "0", "0", "0", "0", "0", "0", "0", "0"},
[330161] = {330161, "現世的搖曳", "由紅博士為多洛莉絲研發的AVG裝甲，雖然沒有升級進化，但這次嘗試了支援型的形態。\n不過話說回來，偶像服形態才應該是支援型吧？", "icon_duoluolisicf_zs2", "0", 4, 2, "8_{lv}*200", "多洛莉絲·禮服", "1_110021_20", 10, "8_200", "330160,330161,330162", "0", "0", "0", "0", "0", "0", "0", "0"},
[330162] = {330162, "明日的期許", "由紅博士為多洛莉絲研發的AVG裝甲，發飾上別著一朵百合花。象徵純潔無暇，希望與新生，忠誠和永恆。\n順便提一句，在常態形態下，多洛莉絲也能發揮部分裝甲的力量，也即是說——她在現實中是超人。", "icon_duoluolisicf_zs3", "0", 4, 3, "8_{lv}*200", "多洛莉絲·禮服", "1_110021_20", 10, "8_200", "330160,330161,330162", "0", "0", "0", "0", "0", "0", "0", "0"},
[330170] = {330170, "只是一次敗北", "九十九環定制的輔助機，即使在幻化解除之後也能持續運作四個小時，行動迅捷，搭載的人工智慧可以自主規避大部分原罪，九十九環使用她來救助在戰場上因為尼姆比斯能見底而解除幻化的駕駛員。\n毫無疑問，支援型駕駛員是最適合指揮的類型。", "icon_jiushijiuhuan_zs1", "0", 3, 1, "8_{lv}*200", "九十九環", "1_110021_10", 10, "8_200", "330170,330171,330172", "0", "0", "0", "0", "0", "0", "0", "0"},
[330171] = {330171, "好感度偵測器", "克莉絲蒂娜博士根據九十九環的改造的特殊偵測器，特化了駕駛員資料的收集，以便九十九環對戰局的指揮與把握。從領航員到駕駛員，完成身份轉變的九十九環並沒有拋棄掉領航的知識。\n據說，只是據說，這款偵測器還能偵測到對某人的好感度。", "icon_jiushijiuhuan_zs2", "0", 3, 2, "3_{lv}*100", "九十九環", "1_110021_10", 10, "3_100", "330170,330171,330172", "0", "0", "0", "0", "0", "0", "0", "0"},
[330172] = {330172, "再一次嘗試", "由克莉絲蒂娜博士研發，將“好感度偵測器”收集的資料視覺化的輔助裝備，該套系統正在測試中，測試順利的話就能大批量地投入到戰鬥中使用，能極大地提升支援型駕駛員的援護能力。\n很好奇都能看到哪些資料……", "icon_jiushijiuhuan_zs3", "0", 3, 3, "3_{lv}*100", "九十九環", "1_110021_10", 10, "3_100", "330170,330171,330172", "0", "0", "0", "0", "0", "0", "0", "0"},
[330180] = {330180, "幻想型機甲初型", "米狄爾族科技與艾吉斯機械的融合產物，通過的內置米狄爾增幅水晶將機械與使用者的精神進行高度鏈接，可以通過意念直接控制機械行動，相當於延伸的肢體。\n警告：該裝備對精神力壓迫極大，僅修米婭小隊成員可使用。", "icon_mituoxiwa_zs1", "0", 3, 1, "8_{lv}*200", "密托希瓦", "1_110021_10", 10, "8_200", "330180,330181,330182", "0", "0", "0", "0", "0", "0", "0", "0"},
[330181] = {330181, "平衡型環尾", "米狄爾族科技製造的外置裝甲肢體，除了可以保持平衡之外也可以用於近身戰鬥，其材質的堅固程度不亞於目前最新的合金材料。\n千萬不要從背後靠近，相信我你不會想被這條尾巴抽打的。", "icon_mituoxiwa_zs2", "0", 3, 2, "8_{lv}*200", "密托希瓦", "1_110021_10", 10, "8_200", "330180,330181,330182", "0", "0", "0", "0", "0", "0", "0", "0"},
[330182] = {330182, "全頻率收發天線", "米狄爾族科技製造的通訊裝置，原本設計為可以接受宇宙間任何形式的信號，但是那樣的體積太大，經過簡化變為可接受全頻率無線電，體積也縮小至駕駛員可佩戴的程度。\n不要胡思亂想，會被聽到的。", "icon_mituoxiwa_zs3", "0", 3, 3, "3_{lv}*100", "密托希瓦", "1_110021_10", 10, "3_100", "330180,330181,330182", "0", "0", "0", "0", "0", "0", "0", "0"},
[330190] = {330190, "萬行盡在", "古遺物，曾經被當做至寶供奉，在這份信仰破滅之後被收納到“學宮”的寶庫中。\n朝霧選擇了它，震落了杖身上的汙穢，顯現出它本來的名字，“萬行盡在”。", "icon_zhaowu_zs1", "0", 4, 1, "8_{lv}*200", "朝霧", "1_110021_20", 10, "8_200", "330190,330191,330192", "0", "0", "0", "0", "0", "0", "0", "0"},
[330191] = {330191, "流雲舍利束瑤台", "九州的科學官應朝霧的要求為她量身設計的防護裝置，使作為支援型駕駛員的朝霧在戰場能更顯眼。\n“希望在戰場上，需要幫助的人能第一時間找到我。”。", "icon_zhaowu_zs2", "0", 4, 2, "8_{lv}*200", "朝霧", "1_110021_20", 10, "8_200", "330190,330191,330192", "0", "0", "0", "0", "0", "0", "0", "0"},
[330192] = {330192, "玲瓏美玉玲瓏鎖", "朝霧按照自己的想法幻化而成的護腿，形狀怪異，只有在朝霧身上才能發揮出色的性能。\n這是少女為了懲罰自己被背負的“懲罰”，這“懲罰”督促著她前進。", "icon_zhaowu_zs3", "0", 4, 3, "3_{lv}*100", "朝霧", "1_110021_20", 10, "3_100", "330190,330191,330192", "0", "0", "0", "0", "0", "0", "0", "0"},
[330200] = {330200, "“主體”", "記錄了大量哲學知識的機械書，可有效提供精神增幅。由質地柔韌的特殊合金打造，因此也能作為一個枕頭。\n被梅貝爾取名為“主體”，意義不明。", "icon_meibeier_zs1", "0", 3, 1, "8_{lv}*200", "梅貝爾", "1_110021_10", 10, "8_200", "330200,330201,330202", "0", "0", "0", "0", "0", "0", "0", "0"},
[330201] = {330201, "他者無音", "艾吉斯設計的通信裝置，能夠遮罩、過濾特殊敵人發出的聲波幹擾與雜音，使駕駛員更加專注地應對戰況。\n“他人即地獄，那麼兩耳不聞就好。”", "icon_meibeier_zs2", "0", 3, 2, "3_{lv}*100", "梅貝爾", "1_110021_10", 10, "3_100", "330200,330201,330202", "0", "0", "0", "0", "0", "0", "0", "0"},
[330202] = {330202, "實在壁壘", "一具智能護體裝甲，由薩拉哈蒼穹學院的學者們研製，相對於已經投入量產的制式裝甲要更加具備學術前沿性。\n阻隔虛無的侵入，方可使存在不死。", "icon_meibeier_zs3", "0", 3, 3, "3_{lv}*100", "梅貝爾", "1_110021_10", 10, "3_100", "330200,330201,330202", "0", "0", "0", "0", "0", "0", "0", "0"},
[330210] = {330210, "四維宇宙之鑰", "伯納蒂家族世代相傳的占卜用水晶球，據傳是以墜落的彗星碎片作為材料打造，可以增加與幻化核心的鏈接穩定性。\n繁星從天空隕落，未來於記憶綻開。", "icon_xingjingbonadi_zs1", "0", 3, 1, "8_{lv}*200", "星井", "1_110021_10", 10, "8_200", "330210,330211,330212", "0", "0", "0", "0", "0", "0", "0", "0"},
[330211] = {330211, "無垢淨服", "艾吉斯設計並製造的服裝，專門為那些不在一線戰鬥的駕駛員設計，為了穿戴的舒適性而捨棄了大部分防禦性能。\n雲遊袖淨，櫻染袴緋。", "icon_xingjingbonadi_zs2", "0", 3, 2, "3_{lv}*100", "星井", "1_110021_10", 10, "3_100", "330210,330211,330212", "0", "0", "0", "0", "0", "0", "0", "0"},
[330212] = {330212, "萬神終焉之門", "艾吉斯設計並製造的力場裝置，提供了一定的機動力，但是除了體積龐大比較嚇人之外好像沒有發現其他的用處。\n門的另一側，是他們的終結。", "icon_xingjingbonadi_zs3", "0", 3, 3, "8_{lv}*200", "星井", "1_110021_10", 10, "8_200", "330210,330211,330212", "0", "0", "0", "0", "0", "0", "0", "0"},
[330220] = {330220, "鐵棘鞭", "由奧德賽重工為莫妮卡研發的AVG武器，參考了節鞭的結構在保證堅硬度的同時具有良好的伸展性。原本該武器是按照攻擊型駕駛員的使用來設計，但是由於一次意外，武器設計師發現其對尼姆比斯能的激發有一定作用，於是該武器被更改為一件可怕的支援型裝備。\n你得保證她們不會反過來抽我。", "icon_monika_zs1", "0", 4, 1, "8_{lv}*200", "莫妮卡", "1_110021_20", 10, "8_200", "330220,330221,330222", "0", "0", "0", "0", "0", "0", "0", "0"},
[330221] = {330221, "假皮", "由奧德賽重工為黑荊棘小隊研發的試驗性戰衣，將擁有優秀防禦性能的材料外套上一層高纖維布料，偽裝成日常服裝。主要目的是讓整個黑荊棘小隊的風格更加貼合奧德賽重工集團的風格。但是現在該戰衣還有很多無法解決的缺陷問題，只有莫妮卡願意穿上它戰鬥。\n套上一層假皮，就好像實現了什麼人生目標一樣。", "icon_monika_zs2", "0", 4, 2, "3_{lv}*100", "莫妮卡", "1_110021_20", 10, "3_100", "330220,330221,330222", "0", "0", "0", "0", "0", "0", "0", "0"},
[330222] = {330222, "特工7號", "由奧德賽重工為黑荊棘小隊研發的通訊裝置，可以根據小隊成員的要求隨意改變外形，便於隱藏，以保證通訊時刻暢通。\n“沒有發現異常，OVER。”", "icon_monika_zs3", "0", 4, 3, "8_{lv}*200", "莫妮卡", "1_110021_20", 10, "8_200", "330220,330221,330222", "0", "0", "0", "0", "0", "0", "0", "0"},
[330230] = {330230, "喜歡都在巧克力裡", "顧名思義，用巧克力來表明心意正是情人節最重要的一個環節。只是這充滿苦澀的巧克力實在是讓人感受不到一絲一毫的愛意，但是在品嘗了很多甜膩的巧克力之後，偶爾能吃到這麼一塊苦澀的巧克力也不錯。\n“難道這是專門做出來給我解膩用的？”這個想法只在腦子裡出現了一瞬間就被否定了。", "icon_qrjlilisi_zs1", "0", 4, 1, "8_{lv}*200", "莉莉絲·情人節", "1_110021_20", 10, "8_200", "330230,330231,330232", "0", "0", "0", "0", "0", "0", "0", "0"},
[330231] = {330231, "內心的感情藏起來", "在莉莉絲通感暴走之後研製的【情人節特殊通感抑制器】，但長期使用的話似乎會有睡眠品質不好的副作用，莉莉絲本人也並不希望長期佩戴它。\n有了它就不用擔心暴走了，也就能好好地把自己內心的感情藏起來了。", "icon_qrjlilisi_zs2", "0", 4, 2, "3_{lv}*100", "莉莉絲·情人節", "1_110021_20", 10, "3_100", "330230,330231,330232", "0", "0", "0", "0", "0", "0", "0", "0"},
[330232] = {330232, "躍躍欲試的小心思", "所謂情人節女僕，就是能在烈焰中也能悍然無畏地端著盆子攪拌巧克力的強大存在，但是在這份強大在心上人面前卻蕩然無存——是不可能的。\n精心搭配的服裝，只不過是為了符合自己的審美，絕對沒有其他小心思。", "icon_qrjlilisi_zs3", "0", 4, 3, "7_{lv}*200", "莉莉絲·情人節", "1_110021_20", 10, "7_200", "330230,330231,330232", "0", "0", "0", "0", "0", "0", "0", "0"},
[330240] = {330240, "寧特化精神增幅器", "由艾吉斯科學部為寧打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n為了最大限度發揮寧能力的優勢製作的頭飾，能有效緩解精神壓力。", "icon_dachuancunning_zs1", "0", 4, 1, "8_{lv}*200", "大川村寧", "1_110021_20", 10, "8_200", "330240,330241,330242", "0", "0", "0", "0", "0", "0", "0", "0"},
[330241] = {330241, "寧特製立場裝甲", "由艾吉斯科學部為寧打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n通過在制服上添加特殊的立場來擴大寧能力的搜索範圍，使得寧能看透大部分蒼霧。", "icon_dachuancunning_zs2", "0", 4, 2, "8_{lv}*200", "大川村寧", "1_110021_20", 10, "8_200", "330240,330241,330242", "0", "0", "0", "0", "0", "0", "0", "0"},
[330242] = {330242, "寧特製保護裝置", "由艾吉斯科學部為寧打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n為了初次上戰場的甯能順利地應對原罪，腿甲部分添加了“自動躲避原罪攻擊”的功能，該項能力會過量消耗能量，在生效三次之後請立刻退出戰場。", "icon_dachuancunning_zs3", "0", 4, 3, "8_{lv}*200", "大川村寧", "1_110021_20", 10, "8_200", "330240,330241,330242", "0", "0", "0", "0", "0", "0", "0", "0"},
[330250] = {330250, "渴慕混乱的隐性需求", "與其說是嶄新的AVG裝備，不如說是將弗蘭卡壓抑的內心釋放出來後的全新樣貌\n總是當一個安穩的乖孩子，對任何人來說都是一種奢望。", "icon_shengnvfulanka_zs1", "0", 4, 1, "8_{lv}*200", "弗蘭卡·小惡魔", "1_110021_20", 10, "8_200", "330250,330251,330252", "0", "0", "0", "0", "0", "0", "0", "0"},
[330251] = {330251, "希望节制的外在表现", "與其說是嶄新的AVG裝備，不如說是將弗蘭卡壓抑的內心釋放出來後的全新樣貌\n管控自己的慾望，堵塞永遠不如釋放。", "icon_shengnvfulanka_zs2", "0", 4, 2, "3_{lv}*200", "弗蘭卡·小惡魔", "1_110021_20", 10, "3_200", "330250,330251,330252", "0", "0", "0", "0", "0", "0", "0", "0"},
[330252] = {330252, "司掌平衡", "與其說是嶄新的AVG裝備，不如說是將弗蘭卡壓抑的內心釋放出來後的全新樣貌\n理智與衝動，當二者的重量持平時，人就會被引向正確的路。", "icon_shengnvfulanka_zs3", "0", 4, 3, "8_{lv}*200", "弗蘭卡·小惡魔", "1_110021_20", 10, "8_200", "330250,330251,330252", "0", "0", "0", "0", "0", "0", "0", "0"},
[330260] = {330260, "保護的精髓", "支援用的水槍，作用是……咦？為什麼明明是支援的裝備卻能對敵人造成有效的打擊？奇怪？\n最好的保護就是把敵人全部都殺光！媽媽會保護你們的！", "icon_buzhihuoyz_zs1", "0", 4, 1, "8_{lv}*200", "不知火·泳裝", "1_110021_20", 10, "8_200", "330260,330261,330262", "0", "0", "0", "0", "0", "0", "0", "0"},
[330261] = {330261, "育兒的經驗", "展開傘之後能形成極強的保護立場，甚至能隔絕噪音，據她所說能直接在保護立場裡面睡覺。\n考慮到可能會有帶著傘給領航膝枕的情況，不知火打算給傘再載入播放舒緩音樂的功能。", "icon_buzhihuoyz_zs2", "0", 4, 2, "3_{lv}*100", "不知火·泳裝", "1_110021_20", 10, "3_100", "330260,330261,330262", "0", "0", "0", "0", "0", "0", "0", "0"},
[330262] = {330262, "急速來到你身邊", "【不許傷害我的孩子們！】，把這個理念貫徹到底的裝備。在不知火最強盛的時候（她還是宇宙大災時）只要大聲喊出不知火的名字三次，不知火無視時間、空間來到你的身邊。\n她的“孩子”利用她的這項能力擊敗了她。", "icon_buzhihuoyz_zs3", "0", 4, 3, "3_{lv}*100", "不知火·泳裝", "1_110021_20", 10, "3_100", "330260,330261,330262", "0", "0", "0", "0", "0", "0", "0", "0"},
[330270] = {330270, "掌權者", "想要成爲家族的掌權者，對她來説並不是一件難事。無論是參謀，或是決定這艘船航行方向的船長，成爲什麽樣的人，只取決於她的个人意願。\n“我會成爲什麽樣的人，取決於您希望我成爲什麽樣的人，領航。”", "icon_faernaisisifu_zs1", "0", 4, 1, "8_{lv}*200", "法爾奈斯·禮服", "1_110021_20", 10, "8_200", "330270,330271,330272", "0", "0", "0", "0", "0", "0", "0", "0"},
[330271] = {330271, "暗宴", "和在學院時穿的服裝相比，這身衣服要更加符合她本人應有的身份——掌管一个地區産業的家族千金。\n“如何，這份美麗能觸及您的心靈嗎？”", "icon_faernaisisifu_zs2", "0", 4, 2, "8_{lv}*200", "法爾奈斯·禮服", "1_110021_20", 10, "8_200", "330270,330271,330272", "0", "0", "0", "0", "0", "0", "0", "0"},
[330272] = {330272, "夜色之吻", "黑暗中的秘密，往往只能通過親吻來傳達。\n當時刻步入黑暗，若不輕吻這寂靜便讓星光黯淡。", "icon_faernaisisifu_zs3", "0", 4, 3, "8_{lv}*200", "法爾奈斯·禮服", "1_110021_20", 10, "8_200", "330270,330271,330272", "0", "0", "0", "0", "0", "0", "0", "0"},
[330280] = {330280, "甜蜜魔力", "九州總部的某位愛吃糖果的研究員的嘔心瀝血之作，一把杖型武器。可以將尼姆比斯能轉換成類似糖漿的物質，可以食用，但是轉換過程中會散發驚人的熱量。\n“各種意義上可以讓熱量超標的魔法。”", "icon_qiaoke_zs1", "0", 4, 1, "8_{lv}*200", "巧可", "1_110021_20", 10, "8_200", "330280,330281,330282", "0", "0", "0", "0", "0", "0", "0", "0"},
[330281] = {330281, "巧克力與香草混合物", "九州總部的某位愛吃糖果的研究員的嘔心瀝血之作，按照巧可日常的服裝設計的防護裝甲。僅能提供有限的防護。\n 散發著香草巧克力般的氣味。", "icon_qiaoke_zs2", "0", 4, 2, "3_{lv}*200", "巧可", "1_110021_20", 10, "3_200", "330280,330281,330282", "0", "0", "0", "0", "0", "0", "0", "0"},
[330282] = {330282, "嗷嗚小賣部-分部", "九州總部的某位愛吃糖果的研究員的嘔心瀝血之作，作為巧可的臨時補給倉庫。外形上形似小拉車，功能上也差不多。\n嗷嗚小賣部，現在開業。", "icon_qiaoke_zs3", "0", 4, 3, "8_{lv}*200", "巧可", "1_110021_20", 10, "8_200", "330280,330281,330282", "0", "0", "0", "0", "0", "0", "0", "0"},
[340000] = {340000, "你是我最後的希望", "由星變OS幻化的AVG裝甲，根據星爍的心情變成了她喜歡的形狀。被幸運女神鐘愛的人啊，明天你將會死而復生。\n“你是我最後的希望，也是我最後的絕望。使我沉淪不得解脫”", "icon_wuzhuangxingshuo_zs1", "0", 4, 1, "1_{lv}*100", "星爍·星變奇蹟", "1_110021_20", 10, "1_100", "340000,340001,340002", "0", "0", "0", "0", "0", "0", "0", "0"},
[340001] = {340001, "幸運的代價", "由星變OS幻化的AVG裝甲，根據星爍的心情變成了她喜歡的形狀。尼姆比斯能從身體中溢出，突破了肉體的桎梏，在臂甲上凝結。\n“代價？以非人類的樣貌死去？……我早就脫離人類的範疇了。”", "icon_wuzhuangxingshuo_zs2", "0", 4, 2, "1_{lv}*100", "星爍·星變奇蹟", "1_110021_20", 10, "1_100", "340000,340001,340002", "0", "0", "0", "0", "0", "0", "0", "0"},
[340002] = {340002, "黎貝卡與萊薇", "由星變OS幻化的AVG裝甲，根據星爍的心情變成了她喜歡的形狀。星變OS的基因來源于黎貝卡和萊薇，這兩本武器正是她們力量的化身。\n來源於一場邂逅，起因是你。", "icon_wuzhuangxingshuo_zs3", "0", 4, 3, "1_{lv}*100", "星爍·星變奇蹟", "1_110021_20", 10, "1_100", "340000,340001,340002", "0", "0", "0", "0", "0", "0", "0", "0"},
[340010] = {340010, "斷水大劍", "珂斯嘉德的AVG武裝，以歷代教會騎士團長所傳承的大劍為原型設計。原本是雙手大劍，珂斯嘉德將自身的單手技藝融入使用，創造了獨一無二的劍法。\n據說此劍可斬開奔湧的流水而不癒合，故名“斷水”。", "icon_kesijiade_zs1", "0", 4, 1, "1_{lv}*100", "珂斯嘉德·恒淨之劍", "1_110021_20", 10, "1_100", "340010,340011,340012", "0", "0", "0", "0", "0", "0", "0", "0"},
[340011] = {340011, "立誓綢佈", "珂斯嘉德的AVG武裝，以教會騎士的立誓佈為原型設計的通訊器。每名教會騎士都會將立誓佈係在不同部位，珂斯嘉德選擇將其作為頭飾。\n頭部是與天空和宇宙最為接近之處，尤其是身處巨大化狀態時。", "icon_kesijiade_zs2", "0", 4, 2, "3_{lv}*100", "珂斯嘉德·恒淨之劍", "1_110021_20", 10, "3_100", "340010,340011,340012", "0", "0", "0", "0", "0", "0", "0", "0"},
[340012] = {340012, "雙泉護符", "珂斯嘉德的AVG武裝，以“雙泉護符”為原型設計的兩片裙甲，不僅能抵禦物理衝擊，也可釋放特殊力場減弱能量傷害。\n分別鑲嵌於這對護符中間的藍寶石，象徵著珀因雷德最早發現的兩處泉眼，因此有著特殊意義。", "icon_kesijiade_zs3", "0", 4, 3, "1_{lv}*100", "珂斯嘉德·恒淨之劍", "1_110021_20", 10, "1_100", "340010,340011,340012", "0", "0", "0", "0", "0", "0", "0", "0"},
[340020] = {340020, "村裡最好的衝浪板", "受到了領航的邀請，即將前往海濱樂園的奧菲莉亞，在全村最好的小賣部中買到的村裡最好的衝浪板，據說可以被當作在水中搏殺鯊魚的武器。\n糟、糟了！我完全不會衝浪！", "icon_spaofeiliya_zs1", "0", 4, 1, "1_{lv}*100", "奧菲莉亞·星之君主", "1_110021_20", 10, "1_100", "340020,340021,340022", "0", "0", "0", "0", "0", "0", "0", "0"},
[340021] = {340021, "勇氣頭套", "因為其他駕駛員和領航的目光太過熾烈，所以米菈隊長準備了能讓奧菲莉亞看不見周遭人視線的頭套。她騙奧菲莉亞說只要戴上就會擁有勇氣。\n戴著頭套的奧菲莉亞因為看不見，摔到了領航的身上，在弄清了事情原委之後米菈被關了禁閉。", "icon_spaofeiliya_zs2", "0", 4, 2, "1_{lv}*100", "奧菲莉亞·星之君主", "1_110021_20", 10, "1_100", "340020,340021,340022", "0", "0", "0", "0", "0", "0", "0", "0"},
[340022] = {340022, "不潔泳衣", "米菈隊長為奧菲莉亞準備的“攻略領航專用衣服”，本來只是想捉弄一下奧菲莉亞，沒想到奧菲莉亞因為“不想糟蹋隊友的心意”穿了出來。\n效果卓群。", "icon_spaofeiliya_zs3", "0", 4, 3, "1_{lv}*100", "奧菲莉亞·星之君主", "1_110021_20", 10, "1_100", "340020,340021,340022", "0", "0", "0", "0", "0", "0", "0", "0"},
[340030] = {340030, "代達洛斯之淚", "伊莉雅在記憶世界中獲得的武器，由復仇的怒火和痛苦的記憶凝結而成。用來擊殺原罪綽綽有餘，但是似乎還留有未知的作用等待伊莉雅去挖掘。\n她看到了那個無助的自己，流下了無助的淚。", "icon_shengdanyiliya_zs2", "0", 4, 1, "1_{lv}*100", "伊莉雅·寂滅者", "1_110021_20", 10, "1_100", "340030,340031,340032", "0", "0", "0", "0", "0", "0", "0", "0"},
[340031] = {340031, "心頭摯愛", "伊莉雅最喜歡的一件大衣，只有在最寒冷的時節才會穿上。甚至委託艾吉斯將其錄入藍圖作為自己新的戰鬥裝甲，然而實際防禦性能未知。\n便宜又暖和，是窮人的心頭愛。", "icon_shengdanyiliya_zs3", "0", 4, 2, "3_{lv}*100", "伊莉雅·寂滅者", "1_110021_20", 10, "3_100", "340030,340031,340032", "0", "0", "0", "0", "0", "0", "0", "0"},
[340032] = {340032, "不明生物U", "伊莉雅在冬季常戴的圍巾，圍巾的外形十分很可愛，看著像是某種毛茸茸的小動物。在錄入藍圖後加裝了最新的通訊和偵查模組，足以應對任何戰場情況。\n無人知曉什麼是“U”。", "icon_shengdanyiliya_zs1", "0", 4, 3, "3_{lv}*100", "伊莉雅·寂滅者", "1_110021_20", 10, "3_100", "340030,340031,340032", "0", "0", "0", "0", "0", "0", "0", "0"},
[340040] = {340040, "直到現在的喜歡你", "這是跨越了20年的思念。\n此時的查麗莎已經能坦然面對自己的內心。", "icon_spchalisha_zs1", "0", 4, 1, "1_{lv}*100", "查麗莎", "1_110021_20", 10, "1_100", "340040,340041,340042", "0", "0", "0", "0", "0", "0", "0", "0"},
[340041] = {340041, "尼德霍格", "史蒂芬妮博士留給查麗莎的最後之作。\n能100%發揮查麗莎能力的裝甲，此後，保持火種不熄將是查理莎身上背負的枷鎖。", "icon_spchalisha_zs2", "0", 4, 2, "1_{lv}*100", "查麗莎", "1_110021_20", 10, "1_100", "340040,340041,340042", "0", "0", "0", "0", "0", "0", "0", "0"},
[340042] = {340042, "成長的代價", "領航……你說我究竟有沒有成長為“英雄”呢。\n在人類潰敗之後，成為英雄什麼的……這樣的事情也諷刺了吧。", "icon_spchalisha_zs3", "0", 4, 3, "3_{lv}*100", "查麗莎", "1_110021_20", 10, "3_100", "340040,340041,340042", "0", "0", "0", "0", "0", "0", "0", "0"},
[340050] = {340050, "魔防隊制式帽", "由艾吉斯科學部為羽前京香打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n在戰鬥的時候會脫下帽子。", "icon_yuqianjingxiang_zs1", "0", 4, 1, "1_{lv}*100", "羽前京香", "1_110021_20", 10, "1_100", "340050,340051,340052", "0", "0", "0", "0", "0", "0", "0", "0"},
[340051] = {340051, "故鄉的發飾", "由艾吉斯科學部為羽前京香打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n那一天，永遠不會忘記！", "icon_yuqianjingxiang_zs2", "0", 4, 2, "1_{lv}*100", "羽前京香", "1_110021_20", 10, "1_100", "340050,340051,340052", "0", "0", "0", "0", "0", "0", "0", "0"},
[340052] = {340052, "京香的佩刀", "由艾吉斯科學部為羽前京香打造的AVG裝甲，按照她本人的意思完全保留了常規形態的樣式。\n為了握住刀站在戰場上，她付出了許多。", "icon_yuqianjingxiang_zs3", "0", 4, 3, "1_{lv}*100", "羽前京香", "1_110021_20", 10, "1_100", "340050,340051,340052", "0", "0", "0", "0", "0", "0", "0", "0"},
[340060] = {340060, "龍之勇者的象徵", "意義不明的鑰匙形狀的劍，和意義不明的在武器上的人臉，據說還會說話。\n劍和盾是勇者的標配，同理雕像也是勇者的標配，我把這兩個融合不就無敵了。劍就是我，盾就是我！", "icon_spred_zs1", "0", 4, 1, "1_{lv}*100", "red·繼承者", "1_110021_20", 10, "1_100", "340060,340061,340062", "0", "0", "0", "0", "0", "0", "0", "0"},
[340061] = {340061, "弱者才需要防具", "一點防禦力都沒有的比基尼，這麼裸露出身體的原因是——red可以憑藉感情無限地再生。\n“弱者才需要防具，比基尼只配強者擁有！”這麼說著這句話的red完全沒有意識到大家的比基尼都是帶著防禦系統的高級貨。", "icon_spred_zs2", "0", 4, 2, "3_{lv}*100", "red·繼承者", "1_110021_20", 10, "3_100", "340060,340061,340062", "0", "0", "0", "0", "0", "0", "0", "0"},
[340062] = {340062, "沙灘鎧甲？", "全身上下包裹得最嚴實的地方竟然是腳，為什麼？在沙灘上玩還需要穿著這麼厚的腳部鎧甲？\n為了讓你脫我衣服的時候有點成就感。啊？“你的腳被燜了這麼久一定很臭。”……？你找死！", "icon_spred_zs3", "0", 4, 3, "3_{lv}*100", "red·繼承者", "1_110021_20", 10, "3_100", "340060,340061,340062", "0", "0", "0", "0", "0", "0", "0", "0"},
[340070] = {340070, "統合式火力支援平臺", "根據伊斯卡拉過去的測試資料製造的奇特武器，根據她的需要，可以非常流暢地變成具備各種功能的樣子，甚至不局限於武器。\n幻化的特性讓這東西可以無視常規變形結構中的邏輯性部分，她似乎對此相當滿意。", "icon_yisikala_zs1", "0", 4, 1, "1_{lv}*100", "伊斯卡拉", "1_110021_20", 10, "1_100", "340070,340071,340072", "0", "0", "0", "0", "0", "0", "0", "0"},
[340071] = {340071, "妄想的殘留", "伊斯卡拉在巨大化過程中自然生成的服裝。乍看上去有些防護性問題，但她本人表示，大部分防禦性能被集中在了外面那件外套上。\n戈露卡說她曾在某本員工手冊的封底上見過這身衣服的草稿，這個說法目前已經無處考證。", "icon_yisikala_zs2", "0", 4, 2, "3_{lv}*100", "伊斯卡拉", "1_110021_20", 10, "3_100", "340070,340071,340072", "`", "0", "0", "0", "0", "0", "0", "0"},
[340072] = {340072, "額外戰備", "使用完全由尼姆比斯驅動的多功能武器平臺是不需要準備額外備彈的。伊斯卡拉用一堆即取即用的戰術裝備填上了這部分空間。\n絕對不是為了維持衣服必須配上裝具的視覺效果，絕對不是。", "icon_yisikala_zs3", "0", 4, 3, "3_{lv}*100", "伊斯卡拉", "1_110021_20", 10, "3_100", "340070,340071,340072", "0", "0", "0", "0", "0", "0", "0", "0"},
[340080] = {340080, "總組長的披風", "魔防隊總組長山城戀穿戴的披風。\n盡管本人並沒有特地強調這一點，但這件披風似乎已經成了總組長的象徵。", "icon_shanchenglian_zs1", "0", 4, 1, "3_{lv}*100", "山城戀", "1_110021_20", 10, "3_100", "340080,340081,340082", "0", "0", "0", "0", "0", "0", "0", "0"},
[340081] = {340081, "總組長的隊服", "魔防隊總組長山城戀的隊服，根據她个人喜好進行了適當的修改。\n相比起其他組長對服裝的改動，山城戀總組長的服裝並沒有做多麽夸張的改動，或許跟她的性格有關。", "icon_shanchenglian_zs2", "0", 4, 2, "3_{lv}*100", "山城戀", "1_110021_20", 10, "3_100", "340080,340081,340082", "0", "0", "0", "0", "0", "0", "0", "0"},
[340082] = {340082, "總組長特制腿甲", "魔防隊總組長山城戀日常行動時穿戴的鞾子。\n可能是爲了便於戰斗中會使用的踢技，總組長選擇了更適合發力的短鞾。", "icon_shanchenglian_zs3", "0", 4, 3, "1_{lv}*100", "山城戀", "1_110021_20", 10, "1_100", "340080,340081,340082", "0", "0", "0", "0", "0", "0", "0", "0"},
}
return RoleequipmentLocalData
